export const COMPILER_SOURCES = {
  "compiler.sld": ";; (scheme-js compiler) library\n;;\n;; The compiler's own Scheme: lowering the analyzed AST to IR (ir.scm), lifting\n;; closures (lift.scm), expanding primitives inline (inline.scm), liveness over\n;; frame spills (liveness.scm), generating JavaScript (emit.scm), deciding what\n;; to compile and why not (driver.scm, safety.scm), and when, for a program's\n;; own code as it runs (tier.scm).\n;;\n;; It is written with SRFI 1, SRFI 151 and SRFI 152 and imports them like any\n;; other program, so their private helpers stay private to them. What it needs from\n;; the interpreter, which is JavaScript, it imports from\n;; (scheme-js compiler host), src/compiler/host.js. The files are included in\n;; dependency order: each defines what the later ones call.\n;;\n;; The exports are the entry points JavaScript calls, through\n;; src/compiler/lowering.js, and the Scheme programs that import the library --\n;; the build steps and the compiler's harnesses, run from the CLI -- with the\n;; accessors of the records the entry points answer with. Everything else is\n;; internal, and the compiler's Scheme tests (tests/compiler/) reach it by\n;; running in this library's environment.\n;;\n;; The file is `compiler.sld` because every library resolver finds a library's\n;; file by the last part of its name.\n\n(define-library (scheme-js compiler)\n  (import (scheme base)\n          (only (scheme primitives) emergency-exit eval exit)\n          (scheme char)\n          (scheme cxr)\n          (srfi 1)\n          (srfi 151)\n          (srfi 152)\n          (scheme-js interop)\n          (scheme-js compiler host))\n  (export\n    ;; Lowering\n    lower-lambda control-globals\n    ;; Code generation\n    generate-unit inline-expansion-names js-name\n    ;; What to compile\n    compile-definition compile-expression compile-closure\n    generate-environment compile-environment compile-program\n    generate-lambda expression-thunk\n    program-unsafe-definitions\n    ;; What they answer with\n    generated? generated-name generated-closure generated-source generated-constants generated-globals\n    generated-env generated-library-globals\n    compiled? compiled-name compiled-procedure compiled-source\n    declined? declined-name declined-reason\n    program-run-compiled program-run-declined program-run-unsafe program-run-expressions\n    program-run-value\n    ;; The compiler's own failures, which leave their procedures interpreted\n    take-compiler-failures!\n    ;; A program's tier\n    make-tier tier-bound! tier-due! tier-top-level-procedure note-resume first-resume-to-ask)\n  (include \"ir.scm\" \"lift.scm\" \"inline.scm\" \"liveness.scm\" \"emit.scm\"\n           \"sourcemap.scm\" \"driver.scm\" \"safety.scm\" \"tier.scm\"))\n",
  "driver.scm": ";; The compiler's driver: which procedures are compiled, and each reason one\n;; is not.\n;;\n;; The passes before this file turn a lambda into JavaScript source; this one\n;; decides what to hand them and what to do with what comes back. A procedure\n;; is compiled when the compiler can express every form in it, and left to the\n;; interpreter otherwise, with a reason -- so the tier can grow a form at a\n;; time without any point at which the system is half correct, and the\n;; interpreter stays the reference semantics and the execution mode where\n;; generating code is not allowed.\n;;\n;; What it works on comes from the interpreter, which is JavaScript: analyzed\n;; forms, closures, environments. It reads and changes them only through\n;; `(scheme-js compiler host)` (src/compiler/host.js), and reads a form's\n;; contents as the tagged lists `ir.scm` lowers. JavaScript reaches the entry\n;; points -- `compile-definition`, `compile-expression`, `compile-closure`,\n;; `generate-environment`, `compile-environment`, `compile-program` -- through\n;; src/compiler/index.js, and reads the records they return as objects, one\n;; property per field.\n\n;; ---------------------------------------------------------------------------\n;; What compiling one procedure comes to\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * A procedure's JavaScript, generated and not yet made a procedure: what the\n;;  * build writes into the bundle, and what `instantiate-generated` turns into\n;;  * a procedure where generating code is allowed.\n;;  * @property {string} name - The name it was compiled under.\n;;  * @property {procedure|boolean} closure - The closure it was compiled from, or\n;;  *   #f.\n;;  * @property {object} env - The environment its globals resolve in.\n;;  * @property {object|boolean} span - Its source span, for the debugger, or #f.\n;;  * @property {string} source - The body of a function of the runtime `R`, the\n;;  *   environment `E` and the constant pool `K`.\n;;  * @property {list} constants - The constant pool.\n;;  * @property {list} globals - The globals it references, as symbols.\n;;  * @property {list} spans - The span of each of the source's lines, or #f,\n;;  *   which its source map is written from (`sourcemap.scm`).\n;;  * @property {list} library-globals - Those of its globals that are a\n;;  *   library's own bindings, as (key name . env) (`library-global-key` in\n;;  *   `ir.scm`): what a build that follows the code's references reads them\n;;  *   by.\n;;  */\n(define-record-type generated\n  (make-generated name closure env span source constants globals spans library-globals)\n  generated?\n  (name generated-name)\n  (closure generated-closure)\n  (env generated-env)\n  (span generated-span)\n  (source generated-source)\n  (constants generated-constants)\n  (globals generated-globals)\n  (spans generated-spans)\n  (library-globals generated-library-globals))\n\n;; /**\n;;  * A procedure compiled.\n;;  * @property {string} name - The name it was compiled under.\n;;  * @property {procedure} procedure - The compiled procedure.\n;;  * @property {string} source - Its generated source, for inspection.\n;;  */\n(define-record-type compiled\n  (make-compiled name procedure source)\n  compiled?\n  (name compiled-name)\n  (procedure compiled-procedure)\n  (source compiled-source))\n\n;; /**\n;;  * A procedure the compiler declined, and why.\n;;  * @property {string|boolean} name - Its name, or #f for an expression.\n;;  * @property {string} reason - Why.\n;;  * @property {string|boolean} source - Its source, when it was generated and\n;;  *   JavaScript would not take it; #f otherwise.\n;;  */\n(define-record-type declined\n  (make-declined name reason source)\n  declined?\n  (name declined-name)\n  (reason declined-reason)\n  (source declined-source))\n\n;; ---------------------------------------------------------------------------\n;; What the lowering reports\n;; ---------------------------------------------------------------------------\n;;\n;; `lower-lambda` answers a `lowering-failure`, or a `lowered-lambda` (both in\n;; `ir.scm`).\n\n;; /**\n;;  * The first control-transferring global among some globals, or #f: the\n;;  * forms there is no IR for, as `control-globals` in `ir.scm` names them.\n;;  * A library's binding is that by the name the code writes.\n;;  * @param {list} globals - Global names, as symbols.\n;;  * @param {list} [library-globals] - (key name . env) for each that is a\n;;  *   library's binding (`library-global-key` in ir.scm).\n;;  * @returns {symbol|boolean}\n;;  */\n(define (control-global-in globals . library-globals)\n  (control-global-among control-globals globals\n                        (if (pair? library-globals) (car library-globals) '())))\n\n;; /**\n;;  * The first of some globals, by the name the code writes, that is among\n;;  * some control globals, or #f.\n;;  * @param {list} controls - The control globals, as symbols.\n;;  * @param {list} globals - Global names, as symbols.\n;;  * @param {list} library-globals - (key name . env) for each that is a\n;;  *   library's binding.\n;;  * @returns {symbol|boolean}\n;;  */\n(define (control-global-among controls globals library-globals)\n  (find (lambda (name) (memq name controls))\n        (map (lambda (global) (global-written-name library-globals global)) globals)))\n\n;; /**\n;;  * Why a lowered procedure is not to be compiled, or #f if it is.\n;;  *\n;;  * A procedure that names `dynamic-wind`, `guard` or the like is declined\n;;  * because there is no IR for those forms, not because compiling it would be\n;;  * wrong. One that captures a continuation is compiled unless captures are\n;;  * declined: nearly every capture is an escape, which compiled code pays for\n;;  * easily, and one whose continuations are re-entered over and over is\n;;  * switched back to its closure as the program runs (`note-resume` in\n;;  * `tier.scm`).\n;;  *\n;;  * A control global where the code runs may be an ordinary procedure: a\n;;  * program built ahead of time has `dynamic-wind` as a procedure of\n;;  * (scheme-js winds), which keeps the winds itself, in the primitive's place\n;;  * (`library-primitives` in scripts/lib/ahead.scm).\n;;  *\n;;  * @param {lowered-lambda|lowering-failure} lowered - What `lower-lambda`\n;;  *   answered.\n;;  * @param {boolean} decline-captures? - Whether to decline a capture.\n;;  * @param {list} [ordinary] - The control globals that are ordinary\n;;  *   procedures where the code runs.\n;;  * @returns {string|boolean} The reason, or #f.\n;;  */\n(define (lowering-decline lowered decline-captures? . ordinary)\n  (cond\n    ((lowering-failure? lowered) (lowering-failure-reason lowered))\n    ((control-global-among (if (pair? ordinary)\n                               (lset-difference eq? control-globals (car ordinary))\n                               control-globals)\n                           (lowered-globals lowered) (lowered-library-globals lowered))\n     => (lambda (g) (string-append \"references control global '\" (symbol->string g) \"'\")))\n    ((and decline-captures? (lowered-captures? lowered))\n     \"captures a continuation, and captures are declined\")\n    (else #f)))\n\n;; ---------------------------------------------------------------------------\n;; What a form contains\n;; ---------------------------------------------------------------------------\n;;\n;; Read from the core forms `ir.scm` lowers. A form `ir.scm` does not lower --\n;; a reference to a library's own binding, `(other description)` -- is not\n;; looked into; the lowering declines such a form anyway, so what it contains\n;; cannot change whether it is compiled.\n\n;; /**\n;;  * The forms directly inside a form: its subexpressions, never a quoted\n;;  * literal's contents.\n;;  * @param {list} form - An analyzed form.\n;;  * @returns {list}\n;;  */\n(define (subforms form)\n  (case (ast-tag form)\n    ((if) (list (ast-1 form) (ast-2 form) (ast-3 form)))\n    ((seq) (ast-1 form))\n    ((lambda) (list (ast-4 form)))\n    ((let) (list (ast-2 form) (ast-3 form)))\n    ((letrec) (cons (ast-3 form) (ast-2 form)))\n    ((set define) (list (ast-2 form)))\n    ((app) (cons (ast-1 form) (ast-2 form)))\n    (else '())))\n\n;; /**\n;;  * Whether a form, or any form inside it, is one of some kinds.\n;;  * @param {list} tags - The kinds, as `ir.scm`'s tags.\n;;  * @param {list} form - An analyzed form.\n;;  * @returns {boolean}\n;;  */\n(define (contains-kind? tags form)\n  (let search ((form form))\n    (or (and (memq (ast-tag form) tags) #t)\n        (any search (subforms form)))))\n\n;; /**\n;;  * Whether a form makes a procedure or loops -- a named `let`, a `do` and a\n;;  * group of local procedures are all a `letrec` by now -- which is what makes\n;;  * compiling it worth what compiling costs.\n;;  * @param {list} form - An analyzed form.\n;;  * @returns {boolean}\n;;  */\n(define (makes-procedures-or-loops? form) (contains-kind? '(lambda letrec) form))\n\n;; /**\n;;  * Whether a form loops, here or in a procedure it makes.\n;;  * @param {list} form - An analyzed form.\n;;  * @returns {boolean}\n;;  */\n(define (contains-loop? form) (contains-kind? '(letrec) form))\n\n;; /**\n;;  * Whether a form defines at top level: a definition, or a `begin` whose\n;;  * definitions splice into the environment it runs in.\n;;  * @param {list} form - An analyzed form.\n;;  * @returns {boolean}\n;;  */\n(define (defines-at-top-level? form)\n  (case (ast-tag form)\n    ((define) #t)\n    ((seq) (any defines-at-top-level? (ast-1 form)))\n    (else #f)))\n\n;; /**\n;;  * Whether a form defines a procedure.\n;;  * @param {list} form - An analyzed form.\n;;  * @returns {boolean}\n;;  */\n(define (procedure-definition? form)\n  (and (eq? (ast-tag form) 'define) (eq? (ast-tag (ast-2 form)) 'lambda)))\n\n;; ---------------------------------------------------------------------------\n;; Generating a procedure\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * The largest generated source, in characters, a procedure may produce.\n;;  *\n;;  * A procedure is emitted twice, and so is every procedure nested inside it,\n;;  * once within each form of its parent, so a nested closure costs a multiple\n;;  * per level of nesting, measured at about 4.2x. Deep enough, that exceeds\n;;  * JavaScript's own maximum string length. A `let` used to be the worst case,\n;;  * since it reaches the compiler as an immediately applied lambda; lowering\n;;  * now turns those into bindings that nest nothing, which took the deepest\n;;  * procedure in the benchmark corpus from twenty-nine levels to seven. The\n;;  * bound stays for closures that really are nested, and costs nothing real:\n;;  * a procedure whose body is megabytes of JavaScript would not have been fast.\n;;  * @type {integer}\n;;  */\n(define max-source (* 4 1024 1024))\n\n;; /**\n;;  * Why a generated source is too large to keep, or #f if it is not.\n;;  * @param {string} source - The source.\n;;  * @returns {string|boolean}\n;;  */\n(define (source-too-large source)\n  (let ((size (string-length source)))\n    (and (> size max-source)\n         (string-append \"generated source is \" (number->string size) \" characters, over the \"\n                        (number->string max-source)\n                        \" limit; the procedure nests too deeply to emit twice\"))))\n\n;; /**\n;;  * The globals with an inline expansion.\n;;  * @type {list}\n;;  */\n(define expandable-globals (inline-expansion-names))\n\n;; /**\n;;  * The globals among a procedure's that may be expanded inline where it will\n;;  * run: those with an expansion that the environment still binds to the\n;;  * primitive the expansion reproduces -- for a library's binding, the\n;;  * library's environment. A program that has already redefined `car` must\n;;  * not have its `car` compiled as the primitive's.\n;;  * @param {list} globals - The procedure's globals, as symbols.\n;;  * @param {list} library-globals - (key name . env) for each that is a\n;;  *   library's binding.\n;;  * @param {object} env - The environment it will run in.\n;;  * @returns {list} The globals to expand.\n;;  */\n(define (guarded-globals globals library-globals env)\n  (filter (lambda (g)\n            (let* ((library (assq g library-globals))\n                   (name (if library (cadr library) g)))\n              (and (memq name expandable-globals)\n                   (bound-to-primitive? (if library (cddr library) env) (symbol->string name)))))\n          globals))\n\n;; /**\n;;  * Generates a lowered procedure's JavaScript.\n;;  * @param {lowered-lambda|lowering-failure} lowered - What `lower-lambda`\n;;  *   answered.\n;;  * @param {string} name - The name to compile it under.\n;;  * @param {procedure|boolean} closure - The closure it comes from, or #f.\n;;  * @param {object} env - The environment it will run in.\n;;  * @param {object|boolean} span - Its source span, or #f.\n;;  * @returns {generated|declined} The code, or why it is too large to keep.\n;;  */\n(define (emit-lowered lowered name closure env span)\n  (let* ((globals (lowered-globals lowered))\n         (library-globals (lowered-library-globals lowered))\n         (unit (generate-unit (lowered-ir lowered) globals library-globals name\n                              (guarded-globals globals library-globals env)))\n         (source (car unit)))\n    (cond ((source-too-large source) => (lambda (reason) (make-declined name reason #f)))\n          (else (make-generated name closure env span source (cadr unit) globals (caddr unit)\n                                library-globals)))))\n\n;; ---------------------------------------------------------------------------\n;; When the compiler fails\n;; ---------------------------------------------------------------------------\n;;\n;; The compiler is an optimization, so nothing it does may change what a\n;; program does. An error raised while it compiles a procedure is a bug of its\n;; own: the procedure is declined, and runs interpreted, and the failure is\n;; written to the error port -- the console on a page, standard error under the\n;; CLI -- and kept, so that the test suites, which run with the compiler on,\n;; fail on any. A procedure declined for a reason the compiler gives is no\n;; failure.\n\n;; The failures not yet taken, newest first, each as (name . message).\n(define compiler-failures '())\n\n;; /**\n;;  * The message an error raised in the compiler carries.\n;;  * @param {*} e - What was raised.\n;;  * @returns {string}\n;;  */\n(define (failure-message e)\n  (if (error-object? e) (error-object-message e) \"an object that is not an error was raised\"))\n\n;; /**\n;;  * Declines a procedure the compiler failed on, warning of it and keeping it.\n;;  * @param {string|boolean} name - The procedure's name, or #f.\n;;  * @param {*} e - What the compiler raised.\n;;  * @returns {declined}\n;;  */\n(define (compiler-failed name e)\n  (let ((message (failure-message e))\n        (port (current-error-port))\n        (named (if (string? name) name \"an expression\")))\n    (set! compiler-failures (cons (cons named message) compiler-failures))\n    (write-string (string-append \"scheme-js: the compiler failed on \" named\n                                 \", which runs interpreted instead. This is a bug in the compiler: \"\n                                 message \"\\n\")\n                  port)\n    (flush-output-port port)\n    (make-declined name (string-append \"the compiler failed: \" message) #f)))\n\n;; /**\n;;  * What a thunk that compiles a procedure answers, or the procedure declined\n;;  * if the compiler raises (`compiler-failed`). The one procedure here the\n;;  * compiler leaves interpreted when it compiles itself, since `guard` is a\n;;  * control form; what it calls is compiled.\n;;  * @param {string|boolean} name - The procedure's name, or #f.\n;;  * @param {procedure} thunk - The compiling.\n;;  * @returns {generated|compiled|declined}\n;;  */\n(define (unless-failing name thunk)\n  (guard (e (#t (compiler-failed name e)))\n    (thunk)))\n\n;; /**\n;;  * The compiler's failures since they were last taken, oldest first, each as\n;;  * (name . message); none are kept after.\n;;  * @returns {list}\n;;  */\n(define (take-compiler-failures!)\n  (let ((failures (reverse compiler-failures)))\n    (set! compiler-failures '())\n    failures))\n\n;; /**\n;;  * Lowers a lambda, as the tagged list `ir.scm` reads, and generates its\n;;  * JavaScript, raising if the compiler fails.\n;;  * @param {list} node - The lambda.\n;;  * @param {string} name - The name to compile it under.\n;;  * @param {procedure|boolean} closure - The closure it comes from, or #f.\n;;  * @param {object} env - The environment its globals resolve in.\n;;  * @param {object|boolean} span - Its source span, or #f.\n;;  * @param {boolean} decline-captures? - Whether to decline a capture.\n;;  * @param {list} [ordinary] - The control globals that are ordinary\n;;  *   procedures where the code runs (`lowering-decline`).\n;;  * @returns {generated|declined}\n;;  */\n(define (lower-and-emit node name closure env span decline-captures? . ordinary)\n  (let* ((lowered (lower-lambda node))\n         (reason (apply lowering-decline lowered decline-captures? ordinary)))\n    (if reason\n        (make-declined name reason #f)\n        (emit-lowered lowered name closure env span))))\n\n;; /**\n;;  * `lower-and-emit`, declining the procedure if the compiler fails.\n;;  * @returns {generated|declined}\n;;  */\n(define (generate-lambda node name closure env span decline-captures? . ordinary)\n  (unless-failing name\n    (lambda () (apply lower-and-emit node name closure env span decline-captures? ordinary))))\n\n;; /**\n;;  * A file's name as a place in a `scheme:///` URL: a name that is itself a\n;;  * URL -- a page's script with a `src` -- by its path, since its scheme and\n;;  * host would only be repeated inside another URL; any other as it is.\n;;  * @param {string} file - The name.\n;;  * @returns {string}\n;;  */\n(define (file-place file)\n  (let ((scheme-end (string-contains file \"://\")))\n    (let ((path (and scheme-end\n                     (string-index file (lambda (c) (char=? c #\\/)) (+ scheme-end 3)))))\n      (if path (substring file (+ path 1) (string-length file)) file))))\n\n;; /**\n;;  * Where generated code says it comes from, in a stack trace and in a\n;;  * debugger's list of sources: `scheme:///` and the file the procedure was\n;;  * read from (`file-place`) -- or else its library, or else the program --\n;;  * and the procedure's name. Without it an engine names the code by where\n;;  * `new Function` was called, the same for every procedure.\n;;  * @param {generated} code - The code.\n;;  * @returns {string} The URL.\n;;  */\n(define (source-url code)\n  (let* ((span (generated-span code))\n         (file (and span (span-file span)))\n         (library (environment-library (generated-env code)))\n         (place (cond (file (file-place file))\n                      ;; A library's name, which the host keeps as a vector of strings.\n                      (library (string-join (vector->list library) \"/\"))\n                      (else \"program\"))))\n    (string-append \"scheme:///\" (url-path-escape place) \"/\" (url-path-escape (generated-name code)))))\n\n;; /**\n;;  * How many lines the script `instantiate` makes has before the generated\n;;  * code: the two of the function `new Function` wraps a body in, `function\n;;  * anonymous(R,E,K` and `) {`, and the `'use strict';` before the body\n;;  * (`instantiate` in `host.js`).\n;;  */\n(define lines-before-generated-code 3)\n\n;; /**\n;;  * Generated code as the script it runs as: named for a debugger by\n;;  * `source-url`, and with its source map where it has one. Only as a program\n;;  * runs: the build writes the same code into a module, whose own URL it has.\n;;  * @param {generated} code - The code.\n;;  * @returns {string}\n;;  */\n(define (script-of code)\n  (let ((map (source-map (generated-spans code) lines-before-generated-code source-text)))\n    (string-append (generated-source code)\n                   \"\\n//# sourceURL=\" (source-url code)\n                   (if map (string-append \"\\n//# sourceMappingURL=\" (source-map-url map)) \"\"))))\n\n;; /**\n;;  * Makes generated code a procedure.\n;;  * @param {generated} code - The code.\n;;  * @returns {compiled|declined} The procedure, with the script it was made\n;;  *   from, or why JavaScript would not take the code.\n;;  */\n(define (instantiate-generated code)\n  (let* ((script (script-of code))\n         (procedure (instantiate script (generated-env code) (generated-constants code) (generated-span code))))\n    (if (string? procedure)\n        (make-declined (generated-name code) procedure script)\n        (make-compiled (generated-name code) procedure script))))\n\n;; /**\n;;  * Compiles a lambda: `lower-and-emit`, then `instantiate-generated`,\n;;  * declining the procedure if the compiler fails in either.\n;;  * @returns {compiled|declined}\n;;  */\n(define (compile-lambda node name closure env span decline-captures?)\n  (unless-failing name\n    (lambda ()\n      (let ((result (lower-and-emit node name closure env span decline-captures?)))\n        (if (generated? result) (instantiate-generated result) result)))))\n\n;; ---------------------------------------------------------------------------\n;; Definitions, expressions and closures\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Compiles a top-level procedure definition.\n;;  * @param {object} node - The analyzed definition.\n;;  * @param {object} env - The environment it belongs to.\n;;  * @param {boolean} decline-captures? - Whether to decline a capture.\n;;  * @returns {compiled|declined}\n;;  */\n(define (compile-definition node env decline-captures?)\n  (let ((form (ast->scheme node)))\n    (cond\n      ((not (eq? (ast-tag form) 'define)) (make-declined #f \"not a top-level definition\" #f))\n      ((not (eq? (ast-tag (ast-2 form)) 'lambda))\n       (make-declined (symbol->string (ast-1 form)) \"definition is not a procedure\" #f))\n      (else (compile-lambda (ast-2 form) (symbol->string (ast-1 form)) #f env\n                            (definition-span node) decline-captures?)))))\n\n;; /**\n;;  * A top-level expression as a lambda of no arguments, to call once.\n;;  * @param {list} form - The expression, as `ir.scm` reads it.\n;;  * @returns {list} The lambda.\n;;  */\n(define (expression-thunk form) (list 'lambda '() #f \"top-level\" form))\n\n;; /**\n;;  * Compiles a top-level expression, or the value of a definition that is not\n;;  * a procedure, as a procedure of no arguments to call once.\n;;  *\n;;  * A program's own procedures are often not top-level definitions at all:\n;;  * `benchmarks/r7rs/src/nboyer.scm` defines stubs, then assigns every real\n;;  * procedure from inside one top-level `(let () ...)`, so compiling\n;;  * definitions alone left the whole program interpreted. A definition whose\n;;  * value is made by an expression -- a closure over a table, say -- is the\n;;  * same case.\n;;  *\n;;  * Declined, and so interpreted: a form that defines at top level, since in a\n;;  * procedure its definitions would become internal ones, and one that makes no\n;;  * procedure and has no loop, since straight-line code runs once and\n;;  * compiling it costs more than running it.\n;;  *\n;;  * @param {object} node - The analyzed expression.\n;;  * @param {object} env - The environment its globals resolve in.\n;;  * @param {string|boolean} name - The definition it is the value of, or #f.\n;;  * @param {boolean} decline-captures? - Whether to decline a capture.\n;;  * @returns {compiled|declined} The outcome; a compiled procedure is the thunk.\n;;  */\n(define (compile-expression node env name decline-captures?)\n  (compile-expression-form (ast->scheme node) env (ast-span node) name decline-captures?))\n\n;; /**\n;;  * `compile-expression`, for a form already read as `ir.scm` reads it.\n;;  * @param {list} form - The expression.\n;;  * @param {object} env - The environment its globals resolve in.\n;;  * @param {object|boolean} span - Its source span, or #f.\n;;  * @param {string|boolean} name - The definition it is the value of, or #f.\n;;  * @param {boolean} decline-captures? - Whether to decline a capture.\n;;  * @returns {compiled|declined}\n;;  */\n(define (compile-expression-form form env span name decline-captures?)\n  (cond\n    ((defines-at-top-level? form) (make-declined name \"defines at top level\" #f))\n    ((not (makes-procedures-or-loops? form))\n     (make-declined name \"makes no procedure and has no loop, so runs once\" #f))\n    (else (compile-lambda (expression-thunk form) \"top-level\" #f env span decline-captures?))))\n\n;; /**\n;;  * Compiles an interpreted closure, in its own environment, so its free\n;;  * variables resolve as they did when it was interpreted: a library\n;;  * procedure's globals live in that library's environment, not the program's.\n;;  * @param {procedure} closure - The closure.\n;;  * @param {string} name - The name to compile it under.\n;;  * @param {boolean} decline-captures? - Whether to decline a capture.\n;;  * @returns {compiled|declined}\n;;  */\n(define (compile-closure closure name decline-captures?)\n  (if (interpreted-closure? closure)\n      (compile-lambda (closure-lambda closure name) name closure (closure-environment closure)\n                      (closure-span closure) decline-captures?)\n      (make-declined name \"not an interpreted closure\" #f)))\n\n;; ---------------------------------------------------------------------------\n;; An environment's procedures\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Whether a closure was made in an environment or a scope inside it. A\n;;  * procedure a library imported closes over the library that defined it,\n;;  * which is never inside this one.\n;;  * @param {procedure} closure - An interpreted closure.\n;;  * @param {object} env - The environment.\n;;  * @returns {boolean}\n;;  */\n(define (defined-within? closure env)\n  (let walk ((scope (closure-environment closure)))\n    (and scope (or (eq? scope env) (walk (environment-parent scope))))))\n\n;; /**\n;;  * Whether a closure was made at the top level of a program or a library,\n;;  * rather than inside a procedure or a `let`. One made inside closes over\n;;  * locals, which generated code reaches by their names, and a local's name\n;;  * carries the counter the expander renamed it with in this run: code\n;;  * generated for a prebuilt table, in one run, would look for it under a name\n;;  * that the run installing the table did not give it.\n;;  * @param {procedure} closure - An interpreted closure.\n;;  * @returns {boolean}\n;;  */\n(define (made-at-top-level? closure)\n  (let ((scope (closure-environment closure)))\n    (if (or (not (environment-parent scope)) (environment-library scope)) #t #f)))\n\n;; /**\n;;  * The interpreted closures an environment binds, as (name . closure) with the\n;;  * name a symbol, in the environment's order.\n;;  * @param {object} env - The environment.\n;;  * @param {boolean} own-only? - Only those made in the environment itself,\n;;  *   leaving out what it imported: a library's environment holds a copy of\n;;  *   everything it imports, and a table built for one library must not carry\n;;  *   a second compiled copy of another's procedures.\n;;  * @returns {list}\n;;  */\n(define (environment-closures env own-only?)\n  (filter-map (lambda (binding)\n                (let ((value (cdr binding)))\n                  (and (interpreted-closure? value)\n                       (or (not own-only?) (defined-within? value env))\n                       (cons (string->symbol (car binding)) value))))\n              (environment-bindings env)))\n\n;; /**\n;;  * Generates code for every procedure in an environment worth compiling,\n;;  * without making procedures of it.\n;;  *\n;;  * Separate from making them so that one policy serves both callers: the\n;;  * build step that writes generated source into the bundle, and\n;;  * `compile-environment`, which makes the procedures at once. Two answers to\n;;  * \"which procedures do we compile\" would drift, and the build's has to match\n;;  * the running system's or the bundle would hold code for procedures the\n;;  * system does not expect.\n;;  *\n;;  * @param {object} env - The environment.\n;;  * @param {boolean} own-only? - As for `environment-closures`.\n;;  * @param {boolean} decline-captures? - Decline every procedure a capture\n;;  *   could unwind through, and every one that captures (`safety.scm`).\n;;  * @param {boolean} strict? - With it, also decline one that calls a callee it\n;;  *   cannot name.\n;;  * @returns {pair} `(generated . declined)`, each in the environment's order.\n;;  */\n(define (generate-environment env own-only? decline-captures? strict?)\n  (let* ((closures (environment-closures env own-only?))\n         (unsafe (if decline-captures? (unsafe-closures closures env strict?) '())))\n    (define (attempt entry)\n      (let ((name (symbol->string (car entry)))\n            (closure (cdr entry)))\n        (cond ((assq (car entry) unsafe) => (lambda (u) (make-declined name (cdr u) #f)))\n              ((not (made-at-top-level? closure))\n               (make-declined name\n                              (string-append \"made inside a procedure, so it closes over that \"\n                                             \"procedure's locals, which generated code finds by \"\n                                             \"the names this run's renaming gave them\")\n                              #f))\n              (else (generate-lambda (closure-lambda closure name) name closure\n                                     (closure-environment closure) (closure-span closure)\n                                     decline-captures?)))))\n    (call-with-values (lambda () (partition generated? (map attempt closures))) cons)))\n\n;; /**\n;;  * Compiles the interpreted procedures already in an environment, replacing\n;;  * each in place.\n;;  *\n;;  * The standard library is loaded and interpreted before anything considers\n;;  * compiling it, so it cannot be compiled from source; a closure keeps its\n;;  * parameters, body and environment, so it can be compiled afterwards\n;;  * instead. `memq`, `assq`, `map` and `assoc` are themselves Scheme, and a\n;;  * compiled procedure calling one interpreted crosses into the interpreter on\n;;  * what is often its hottest path: on the compiler's own lowering, compiling\n;;  * the library too was worth 10.8x. Callers pick up each compiled procedure\n;;  * without being compiled again: they hold the closure, which runs compiled.\n;;  *\n;;  * @param {object} env - The environment.\n;;  * @param {boolean} strict? - As for `generate-environment`.\n;;  * @returns {pair|boolean} `(compiled . declined)`, or #f if generating code\n;;  *   is not permitted here, so everything stays interpreted.\n;;  */\n(define (compile-environment env strict?)\n  (and (code-generation-allowed?)\n       (let* ((generation (generate-environment env #f #f strict?))\n              (codes (car generation))\n              (outcomes (map (lambda (code)\n                               (unless-failing (generated-name code)\n                                               (lambda () (instantiate-generated code))))\n                             codes))\n              (replaced (filter-map (lambda (code outcome)\n                                      (and (compiled? outcome)\n                                           (cons (generated-closure code) (compiled-procedure outcome))))\n                                    codes outcomes)))\n         ;; Each closure runs compiled, staying the object whatever holds it\n         ;; has -- a library that imported it, a value made with it -- and is\n         ;; recorded for a debugger to run as itself.\n         (for-each (lambda (pair) (run-compiled! (car pair) (cdr pair))) replaced)\n         (record-compiled-over! replaced env)\n         (cons (filter compiled? outcomes) (append (cdr generation) (remove compiled? outcomes))))))\n\n;; ---------------------------------------------------------------------------\n;; A program\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * What running one top-level form of a program came to.\n;;  * @property {symbol} kind - `procedure` for a procedure definition,\n;;  *   `expression` for a form compiled as a thunk and called, `interpreted`\n;;  *   for one the interpreter ran.\n;;  * @property {compiled|declined} outcome - What compiling it came to.\n;;  * @property {*} value - Its value; undefined for a definition.\n;;  */\n(define-record-type step\n  (make-step kind outcome value)\n  step?\n  (kind step-kind)\n  (outcome step-outcome)\n  (value step-value))\n\n;; /**\n;;  * What compiling a program came to.\n;;  * @property {list} compiled - The procedures compiled, by name.\n;;  * @property {list} declined - Each definition declined.\n;;  * @property {list} unsafe - What the capture rule declined, as (name .\n;;  *   reason) with the name a symbol; empty unless it was asked for.\n;;  * @property {integer} expressions - How many forms were compiled as thunks.\n;;  * @property {*} value - The last form's value.\n;;  */\n(define-record-type program-run\n  (make-program-run compiled declined unsafe expressions value)\n  program-run?\n  (compiled program-run-compiled)\n  (declined program-run-declined)\n  (unsafe program-run-unsafe)\n  (expressions program-run-expressions)\n  (value program-run-value))\n\n;; /**\n;;  * Runs one top-level form, compiling it first where that is worth it.\n;;  *\n;;  * A procedure definition runs as the interpreter runs it, and is then\n;;  * compiled from the closure that made, so that the pair is recorded: a\n;;  * debugger runs the closure while the program is debugged, and a procedure\n;;  * whose continuations are re-entered is switched back to it for good. Any\n;;  * other form is compiled as a thunk and called once where\n;;  * `compile-expression` accepts it, and run by the interpreter otherwise.\n;;  *\n;;  * @param {object} node - The analyzed form.\n;;  * @param {object} env - The program's environment.\n;;  * @param {object} interpreter - The interpreter.\n;;  * @param {list} unsafe - What the capture rule declined.\n;;  * @param {boolean} decline-captures? - Whether to decline a capture.\n;;  * @returns {step}\n;;  */\n(define (run-top-level node env interpreter unsafe decline-captures?)\n  (let* ((form (ast->scheme node))\n         (name (and (eq? (ast-tag form) 'define) (symbol->string (ast-1 form))))\n         (ruled-out (and name (assq (ast-1 form) unsafe))))\n    (cond\n      ((procedure-definition? form)\n       (run-form interpreter node env)\n       (let* ((closure (environment-value env name))\n              (outcome (if ruled-out\n                           (make-declined name (cdr ruled-out) #f)\n                           (compile-closure closure name decline-captures?))))\n         (if (compiled? outcome)\n             (let ((procedure (compiled-procedure outcome)))\n               (run-compiled! closure procedure)\n               (record-compiled-over! (list (cons closure procedure)) env)))\n         (make-step 'procedure outcome js-undefined)))\n      (else\n       (let ((outcome (if ruled-out\n                          (make-declined name (cdr ruled-out) #f)\n                          (compile-expression-form (if name (ast-2 form) form) env\n                                                   (if name (definition-span node) (ast-span node))\n                                                   name decline-captures?))))\n         (cond\n           ((not (compiled? outcome)) (make-step 'interpreted outcome (run-form interpreter node env)))\n           (name\n            (environment-define! env name (run-thunk interpreter env (compiled-procedure outcome)))\n            (make-step 'expression outcome js-undefined))\n           (else\n            (make-step 'expression outcome (run-thunk interpreter env (compiled-procedure outcome))))))))))\n\n;; /**\n;;  * Runs a program's top-level forms in order, compiling what is worth it as\n;;  * it goes: in one pass, so the forms run in the program's order.\n;;  *\n;;  * @param {vector} nodes - The analyzed top-level forms, in order.\n;;  * @param {object} env - The environment to define into.\n;;  * @param {object} interpreter - The interpreter.\n;;  * @param {boolean} decline-captures? - As for `generate-environment`,\n;;  *   decided over the whole program before anything runs, since the answer\n;;  *   for one procedure depends on what its callees do.\n;;  * @param {boolean} strict? - As for `generate-environment`.\n;;  * @returns {program-run}\n;;  */\n(define (compile-program nodes env interpreter decline-captures? strict?)\n  (let* ((nodes (vector->list nodes))\n         (unsafe (if decline-captures? (unsafe-definitions (map ast->scheme nodes) env strict?) '()))\n         (steps (let run ((nodes nodes) (steps '()))\n                  (if (null? nodes)\n                      (reverse steps)\n                      (run (cdr nodes)\n                           (cons (run-top-level (car nodes) env interpreter unsafe decline-captures?)\n                                 steps)))))\n         (outcomes (map step-outcome steps)))\n    (make-program-run\n      (map compiled-name\n           (filter compiled? (map step-outcome (filter (lambda (s) (eq? (step-kind s) 'procedure)) steps))))\n      (filter (lambda (o) (and (declined? o) (declined-name o))) outcomes)\n      unsafe\n      (count (lambda (s) (eq? (step-kind s) 'expression)) steps)\n      (if (null? steps) js-undefined (step-value (last steps))))))\n",
  "emit.scm": ";;; emit.scm -- JavaScript for a lowered procedure.\n;;;\n;;; ## Two forms of every procedure\n;;;\n;;; A compiled procedure runs as straight-line JavaScript -- the *fast form*:\n;;; ordinary `if`s, a non-tail call as a JavaScript call, a tail call made as a\n;;; JavaScript call too while the stack allows and otherwise returned to the\n;;; trampoline as a `TailCall`. One live Scheme frame is one JavaScript frame,\n;;; which is what lets a debugger show a Scheme stack.\n;;;\n;;; A JavaScript function cannot be resumed part-way through, and Scheme needs\n;;; exactly that when a continuation captured beneath a compiled frame is\n;;; invoked. So each procedure is also emitted as its *resumable form*, the\n;;; twin: the same body as a state machine,\n;;;\n;;;     function name$r($pc, $f) {\n;;;       let a, $t1, ..., $r;\n;;;       ({ a, $t1, ..., $r } = $f);\n;;;       for (;;) switch ($pc) {\n;;;         case 0: ...            // ordinary entry\n;;;         case 1: $t3 = $r; ...  // resumed just after call site 1\n;;;       }\n;;;     }\n;;;\n;;; in which every branch and every call ends a block, so every point the\n;;; procedure can be suspended at begins one. When a callee reports a capture,\n;;; the fast form saves its live locals and the block to resume at, and\n;;; returns; the twin later restores them and carries on. The arrangement is\n;;; Marshall's, after Pettyjohn et al.: a capture is signalled by *returning* a\n;;; distinguished value rather than throwing, which costs orders of magnitude\n;;; less on a JavaScript engine.\n;;;\n;;; The two forms differ only in control flow -- `if`, calls, captures, loop\n;;; heads -- so one emitter produces both, with a mode. Everything else is the\n;;; same code, and that is what keeps them agreeing: the fast form spills\n;;; locals by name into a frame the twin restores by name, so both must give\n;;; every value the same name, and they do because they allocate names in the\n;;; same order.\n;;;\n;;; ## Statements are data\n;;;\n;;; The emitter builds statements as tagged lists and renders them to text\n;;; last. An expression is a list of parts: a string is JavaScript text, and a\n;;; symbol is a local the frame can hold. So which locals a statement reads is\n;;; in the data, and the liveness that decides what a frame saves reads it\n;;; there rather than scanning text -- where a local's name inside a string\n;;; literal used to count as a read.\n;;;\n;;;   (assign target expr)     target = expr;   (a symbol target defines it)\n;;;   (eval expr)              expr;\n;;;   (return expr)            return expr;\n;;;   (raw expr)               a statement written out whole, such as a loop\n;;;   (text string)            a fixed line: a loop label, a closing brace\n;;;   (if test then else)      a JavaScript if, in the fast form only\n;;;   (goto n)                 $pc = n; continue;\n;;;   (branch test n m)        to block n if test is not #f, else to m\n;;;   (spill result n)         if result is the unwind sentinel, save the frame\n;;;                            to resume at block n and return; with result #f,\n;;;                            unconditionally\n;;;   (guarded test stmts)     if (test) { stmts }, for a guarded loop jump\n;;;   (suspend result n slots) the fast form's spill, into its twin's block n\n;;;   (tail callee args entry) a tail call, made directly to the callee's raw\n;;;                            entry, which `entry` holds, or returned to the\n;;;                            trampoline; it returns either way\n;;;\n;;; ## Nested procedures\n;;;\n;;; Every nested lambda is emitted once, at the top of the unit, as a factory\n;;; over its free variables (`lift.scm`), and created by calling it. Both forms\n;;; of a parent ask for the same node and get the same factory.\n\n;; ---------------------------------------------------------------------------\n;; JavaScript text\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Each renamed Scheme local's JavaScript identifier, once worked out. A local\n;;  * is named wherever the code reads it, and working the name out again each\n;;  * time was about 6% of compiling the canonical programs under the tier.\n;;  */\n(define js-names (make-weak-table))\n\n;; /**\n;;  * The JavaScript identifier for a renamed Scheme local.\n;;  * @param {symbol} name - A renamed Scheme identifier.\n;;  * @returns {string} A JavaScript identifier.\n;;  */\n(define (js-name name)\n  (or (weak-table-ref js-names name)\n      (let ((text (javascript-identifier name)))\n        (weak-table-set! js-names name text)\n        text)))\n\n;; /**\n;;  * Works out the JavaScript identifier for a renamed Scheme local. The\n;;  * expander's names look like `x_$147`, already close; any character\n;;  * JavaScript does not allow in an identifier becomes `_` and its code in hex.\n;;  * @param {symbol} name - A renamed Scheme identifier.\n;;  * @returns {string} A JavaScript identifier.\n;;  */\n(define (javascript-identifier name)\n  (define (plain? c)\n    (or (char-alphabetic? c) (char-numeric? c) (char=? c #\\_) (char=? c #\\$)))\n  (define (ascii-plain? c) (and (< (char->integer c) 128) (plain? c)))\n  (let ((s (symbol->string name)))\n    (string-append\n      \"s_\"\n      (if (string-every ascii-plain? s)\n          s\n          (apply string-append\n                 (map (lambda (c)\n                        (if (ascii-plain? c)\n                            (string c)\n                            (string-append \"_\" (number->string (char->integer c) 16))))\n                      (string->list s)))))))\n\n;; /**\n;;  * The symbol that stands for a Scheme local in an expression.\n;;  * @param {symbol} name - A renamed Scheme identifier.\n;;  * @returns {symbol} Its JavaScript name, as a symbol.\n;;  */\n(define (js-local name) (string->symbol (js-name name)))\n\n;; /**\n;;  * A string as a JavaScript string literal, escaped as `JSON.stringify` does.\n;;  * @param {string} s - The string.\n;;  * @returns {string} The literal.\n;;  */\n(define (js-string s)\n  (let ((out (open-output-string)))\n    (write-char #\\\" out)\n    (string-for-each\n      (lambda (c)\n        (let ((code (char->integer c)))\n          (cond ((char=? c #\\\") (write-string \"\\\\\\\"\" out))\n                ((char=? c #\\\\) (write-string \"\\\\\\\\\" out))\n                ((= code 8) (write-string \"\\\\b\" out))\n                ((= code 9) (write-string \"\\\\t\" out))\n                ((= code 10) (write-string \"\\\\n\" out))\n                ((= code 12) (write-string \"\\\\f\" out))\n                ((= code 13) (write-string \"\\\\r\" out))\n                ((< code 32)\n                 (write-string \"\\\\u00\" out)\n                 (if (< code 16) (write-char #\\0 out))\n                 (write-string (number->string code 16) out))\n                (else (write-char c out)))))\n      s)\n    (write-char #\\\" out)\n    (get-output-string out)))\n\n;; /**\n;;  * A flonum as a JavaScript number literal. Scheme writes an integral flonum\n;;  * as `1.0`, which JavaScript reads the same, but JavaScript's own spelling\n;;  * drops the `.0`, and that is kept. The infinities and NaN have no literal.\n;;  * @param {number} x - An inexact real.\n;;  * @returns {string} A JavaScript expression.\n;;  */\n(define (js-number x)\n  (cond ((not (= x x)) \"Number(\\\"NaN\\\")\")\n        ((= x (/ 1. 0)) \"Number(\\\"Infinity\\\")\")\n        ((= x (/ -1. 0)) \"Number(\\\"-Infinity\\\")\")\n        (else (let* ((s (number->string x))\n                     (n (string-length s)))\n                (if (and (> n 2) (string=? (substring s (- n 2) n) \".0\"))\n                    (substring s 0 (- n 2))\n                    s)))))\n\n;; ---------------------------------------------------------------------------\n;; Expressions and statements\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Builds an expression from parts: strings, locals as symbols, integers,\n;;  * and other expressions, which are spliced in.\n;;  * @param {...*} parts - The parts.\n;;  * @returns {list} The expression.\n;;  */\n(define (js . parts)\n  (append-map (lambda (part)\n                (cond ((or (string? part) (symbol? part)) (list part))\n                      ((number? part) (list (number->string part)))\n                      (else part)))\n              parts))\n\n;; /**\n;;  * An expression rendered as JavaScript text.\n;;  * @param {list} expr - The expression.\n;;  * @returns {string} Its text.\n;;  */\n(define (expr->string expr)\n  (apply string-append\n         (map (lambda (part) (if (symbol? part) (symbol->string part) part)) expr)))\n\n;; /**\n;;  * The locals an expression reads.\n;;  * @param {list} expr - The expression.\n;;  * @returns {list} The symbols in it.\n;;  */\n(define (expr-locals expr) (filter symbol? expr))\n\n;; /**\n;;  * Whether an expression is a literal or a lone variable -- something that\n;;  * can be written twice without evaluating anything twice.\n;;  * @param {list} expr - The expression.\n;;  * @returns {boolean}\n;;  */\n(define (repeatable? expr)\n  (and (pair? expr)\n       (null? (cdr expr))\n       (or (symbol? (car expr)) (literal-text? (car expr)))))\n\n;; /**\n;;  * Whether an expression is a literal, or a temporary: something no parameter\n;;  * assignment can change, so a loop's jump can assign it without first\n;;  * copying it aside.\n;;  * @param {list} expr - The expression.\n;;  * @returns {boolean}\n;;  */\n(define (settled? expr)\n  (and (pair? expr)\n       (null? (cdr expr))\n       (if (symbol? (car expr))\n           (temporary? (car expr))\n           (or (literal-text? (car expr)) (string=? (car expr) \"undefined\")))))\n\n;; /**\n;;  * Whether a symbol names one of this emitter's temporaries, `$t` and digits.\n;;  * @param {symbol} sym - A local.\n;;  * @returns {boolean}\n;;  */\n(define (temporary? sym)\n  (let ((s (symbol->string sym)))\n    (and (> (string-length s) 2)\n         (string=? (substring s 0 2) \"$t\")\n         (string-every char-numeric? (substring s 2 (string-length s))))))\n\n;; /**\n;;  * Whether text is a literal the emitter writes inline: an exact integer, a\n;;  * `null`/`true`/`false`, or a reference into the constant pool.\n;;  * @param {string} s - The text.\n;;  * @returns {boolean}\n;;  */\n(define (literal-text? s)\n  (define (digits? str) (and (> (string-length str) 0) (string-every char-numeric? str)))\n  (let ((n (string-length s)))\n    (or (member s '(\"null\" \"true\" \"false\"))\n        (let* ((unsigned (if (and (> n 0) (char=? (string-ref s 0) #\\-)) (substring s 1 n) s))\n               (m (string-length unsigned)))\n          (or (digits? unsigned)\n              (and (> m 1) (char=? (string-ref unsigned (- m 1)) #\\n)\n                   (digits? (substring unsigned 0 (- m 1))))))\n        (and (> n 3)\n             (string=? (substring s 0 2) \"K[\")\n             (char=? (string-ref s (- n 1)) #\\])\n             (digits? (substring s 2 (- n 1)))))))\n\n;; /**\n;;  * A statement as a line of JavaScript: any but the fast form's `if`, whose\n;;  * branches are lines of their own (`statement-lines`).\n;;  * @param {form} form - The emission it belongs to, which names the\n;;  *   procedure and says what a spill saves.\n;;  * @param {list} st - The statement.\n;;  * @returns {string} Its text.\n;;  */\n(define (render-statement form st)\n  (let ((expr (lambda (e) (expr->string e)))\n        (unwind (lambda () (runtime form '$UNWIND))))\n    (case (car st)\n      ((assign) (string-append (expr (cadr st)) \" = \" (expr (caddr st)) \";\"))\n      ((eval) (string-append (expr (cadr st)) \";\"))\n      ((return) (string-append \"return \" (expr (cadr st)) \";\"))\n      ((raw) (expr (cadr st)))\n      ((text) (cadr st))\n      ((goto) (goto-text (cadr st)))\n      ((branch) (string-append \"if (\" (expr (cadr st)) \" !== false) { \"\n                               (goto-text (caddr st)) \" } \" (goto-text (cadddr st))))\n      ((spill)\n       (let ((reify (string-append \"R.reify(\" (form-name form) \", \"\n                                   (number->string (caddr st)) \", \"\n                                   (frame-literal (form-frame form (caddr st))) \");\")))\n         (if (cadr st)\n             (string-append \"if (\" (expr (cadr st)) \" === \" (unwind) \") { \" reify \" return \" (unwind) \"; }\")\n             reify)))\n      ((guarded) (string-append \"if (\" (expr (cadr st)) \") { \"\n                                (string-join (map (lambda (s) (render-statement form s)) (caddr st)) \" \")\n                                \" }\"))\n      ((suspend)\n       (let ((spill (string-append \"R.reify(\" (form-name form) \"$r, \" (number->string (caddr st))\n                                   \", \" (frame-literal (cadddr st)) \"); return \" (unwind) \";\")))\n         (if (cadr st)\n             (string-append \"if (\" (expr (cadr st)) \" === \" (unwind) \") { \" spill \" }\")\n             spill)))\n      ((tail)\n       (let* ((callee (expr (cadr st)))\n              (entry (expr (cadddr st)))\n              (arglist (string-join (map expr (caddr st)) \", \"))\n              (fallback (string-append \"return \" (runtime form '$tailCall) \"(\" callee \", [\" arglist \"]);\")))\n         ;; The resumable form runs only when a continuation is resumed, so it\n         ;; always takes the fallback, which halves what direct calls add to\n         ;; the generated code.\n         (if (twin? form)\n             fallback\n             (string-append \"if ($d > 0 && (\" entry \" = \" callee \"?.[\" (runtime form '$RAW) \"] ?? \" callee\n                            \")?.[\" (runtime form '$PRIM) \"] === true) { \"\n                            (runtime form '$stack) \".room = $d; return \" entry \"(\" arglist \"); } \"\n                            fallback))))\n      (else (error \"emit: unknown statement\" st)))))\n\n;; /**\n;;  * An estimate of the stack a procedure's frame takes, in slots: one for each\n;;  * local and parameter, and the fixed part of a V8 interpreter frame -- return\n;;  * address, frame pointer, context, function, argument count, bytecode and\n;;  * its offset, and the receiver. A frame the optimizing compiler has built is\n;;  * smaller, so this overestimates hot code, which errs the safe way. It is\n;;  * what a procedure takes from the room it is entered with (see `depth-entry`).\n;;  * @param {form} form - The emission, after every local has been declared.\n;;  * @returns {integer} Slots.\n;;  */\n(define (frame-size form)\n  (let ((ir (form-ir form)))\n    (+ (length (form-declared form))\n       (length (lambda-params ir))\n       (if (lambda-rest ir) 1 0)\n       8)))\n\n;; /**\n;;  * The lines that begin a procedure which calls anything: the room it leaves,\n;;  * `$d`, and in the fast form the test that moves compiled frames to the heap.\n;;  *\n;;  * Compiled frames live on the JavaScript stack, which holds a few thousand of\n;;  * them, where the interpreter's live on the heap. So how much more stack the\n;;  * compiled frames above the nearest interpreter frame may take is kept, in\n;;  * slots (see `frame-size`), in `R.stack.room`: each call site stores the room\n;;  * its procedure leaves before calling, and a procedure entered takes its own\n;;  * frame from what it finds there. A fast form entered with no room left does\n;;  * not run: it returns the unwind sentinel with itself and its arguments\n;;  * recorded as a pending call (`R.flush`), each compiled frame beneath it saves\n;;  * itself on the way out as it would for a continuation capture, and the\n;;  * interpreter puts the saved frames on its heap stack and makes the call from\n;;  * there, with the JavaScript stack empty again -- if the interpreter is there\n;;  * to do it, which `R.stack.flushable` says; see `compiledStack` in\n;;  * `src/core/interpreter/unwind.js`. The test is at entry rather than at each\n;;  * call site because a procedure is entered once and may call from many\n;;  * places: the arguments recorded for the call are its parameters.\n;;  *\n;;  * Room is stored before a call rather than taken before and given back\n;;  * after, so returning restores nothing and an exception that skips the code\n;;  * after a call cannot leave it wrong: the next call site stores it again.\n;;  * Counting that way, on every call, measured at 1-4% on programs made of\n;;  * calls, against 5-12% for taking and giving back, testing at each call. A procedure that calls\n;;  * nothing cannot deepen the stack and gets none of it.\n;;  *\n;;  * The resumable form is entered only by the interpreter, directly above its\n;;  * frames, so it keeps room for its callees but never moves its frames.\n;;  *\n;;  * @param {form} form - The emission, after its body.\n;;  * @param {list} args - The fast form's arguments, as JavaScript text.\n;;  * @returns {list} Lines of JavaScript.\n;;  */\n(define (depth-entry form args)\n  (let* ((rest (lambda-rest (form-ir form)))\n         ;; Arguments arrive on the stack, and a rest parameter's can be any\n         ;; number: `apply` spreading a long list is the case.\n         (spread (if (and rest (not (twin? form))) (string-append \" - \" (js-name rest) \"$raw.length\") \"\"))\n         (depth (lambda ()\n                  (string-append \"const $d = \" (runtime form '$stack) \".room - \"\n                                 (number->string (frame-size form)) spread \";\"))))\n    (cond ((not (form-depth form)) '())\n          ((and (eq? (form-depth form) 'call) (not (twin? form)))\n           (list (depth)\n                 (string-append \"if ($d < 0 && \" (runtime form '$stack) \".flushable) return \"\n                                (runtime form '$flush) \"(\" (procedure-value-name form)\n                                \", [\" (string-join args \", \") \"]);\")))\n          (else (list (depth))))))\n\n(define (goto-text n) (string-append \"$pc = \" (number->string n) \"; continue;\"))\n\n(define (frame-literal slots)\n  (string-append \"{ \" (string-join (map symbol->string slots) \", \") \" }\"))\n\n;; ---------------------------------------------------------------------------\n;; Lines\n;; ---------------------------------------------------------------------------\n;;\n;; A procedure is rendered as a list of items, each a line or an indented\n;; group of them:\n;;\n;;   string            a line\n;;   (text . span)     a line the source map maps to `span`\n;;   #(prefix items)   items, each line of them indented by `prefix`\n;;\n;; The function, the factory and the unit around a procedure each wrap the\n;; items inside rather than indenting every line again, and the unit's text is\n;; written once, at the end (`render-items`), which also lists the span of\n;; each line it writes, for the source map (`sourcemap.scm`).\n\n;; /**\n;;  * A statement's items: one line, but for the fast form's `if`, whose\n;;  * branches are lines of their own, indented.\n;;  * @param {form} form - The emission.\n;;  * @param {list} st - The statement.\n;;  * @returns {list}\n;;  */\n(define (statement-lines form st)\n  (if (eq? (car st) 'if)\n      (list (spanned (string-append \"if (\" (expr->string (cadr st)) \" !== false) {\") (statement-span st))\n            (vector \"  \" (append-map (lambda (s) (statement-lines form s)) (caddr st)))\n            \"} else {\"\n            (vector \"  \" (append-map (lambda (s) (statement-lines form s)) (cadddr st)))\n            \"}\")\n      (list (spanned (render-statement form st) (statement-span st)))))\n\n;; /**\n;;  * A line, with its span if it has one.\n;;  * @param {string} text - The line.\n;;  * @param {object|boolean} span - Its span, or #f.\n;;  * @returns {string|pair}\n;;  */\n(define (spanned text span) (if span (cons text span) text))\n\n;; /**\n;;  * Items as text, and the span of each line, in order: #f for a line with\n;;  * none. The text is appended to line by line, which a JavaScript engine\n;;  * does as a rope, joined once when the code is read; a string port, which\n;;  * checks its port at each write, made rendering a unit a third dearer.\n;;  * @param {list} items - The items.\n;;  * @returns {pair} (text . spans).\n;;  */\n(define (render-items items)\n  ;; The accumulator is (text . spans), the text #f until the first line and\n  ;; the spans most recent first.\n  (define (add acc indent text span)\n    (cons (if (car acc) (string-append (car acc) \"\\n\" indent text) (string-append indent text))\n          (cons span (cdr acc))))\n  (define (walk items indent acc)\n    (fold (lambda (item acc)\n            (cond ((string? item) (add acc indent item #f))\n                  ((pair? item) (add acc indent (car item) (cdr item)))\n                  (else (walk (vector-ref item 1) (string-append indent (vector-ref item 0)) acc))))\n          acc\n          items))\n  (let ((acc (walk items \"\" (cons #f '()))))\n    (cons (or (car acc) \"\") (reverse (cdr acc)))))\n\n;; ---------------------------------------------------------------------------\n;; The unit\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * What every procedure in one compilation unit shares: the lifting plan,\n;;  * how each global is reached -- each a library's own binding, by the key\n;;  * the lowering gave it, from the library's environment (`library-global-key`\n;;  * in ir.scm) -- the constant pool, the factories emitted so\n;;  * far, where each call site resumes, and the runtime values its code names\n;;  * (see `runtime`).\n;;  *\n;;  * A call site's resume block and saved locals are decided by the twin,\n;;  * which is generated first, and read by the fast form, which has to spill\n;;  * into exactly the frame the twin restores.\n;;  */\n(define-record-type unit\n  (make-unit plan globals library-globals global-indices guarded constants factories emitted resume-points\n             runtime)\n  unit?\n  (plan unit-plan)\n  (globals unit-globals)\n  (library-globals unit-library-globals)\n  (global-indices unit-global-indices)\n  (guarded unit-guarded)\n  (constants unit-constants set-unit-constants!)\n  (factories unit-factories set-unit-factories!)\n  (emitted unit-emitted set-unit-emitted!)\n  (resume-points unit-resume-points set-unit-resume-points!)\n  (runtime unit-runtime set-unit-runtime!))\n\n;; /**\n;;  * The local name generated code knows a runtime value by, noted as one its\n;;  * unit uses, so that the unit declares it (see `runtime-prelude`). Every\n;;  * piece of generated code that names a runtime value names it through this.\n;;  * @param {form} form - The emission.\n;;  * @param {symbol} name - The value's local name, one of `runtime-constants`.\n;;  * @returns {string} The name, as text.\n;;  */\n(define (runtime form name)\n  (let ((u (form-unit form)))\n    (if (not (memq name (unit-runtime u)))\n        (set-unit-runtime! u (cons name (unit-runtime u))))\n    (symbol->string name)))\n\n;; /**\n;;  * The globals the lowering itself introduces, which are the runtime's\n;;  * procedures whatever the environment binds under their names\n;;  * (`lower-call-with-values` and `receiver-binding` in ir.scm), each with\n;;  * what reads it.\n;;  */\n(define runtime-globals\n  '((%apply . \"R.applyProcedure\") (%values->list . \"R.valuesToList\")\n    (%this-at . \"R.thisAt\") (%this-of . \"R.thisOf\")))\n\n;; /**\n;;  * The JavaScript expression that reads a global: its cell's value, or, before\n;;  * the first read resolves the cell -- or when the value is `null` or\n;;  * `undefined`, which the cell cannot tell from unresolved -- its resolver's\n;;  * answer. See `R.globalCell` for why a global is read through a cell. One\n;;  * the lowering introduced is read from the runtime (`runtime-globals`).\n;;  * @param {unit} u - The unit.\n;;  * @param {symbol} name - The global.\n;;  * @returns {string} The expression.\n;;  */\n(define (global-read u name)\n  (cond ((assq name runtime-globals) => cdr)\n        (else (let ((i (global-index u name)))\n                (string-append \"(C\" i \".v ?? G\" i \"())\")))))\n\n;; /**\n;;  * A global's position in the unit's list, which numbers its accessor.\n;;  * @param {unit} u - The unit.\n;;  * @param {symbol} name - The global.\n;;  * @returns {string} The position, as text.\n;;  */\n(define (global-index u name)\n  (or (weak-table-ref (unit-global-indices u) name)\n      (error \"emit: not a global of this unit\" name)))\n\n;; /**\n;;  * Each of some globals' positions in their list, as text, for\n;;  * `global-index`: a global is read wherever the code names it, and finding\n;;  * it in the list each time grew with the square of the globals.\n;;  * @param {list} globals - The globals, as symbols.\n;;  * @returns {weak-table} Each global's position.\n;;  */\n(define (global-indices globals)\n  (let ((table (make-weak-table)))\n    (for-each (lambda (g i) (weak-table-set! table g (number->string i)))\n              globals (iota (length globals)))\n    table))\n\n;; /**\n;;  * A value that survived to compile time, as a JavaScript expression.\n;;  *\n;;  * Only immediates are written inline. Pairs, symbols, vectors and the like\n;;  * go into the constant pool: they have identity `eq?` can observe, so\n;;  * re-creating them per evaluation would be wrong as well as slow.\n;;  *\n;;  * @param {unit} u - The unit, holding the pool.\n;;  * @param {*} v - The value.\n;;  * @returns {string} A JavaScript expression.\n;;  */\n(define (constant u v)\n  (cond ((null? v) \"null\")\n        ((js-undefined? v) \"undefined\")\n        ((eq? v #t) \"true\")\n        ((eq? v #f) \"false\")\n        ;; An exact integer is a JavaScript number in the safe range, a BigInt\n        ;; beyond it; an inexact real a number unless its value is an integer,\n        ;; when it is boxed, and goes into the pool\n        ;; (src/core/interpreter/number_representation.js).\n        ((exact-integer? v)\n         (if (<= (abs v) 9007199254740991)\n             (number->string v)\n             (string-append (number->string v) \"n\")))\n        ((and (real? v) (inexact? v) (not (integer? v))) (js-number v))\n        ((string? v) (js-string v))\n        (else\n         (let ((index (length (unit-constants u))))\n           (set-unit-constants! u (cons v (unit-constants u)))\n           (string-append \"K[\" (number->string index) \"]\")))))\n\n;; ---------------------------------------------------------------------------\n;; One emission of one procedure\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * The state of one emission -- one form of one procedure.\n;;  *\n;;  * Each emission counts its temporaries from zero, the two forms of the same\n;;  * procedure included. That is the point: they must arrive at the same name\n;;  * for the same value, and they only do if neither inherits a count.\n;;  *\n;;  * `out` is the statements so far, most recent first -- in the twin, those of\n;;  * the current block. `declared` is every local the emission introduced, most\n;;  * recent first. `loop-targets` is the stack of loops a looping call can jump\n;;  * to. `blocks` holds the twin's finished blocks by number, and `sites` its\n;;  * suspension points with the block each resumes at. `span` is the source\n;;  * span of the call being emitted, which each statement emitted meanwhile is\n;;  * noted as coming from (`emit!`), or #f. `doubles` is the locals that hold\n;;  * raw doubles where the emission is, inside a loop run on them (see \"Loops\n;;  * on raw doubles\").\n;;  */\n(define-record-type form\n  (make-form name ir unit mode path counter labels loops loop-targets declared\n             out blocks block-count current sites frames depth span doubles)\n  form?\n  (name form-name)\n  (ir form-ir)\n  (unit form-unit)\n  (mode form-mode)\n  (path form-path)\n  (counter form-counter set-form-counter!)\n  (labels form-labels set-form-labels!)\n  (loops form-loops set-form-loops!)\n  (loop-targets form-loop-targets set-form-loop-targets!)\n  (declared form-declared set-form-declared!)\n  (out form-out set-form-out!)\n  (blocks form-blocks set-form-blocks!)\n  (block-count form-block-count set-form-block-count!)\n  (current form-current set-form-current!)\n  (sites form-sites set-form-sites!)\n  (frames form-frames set-form-frames!)\n  (depth form-depth set-form-depth!)\n  (span form-span set-form-span!)\n  (doubles form-doubles set-form-doubles!))\n\n;; /**\n;;  * A fresh emission of a procedure.\n;;  * @param {string} name - The JavaScript function's name.\n;;  * @param {list} ir - The procedure's lambda IR node.\n;;  * @param {unit} u - The unit.\n;;  * @param {symbol} mode - 'fast or 'twin.\n;;  * @param {string} path - Where the procedure sits in the tree of procedures.\n;;  * @returns {form} The emission.\n;;  */\n(define (new-form name ir u mode path)\n  (make-form name ir u mode path 0 0 #f '() '() '() '() 1 0 '() '() #f #f '()))\n\n(define (twin? form) (eq? (form-mode form) 'twin))\n(define (plan-of form) (unit-plan (form-unit form)))\n\n;; /**\n;;  * The source span each statement was emitted from, where it was emitted\n;;  * while a call with one was (`form-span`): what the line it renders to maps\n;;  * to in the source map (`sourcemap.scm`). Kept beside the statements rather\n;;  * than in them, since every reader of a statement -- liveness, the blocks of\n;;  * the resumable form, rendering -- would otherwise have to step over it.\n;;  */\n(define statement-spans (make-weak-table))\n\n;; /**\n;;  * The source span a statement was emitted from, or #f.\n;;  * @param {list} st - The statement.\n;;  * @returns {object|boolean}\n;;  */\n(define (statement-span st) (weak-table-ref statement-spans st))\n\n;; /**\n;;  * Appends a statement to the emission, noting the span of the call it comes\n;;  * from.\n;;  * @param {form} form - The emission.\n;;  * @param {list} st - The statement.\n;;  * @returns {unspecified}\n;;  */\n(define (emit! form st)\n  (let ((span (form-span form)))\n    (if span (weak-table-set! statement-spans st span) #f))\n  (set-form-out! form (cons st (form-out form))))\n\n;; /**\n;;  * Emits a call node with its source span as the emission's, so that the\n;;  * statements it makes are noted as coming from it; a call with none leaves\n;;  * the span of the call it is in.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `call` IR node.\n;;  * @param {procedure} emit - Emits it, and returns what it returns.\n;;  * @returns {*} What `emit` returns.\n;;  */\n(define (with-call-span form node emit)\n  (let ((span (call-span node)))\n    (if (not span)\n        (emit)\n        (let ((outer (form-span form)))\n          (set-form-span! form span)\n          (let ((result (emit)))\n            (set-form-span! form outer)\n            result)))))\n\n;; /**\n;;  * Records a local as introduced by this emission, keeping first-seen order.\n;;  * @param {form} form - The emission.\n;;  * @param {symbol} sym - The local.\n;;  * @returns {unspecified}\n;;  */\n(define (declare! form sym)\n  (if (not (memq sym (form-declared form)))\n      (set-form-declared! form (cons sym (form-declared form)))))\n\n;; /**\n;;  * Takes the next number from the emission's counter, which names both\n;;  * temporaries and nested procedures.\n;;  * @param {form} form - The emission.\n;;  * @returns {integer} The number.\n;;  */\n(define (next-number! form)\n  (let ((n (form-counter form)))\n    (set-form-counter! form (+ n 1))\n    n))\n\n;; /**\n;;  * A fresh temporary. It is declared without `declare!`'s search of what the\n;;  * emission has declared, which cannot hold it: its number is new to the\n;;  * emission, and only temporaries are named `$t`.\n;;  * @param {form} form - The emission.\n;;  * @returns {symbol} Its name.\n;;  */\n(define (temp! form)\n  (let ((sym (string->symbol (string-append \"$t\" (number->string (next-number! form))))))\n    (set-form-declared! form (cons sym (form-declared form)))\n    sym))\n\n;; /**\n;;  * The name and position of the next procedure nested directly in this one.\n;;  * The name spells out where it sits -- `$fn2_0` is the first inside the\n;;  * third inside the outermost -- which makes it unique in the unit without a\n;;  * shared counter. It must be: a procedure refers to its own resumable form\n;;  * by name, and a nested name that collided with its parent's would shadow it.\n;;  * @param {form} form - The emission.\n;;  * @returns {pair} (name . path).\n;;  */\n(define (nested-name! form)\n  (let* ((index (number->string (next-number! form)))\n         (path (if (string=? (form-path form) \"\") index\n                   (string-append (form-path form) \"_\" index))))\n    (cons (string-append \"$fn\" path) path)))\n\n;; /**\n;;  * The statements a thunk emits, collected apart from the emission's own and\n;;  * returned in order. The fast form emits the branches of a JavaScript `if`\n;;  * this way.\n;;  * @param {form} form - The emission.\n;;  * @param {procedure} thunk - Emits the statements.\n;;  * @returns {list} The statements.\n;;  */\n(define (collect-statements form thunk)\n  (let ((saved (form-out form)))\n    (set-form-out! form '())\n    (thunk)\n    (let ((collected (reverse (form-out form))))\n      (set-form-out! form saved)\n      collected)))\n\n;; --- Locals ----------------------------------------------------------------\n\n(define (boxed-local? form name) (boxed? (plan-of form) name))\n\n;; /**\n;;  * An expression reading a local; a boxed one is read through its box.\n;;  * @param {form} form - The emission.\n;;  * @param {symbol} name - A renamed local.\n;;  * @returns {list} The expression.\n;;  */\n(define (read-local form name)\n  (if (boxed-local? form name)\n      (js (js-local name) \"[0]\")\n      (js (js-local name))))\n\n;; /**\n;;  * The statement binding a local to its first value. A boxed local's box is\n;;  * made here, so every reader -- a closure, a resumed frame -- reaches it.\n;;  * @param {form} form - The emission.\n;;  * @param {symbol} name - A renamed local.\n;;  * @param {list} value - Its value.\n;;  * @returns {list} The statement.\n;;  */\n(define (bind-local form name value)\n  (declare! form (js-local name))\n  (list 'assign (js (js-local name))\n        (if (boxed-local? form name) (js \"[\" value \"]\") value)))\n\n;; /**\n;;  * Makes the boxes for the internal definitions in a body, before any of it\n;;  * runs. A procedure defined earlier in a body can refer to one defined later,\n;;  * so it has to be handed something that will hold that procedure once the\n;;  * later definition runs. Only names some nested procedure refers to are\n;;  * boxed, so an ordinary internal helper stays a plain variable. A loop that\n;;  * stands for a fresh call makes them again each iteration.\n;;  * @param {form} form - The emission.\n;;  * @param {list} body - The body.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-define-boxes! form body)\n  (for-each (lambda (def)\n              (let ((name (cadr def)))\n                (if (boxed-local? form name)\n                    (begin (declare! form (js-local name))\n                           (emit! form (list 'assign (js (js-local name)) (js \"[undefined]\")))))))\n            (definitions-in body)))\n\n;; /**\n;;  * The internal definitions in a procedure's own body -- in any branch, but\n;;  * not inside a nested procedure, which makes its own.\n;;  * @param {list} node - An IR node.\n;;  * @returns {list} The `define` nodes.\n;;  */\n(define (definitions-in node)\n  (case (car node)\n    ((lambda) '())\n    ((define) (cons node (definitions-in (caddr node))))\n    (else (append-map definitions-in (ir-children node)))))\n\n;; ---------------------------------------------------------------------------\n;; Expressions\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Emits an IR node whose value is wanted, returning an expression for it.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node.\n;;  * @returns {list} The expression.\n;;  */\n(define (emit-value! form node)\n  (case (car node)\n    ((const) (js (constant (form-unit form) (cadr node))))\n    ((local) (if (memq (cadr node) (form-doubles form))\n                 (js \"R.inexactReal(\" (js-local (cadr node)) \")\")\n                 (read-local form (cadr node))))\n    ;; Read through its cell on every reference, because a top-level binding\n    ;; can be redefined after this code was compiled -- by the REPL running it,\n    ;; for one.\n    ((global) (js (global-read (form-unit form) (cadr node))))\n    ((lambda) (emit-closure! form node))\n    ((set) (emit-assignment! form node))\n    ((define) (emit-definition! form node))\n    ((seq) (fold (lambda (expr last) (emit-value! form expr)) (js \"undefined\") (cadr node)))\n    ((if) (if (twin? form) (emit-twin-value-if! form node) (emit-value-if! form node)))\n    ((let)\n     (declare! form (js-local (cadr node)))\n     (if (double-let? form node)\n         (with-double form (cadr node) (caddr node) (lambda () (emit-value! form (cadddr node))))\n         (let ((init (emit-value! form (caddr node))))\n           (emit! form (bind-local form (cadr node) init))\n           (emit-value! form (cadddr node)))))\n    ((letrec)\n     (emit-letrec-bindings! form node)\n     (emit-value! form (cadddr node)))\n    ((capture) (emit-capture! form node))\n    ((call) (with-call-span form node (lambda () (or (emit-inline! form node) (emit-call! form node)))))\n    (else (error \"emit: cannot emit IR node\" (car node)))))\n\n;; /**\n;;  * Emits operands, left to right, each settled before any after it can\n;;  * change what it reads.\n;;  *\n;;  * A call's value is a statement and a temporary, but a global read, a boxed\n;;  * local's read or a sequence's last expression is an expression, written into\n;;  * the call that uses it -- and so evaluated after every operand to its right.\n;;  * If one of those assigns what it reads, the operand sees the new value:\n;;  * `(list g (f))`, with `f` assigning `g`, was `(5 10)` compiled where the\n;;  * interpreter says `(0 10)`. R7RS leaves the order unspecified, so both are\n;;  * Scheme; but the interpreter is the reference semantics, and a program that\n;;  * depended on the order would change its answer when compiled. So such an\n;;  * operand goes into a temporary first, when an operand after it could have\n;;  * an effect at all -- anything but a literal, a variable or a lambda. A\n;;  * literal and an unassigned local are left alone, since nothing can change\n;;  * them.\n;;  *\n;;  * @param {form} form - The emission.\n;;  * @param {list} nodes - The operands' IR nodes, in order.\n;;  * @returns {list} Their expressions.\n;;  */\n(define (emit-operands! form nodes)\n  (let loop ((nodes nodes) (acc '()))\n    (if (null? nodes)\n        (reverse acc)\n        (let ((expr (emit-value! form (car nodes))))\n          (loop (cdr nodes)\n                (cons (if (and (not (repeatable? expr)) (any effectful? (cdr nodes)))\n                          (let ((t (temp! form)))\n                            (emit! form (list 'assign (js t) expr))\n                            (js t))\n                          expr)\n                      acc))))))\n\n;; /**\n;;  * Whether evaluating an IR node could change what another reads: anything\n;;  * but a literal, a variable read or the making of a procedure.\n;;  * @param {list} node - The node.\n;;  * @returns {boolean}\n;;  */\n(define (effectful? node)\n  (not (memq (car node) '(const local global lambda))))\n\n;; /**\n;;  * Creates a nested procedure by calling its factory with its free variables.\n;;  * @param {form} form - The emission.\n;;  * @param {list} lam - A lambda IR node.\n;;  * @returns {list} The expression holding the procedure.\n;;  */\n(define (emit-closure! form lam)\n  (let* ((named (nested-name! form))\n         (factory (factory-for! (form-unit form) (car named) (cdr named) lam))\n         (args (map js-local (plan-free-of (plan-of form) lam)))\n         (result (temp! form)))\n    (emit! form (list 'assign (js result)\n                      (js factory \"(\" (join-exprs (map js args) \", \") \")\")))\n    (js result)))\n\n;; /**\n;;  * Expressions joined by a separator, as one expression.\n;;  * @param {list} exprs - The expressions.\n;;  * @param {string} separator - The separator.\n;;  * @returns {list} The expression.\n;;  */\n(define (join-exprs exprs separator)\n  (if (null? exprs)\n      '()\n      (fold (lambda (e acc) (js acc separator e)) (car exprs) (cdr exprs))))\n\n;; /**\n;;  * Emits `set!`, whose value is unspecified.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `set` IR node.\n;;  * @returns {list} The expression for its value.\n;;  */\n(define (emit-assignment! form node)\n  (let* ((value (emit-value! form (cadddr node)))\n         (name (cadr node))\n         (u (form-unit form))\n         (library (assq name (unit-library-globals u))))\n    (emit! form (cond ((caddr node) (list 'assign (read-local form name) value))\n                      (library\n                       (list 'eval (js (constant u (cddr library)) \".set(\"\n                                       (js-string (symbol->string (cadr library))) \", \" value \")\")))\n                      (else (list 'eval (js \"E.set(\" (js-string (symbol->string name)) \", \" value \")\")))))\n    (js \"undefined\")))\n\n;; /**\n;;  * Emits an internal definition. A boxed name's box already exists -- made\n;;  * at the head of the body, since something defined earlier may hold it --\n;;  * so the definition fills it rather than making one.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `define` IR node.\n;;  * @returns {list} The expression for its value.\n;;  */\n(define (emit-definition! form node)\n  (let ((name (cadr node)))\n    (if (boxed-local? form name)\n        (begin\n          (declare! form (js-local name))\n          (let ((value (emit-value! form (caddr node))))\n            (emit! form (list 'assign (js (js-local name) \"[0]\") value))))\n        (let ((value (emit-value! form (caddr node))))\n          (emit! form (bind-local form name value))))\n    (js \"undefined\")))\n\n;; /**\n;;  * Emits a `letrec` group's bindings.\n;;  *\n;;  * Every name is declared, and every boxed name's box made, before any\n;;  * initializer, so an initializer can refer to a sibling in either order: a\n;;  * name a sibling refers to is boxed exactly so that the sibling, built first,\n;;  * can be handed something that will hold it later. Every initializer is a\n;;  * lambda, so their order is unobservable.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `letrec` IR node.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-letrec-bindings! form node)\n  (let ((names (cadr node)))\n    (for-each (lambda (name) (declare! form (js-local name))) names)\n    (for-each (lambda (name)\n                (if (boxed-local? form name)\n                    (emit! form (list 'assign (js (js-local name)) (js \"[undefined]\")))))\n              names)\n    (for-each (lambda (name init)\n                (let ((value (emit-value! form init)))\n                  (emit! form (list 'assign\n                                    (if (boxed-local? form name)\n                                        (js (js-local name) \"[0]\")\n                                        (js (js-local name)))\n                                    value))))\n              names (caddr node))))\n\n;; /**\n;;  * Emits an `if` whose value is wanted, in the fast form: a JavaScript `if`\n;;  * assigning a temporary in each branch.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An `if` IR node.\n;;  * @returns {list} The expression holding its value.\n;;  */\n(define (emit-value-if! form node)\n  (let* ((test (emit-value! form (cadr node)))\n         (result (temp! form))\n         (arm (lambda (branch)\n                (collect-statements form\n                  (lambda ()\n                    (let ((value (emit-value! form branch)))\n                      (emit! form (list 'assign (js result) value)))))))\n         (then (arm (caddr node)))\n         (other (arm (cadddr node))))\n    (emit! form (list 'if test then other))\n    (js result)))\n\n;; /**\n;;  * Attempts to expand a call to a primitive inline, returning #f when the\n;;  * call is not one: the operator must be a global with an expansion at this\n;;  * argument count, bound to its primitive when this was compiled.\n;;  *\n;;  * The expansion is guarded on the binding, since Scheme allows the\n;;  * primitive to be redefined afterwards: it is used while the primitive's\n;;  * cell says the name has never been rebound, or failing that while the\n;;  * binding is the primitive anyway, and otherwise the call goes to whatever\n;;  * the name is bound to now. Operands are evaluated into temporaries first,\n;;  * since an expansion may mention one more than once.\n;;  *\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `call` IR node.\n;;  * @returns {list|boolean} The expression holding the value, or #f.\n;;  */\n(define (emit-inline! form node)\n  (or (and (pair? (form-doubles form)) (emit-double-inline form node))\n      (emit-guarded-inline! form node)))\n\n;; /**\n;;  * An inline expansion of a call to a primitive whose binding is guarded, or\n;;  * #f (`emit-inline!`).\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `call` IR node.\n;;  * @returns {list|boolean} The expression holding the value, or #f.\n;;  */\n(define (emit-guarded-inline! form node)\n  (let* ((fn (cadr node))\n         (u (form-unit form))\n         (entry (and (eq? (car fn) 'global)\n                     (memq (cadr fn) (unit-guarded u))\n                     (inline-expansion (global-written-name (unit-library-globals u) (cadr fn))\n                                       (caddr node)))))\n    (and entry\n         (let* ((operands (map-in-order (lambda (arg)\n                                 (let ((value (emit-value! form arg)))\n                                   (if (repeatable? value)\n                                       value\n                                       (let ((t (temp! form)))\n                                         (emit! form (list 'assign (js t) value))\n                                         (js t)))))\n                               (caddr node)))\n                (index (global-index u (cadr fn)))\n                (read (global-read u (cadr fn)))\n                (shape ((caddr entry) operands))\n                (fast (let ((value (cadddr entry)))\n                        (cond ((symbol? value)\n                               (js (runtime form value) \"(\" (join-exprs operands \", \") \")\"))\n                              ((pair? value)\n                               ((cdr value) operands (runtime form (car value)) (caddr node)))\n                              (else (value operands)))))\n                (binding (js \"(W\" index \".intact || \" read \" === P\" index \")\"))\n                (result (temp! form)))\n           (emit! form (list 'assign (js result)\n                             (js (if shape (js binding \" && (\" shape \")\") binding)\n                                 \" ? (\" fast \") : R.callBinding(\" read \", [\"\n                                 (join-exprs operands \", \") \"])\")))\n           (js result)))))\n\n;; /**\n;;  * Emits a call whose value is wanted.\n;;  *\n;;  * A primitive takes Scheme values directly. An interpreted closure or a\n;;  * compiled procedure is a callable function too, but calling it that way\n;;  * enters Scheme from JavaScript and converts -- exact integers to doubles --\n;;  * so it is called through its raw entry. Which kind the callee is belongs to\n;;  * the value, not the name, so it is tested at the call.\n;;  *\n;;  * Before any of that the callee is tested for being a function at all:\n;;  * called, anything else makes JavaScript report the temporary holding it --\n;;  * \"$t0 is not a function\" -- where the interpreter says \"application: not a\n;;  * procedure\", and reading the raw entry of the empty list, which is `null`,\n;;  * fails before that. How it is tested was measured, since it runs on every\n;;  * call. Written into the call expression -- only a callee with no raw entry,\n;;  * the entry read with `?.` -- it made `benchmarks/r7rs/src/divrec.scm` 9%\n;;  * slower; as a statement of its own, 2-4.5% on the programs made of calls\n;;  * between compiled procedures. Catching the call's failure in a `try`\n;;  * instead cost those nothing but a call into an interpreted procedure 15%,\n;;  * which is what the compiled library calling a program's callbacks makes,\n;;  * so `benchmarks/r7rs/src/quicksort.scm` ran 9% slower. The callee may\n;;  * return a pending tail call, which is run out here, or report a capture --\n;;  * or that there was no room on the stack for it to run (see `depth-entry`)\n;;  * -- which this frame then joins.\n;;  *\n;;  * Before the call it stores the room this procedure leaves for the callee,\n;;  * and again before each step of a pending tail call, since whatever returned\n;;  * it had stored room of its own.\n;;  *\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `call` IR node.\n;;  * @returns {list} The expression holding the value.\n;;  */\n(define (emit-call! form node)\n  ;; The procedure first, as the interpreter evaluates it (`emit-operands!`).\n  (let* ((operands (emit-operands! form (cons (cadr node) (caddr node))))\n         (fn (car operands))\n         (args (cdr operands))\n         (callee (temp! form))\n         (raw (temp! form))\n         (result (temp! form))\n         (arglist (join-exprs args \", \")))\n    (emit! form (list 'assign (js callee) fn))\n    (emit! form (list 'raw (js \"if (typeof \" callee \" !== 'function') \" (runtime form '$notProc) \"(\" callee \");\")))\n    (emit! form (list 'assign (js raw) (js callee \"[\" (runtime form '$RAW) \"]\")))\n    (set-form-depth! form 'call)\n    (emit! form (list 'text (string-append (runtime form '$stack) \".room = $d;\")))\n    ;; No raw entry: a primitive, called directly, or anything else -- a\n    ;; JavaScript function -- through `$foreign`, which converts its arguments\n    ;; as the interpreter does.\n    (emit! form (list 'assign (js result)\n                      (js raw \" === undefined ? (\" callee \"[\" (runtime form '$PRIM) \"] === true ? \"\n                          callee \"(\" arglist \") : \" (runtime form '$foreign) \"(\" callee \", [\" arglist \"])) : \"\n                          raw \"(\" arglist \")\")))\n    (emit! form (list 'raw (js \"while (\" result \" instanceof \" (runtime form '$TailCall) \") { \"\n                               (runtime form '$stack) \".room = $d; \"\n                               result \" = \" (runtime form '$step) \"(\" result \"); }\")))\n    (if (twin? form)\n        (resume-after! form node result)\n        (emit! form (suspension form node (js result))))\n    (js result)))\n\n;; /**\n;;  * Emits a continuation capture. It always suspends; the value the\n;;  * continuation is later invoked with arrives where the procedure resumes.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `capture` IR node.\n;;  * @returns {list} The expression holding the captured value.\n;;  */\n(define (emit-capture! form node)\n  (let* ((receiver (emit-value! form (cadr node)))\n         (result (temp! form)))\n    (emit! form (list 'eval (js \"R.capture(\" receiver \")\")))\n    (if (twin? form)\n        (let ((resume (new-block! form)))\n          (note-resume-site! form node resume)\n          (emit! form (list 'spill #f resume))\n          (emit! form (list 'return (js (runtime form '$UNWIND))))\n          (switch-to! form resume)\n          (emit! form (list 'assign (js result) (js \"$r\"))))\n        (emit! form (suspension form node #f)))\n    (js result)))\n\n;; /**\n;;  * The fast form's statement for when a callee reports a capture beneath this\n;;  * frame: save the locals the twin needs at the block it resumes at, and pass\n;;  * the report outward, so every frame between the capture and the\n;;  * interpreter records itself.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - The call or capture IR node.\n;;  * @param {list|boolean} result - The call's result, or #f for a capture,\n;;  *   which suspends unconditionally.\n;;  * @returns {list} The statement.\n;;  */\n(define (suspension form node result)\n  (let ((point (assq node (unit-resume-points (form-unit form)))))\n    (if point\n        (list 'suspend result (cadr point) (cddr point))\n        ;; No resumable form to suspend into. Refusing is the point: carrying on\n        ;; with the sentinel as the call's value would assemble an answer from a\n        ;; continuation with a hole in it.\n        (list 'text (if result\n                        (string-append \"if (\" (expr->string result)\n                                       \" === \" (runtime form '$UNWIND) \") R.captureWithoutResume();\")\n                        \"R.captureWithoutResume();\")))))\n\n;; ---------------------------------------------------------------------------\n;; Statements\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Emits an IR node as a statement. A node in tail position ends the\n;;  * procedure; anything else contributes its effects and its value is\n;;  * discarded.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-statement! form node)\n  (if (not (node-tail? node))\n      (emit! form (list 'eval (emit-value! form node)))\n      (case (car node)\n        ((if) (if (twin? form) (emit-twin-tail-if! form node) (emit-tail-if! form node)))\n        ((seq)\n         (if (null? (cadr node))\n             (emit! form (list 'return (js \"undefined\")))\n             (for-each (lambda (expr) (emit-statement! form expr)) (cadr node))))\n        ((let)\n         (if (double-let? form node)\n             (begin (declare! form (js-local (cadr node)))\n                    (with-double form (cadr node) (caddr node) (lambda () (emit-statement! form (cadddr node)))))\n             (let ((init (emit-value! form (caddr node))))\n               (emit! form (bind-local form (cadr node) init))\n               (emit-statement! form (cadddr node)))))\n        ((letrec)\n         (if (letrec-inline? node)\n             (emit-inline-loop! form node)\n             (begin (emit-letrec-bindings! form node)\n                    (emit-statement! form (cadddr node)))))\n        ((call) (with-call-span form node (lambda () (emit-tail-call! form node))))\n        (else (emit! form (list 'return (emit-value! form node)))))))\n\n;; /**\n;;  * Whether an IR node is in tail position. Every node records it, in the\n;;  * field after its own.\n;;  * @param {list} node - An IR node.\n;;  * @returns {boolean}\n;;  */\n(define (node-tail? node)\n  (case (car node)\n    ((const local global capture) (caddr node))\n    ((call) (cadddr node))\n    ((set) (car (cddddr node)))\n    ((define) (cadddr node))\n    ((if) (car (cddddr node)))\n    ((seq) (caddr node))\n    ((lambda) (cadr (cddddr node)))\n    ((let letrec) (car (cddddr node)))\n    (else #f)))\n\n(define (letrec-inline? node) (eq? (list-ref node 6) #t))\n\n;; /**\n;;  * A tail `if` in the fast form: a JavaScript `if` whose branches each end\n;;  * the procedure.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An `if` IR node.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-tail-if! form node)\n  (let* ((test (emit-value! form (cadr node)))\n         (then (collect-statements form (lambda () (emit-statement! form (caddr node)))))\n         (other (collect-statements form (lambda () (emit-statement! form (cadddr node))))))\n    (emit! form (list 'if test then other))))\n\n;; /**\n;;  * Emits a call in tail position.\n;;  *\n;;  * An inlined primitive needs no trampoline: it cannot tail-call, so its\n;;  * value is this procedure's value, returned directly. A call the lowering\n;;  * found to be to the loop it is in reassigns that loop's parameters and\n;;  * jumps back to its head; a call to this procedure's own global does so only\n;;  * while the global still names this procedure. Anything else is a `tail`\n;;  * statement (see `emit-transfer!`).\n;;  *\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `call` IR node in tail position.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-tail-call! form node)\n  (let ((inlined (emit-inline! form node)))\n    (if inlined\n        (emit! form (list 'return inlined))\n        (let* ((kind (call-loop node))\n               (target (loop-target form))\n               (operands (if (and kind (pair? (form-doubles form)))\n                             (cons (emit-value! form (cadr node))\n                                   (map (lambda (arg param)\n                                          (if (memq param (form-doubles form))\n                                              (emit-double form arg)\n                                              (emit-value! form arg)))\n                                        (caddr node) (loop-params target)))\n                             (emit-operands! form (cons (cadr node) (caddr node)))))\n               (fn (car operands))\n               (args (cdr operands)))\n          (cond\n            ((and kind (loop-fixed-arity? target) (= (length args) (length (loop-params target))))\n             (let ((jump (loop-back! form args target)))\n               (if (loop-procedure? target) (set-form-loops! form #t))\n               (if (eq? kind 'local)\n                   (for-each (lambda (st) (emit! form st)) jump)\n                   (begin\n                     (emit! form (list 'guarded (js fn \" === \" (procedure-value-name form)) jump))\n                     (emit-transfer! form fn args)))))\n            (else (emit-transfer! form fn args)))))))\n\n;; /**\n;;  * Emits a tail call to a callee that is not known to be this procedure.\n;;  *\n;;  * A compiled procedure or a primitive is called directly -- a compiled\n;;  * procedure through its raw entry, which faces Scheme where the procedure\n;;  * itself faces JavaScript, so the call costs a property load more than when\n;;  * the two were one -- as long as this\n;;  * procedure leaves room on the stack (see `depth-entry`); the callee then\n;;  * takes its frame from that room, since this frame stays on the stack\n;;  * beneath it. With no room, and for any other callee, the call is returned\n;;  * as a `TailCall`, so whoever is trampolining -- compiled or interpreted --\n;;  * continues it and a chain of tail calls runs in bounded space. An\n;;  * interpreted closure is among the others because it is entered through the\n;;  * interpreter, which a trampoline reaches as cheaply, and a continuation\n;;  * because calling one directly throws to get where it is going: `fibc` ran\n;;  * 2.6 times slower when its tail calls to continuations were made directly.\n;;  *\n;;  * The room is tested before the callee, so a call with none costs one\n;;  * comparison rather than a property load on whatever the callee is: tested\n;;  * the other way round, `earley`, which recurses deeply, ran slower than it\n;;  * did before any call was made directly.\n;;  *\n;;  * Only the fast form tries the direct call; the resumable form, which runs\n;;  * only when a continuation is resumed, always takes the fallback. The\n;;  * fallback is a runtime helper, `tailCall`, rather than the `TailCall`\n;;  * written out. Both keep down what every tail call site adds: the direct call\n;;  * in both forms, with the fallback written out and the check a non-procedure\n;;  * needs, made the generated code 9% larger. See `tailCall` for the check.\n;;  *\n;;  * A capture beneath a direct tail call needs nothing from this frame: its\n;;  * continuation is the callee's, so the unwind sentinel is returned as the\n;;  * callee's value, and the frame is correctly absent from what is recorded.\n;;  *\n;;  * @param {form} form - The emission.\n;;  * @param {list} fn - The callee expression.\n;;  * @param {list} args - The argument expressions.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-transfer! form fn args)\n  (if (and (not (twin? form)) (not (form-depth form))) (set-form-depth! form 'tail))\n  (let ((callee (temp! form))\n        (entry (temp! form)))\n    (emit! form (list 'assign (js callee) fn))\n    (emit! form (list 'tail (js callee) args (js entry)))))\n\n;; /**\n;;  * The identifier of this procedure's fast form, which is its raw entry.\n;;  * @param {form} form - The emission.\n;;  * @returns {string} The identifier.\n;;  */\n(define (procedure-name form)\n  (let* ((name (form-name form)) (n (string-length name)))\n    (if (and (twin? form) (> n 2) (string=? (substring name (- n 2) n) \"$r\"))\n        (substring name 0 (- n 2))\n        name)))\n\n;; /**\n;;  * The identifier of the procedure itself, which faces JavaScript and has the\n;;  * fast form as its raw entry (`markProcedure` in `src/compiler/runtime.js`):\n;;  * what a global self-call is compared against, since it is what the global\n;;  * holds, and what a move of frames to the heap records to call again, since\n;;  * it is what the interpreter knows to be compiled.\n;;  * @param {form} form - The emission.\n;;  * @returns {string} The identifier.\n;;  */\n(define (procedure-value-name form)\n  (string-append (procedure-name form) \"$js\"))\n\n;; ---------------------------------------------------------------------------\n;; Loops\n;; ---------------------------------------------------------------------------\n;;\n;; A loop target is what a looping tail call jumps to: this procedure itself,\n;; or a loop emitted inline inside it. Reassigning parameters in place is sound\n;; because every nested procedure receives its free variables by value or by\n;; box, so a closure made in one iteration keeps that iteration's bindings.\n\n(define-record-type loop-target\n  (make-loop-target params fixed-arity procedure assign jump)\n  loop-target?\n  (params loop-params)\n  (fixed-arity loop-fixed-arity?)\n  (procedure loop-procedure?)\n  (assign loop-assign)\n  (jump loop-jump))\n\n;; /**\n;;  * The loop a looping call made here jumps to: the innermost inline loop, or\n;;  * else this procedure. The lowering tags a call as looping only from inside\n;;  * the lambda it loops to, and an inline loop's body is that lambda's body.\n;;  * @param {form} form - The emission.\n;;  * @returns {loop-target} The target.\n;;  */\n(define (loop-target form)\n  (if (pair? (form-loop-targets form))\n      (car (form-loop-targets form))\n      (let ((ir (form-ir form)))\n        (make-loop-target\n          (lambda-params ir)\n          (not (lambda-rest ir))\n          #t\n          ;; The fast form boxes its parameters at the top of its loop, as on\n          ;; entry. The twin receives them from a frame already boxed and never\n          ;; boxes on entry, so it gives a boxed parameter a fresh box here --\n          ;; either way each iteration has its own, as a fresh call would.\n          (lambda (param value)\n            (list 'assign (js (js-local param))\n                  (if (and (twin? form) (boxed-local? form param)) (js \"[\" value \"]\") value)))\n          (if (twin? form) (list 'goto 0) (list 'text \"continue $loop;\"))))))\n\n;; /**\n;;  * The statements that make a tail call a jump: new values into the\n;;  * parameters, then the jump. Every argument is evaluated before any\n;;  * parameter is assigned, since an argument may read a parameter an earlier\n;;  * assignment would clobber -- a loop that swaps two arguments is the plain\n;;  * case. A value no assignment can disturb is used as it is, and a parameter\n;;  * passed back unchanged is not assigned at all.\n;;  * @param {form} form - The emission.\n;;  * @param {list} args - The argument expressions.\n;;  * @param {loop-target} target - The loop.\n;;  * @returns {list} The statements, in order.\n;;  */\n(define (loop-back! form args target)\n  (let walk ((args args) (params (loop-params target)) (copies '()) (assigns '()))\n    (if (null? args)\n        (append (reverse copies) (reverse assigns) (list (loop-jump target)))\n        (let ((value (car args)) (param (car params)))\n          (cond ((and (equal? value (js (js-local param))) (not (boxed-local? form param)))\n                 (walk (cdr args) (cdr params) copies assigns))\n                ((settled? value)\n                 (walk (cdr args) (cdr params) copies\n                       (cons ((loop-assign target) param value) assigns)))\n                (else\n                 (let ((t (temp! form)))\n                   (walk (cdr args) (cdr params)\n                         (cons (list 'assign (js t) value) copies)\n                         (cons ((loop-assign target) param (js t)) assigns)))))))))\n\n;; /**\n;;  * A call's loop tag: 'local or 'global when it is a tail call to the loop it\n;;  * is in, else #f. The calls lowering synthesizes carry no tag at all.\n;;  * @param {list} node - A `call` IR node.\n;;  * @returns {symbol|boolean} The tag.\n;;  */\n(define (call-loop node)\n  (let ((rest (cddddr node)))\n    (and (pair? rest) (car rest))))\n\n;; /**\n;;  * A call's source span: that of the application it was lowered from, or #f.\n;;  * The calls lowering synthesizes carry none.\n;;  * @param {list} node - A `call` IR node.\n;;  * @returns {object|boolean} The span.\n;;  */\n(define (call-span node)\n  (let ((rest (cddddr node)))\n    (and (pair? rest) (pair? (cdr rest)) (cadr rest))))\n\n;; /**\n;;  * Emits a `letrec` loop inside this procedure rather than as a procedure of\n;;  * its own. The lowering marks a group so when its one lambda is only ever\n;;  * running as a loop entered from here (`inline-loop?` in `ir.scm`), so its\n;;  * parameters become this procedure's locals, entering is their first\n;;  * assignment, and its looping calls jump back to its head. Nothing is\n;;  * allocated to enter it -- for `assq`, whose loop usually runs twice,\n;;  * entering was nearly the whole cost. The head does what a fresh call would:\n;;  * boxes boxed parameters and makes the boxes for internal definitions.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `letrec` IR node marked inline.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-inline-loop! form node)\n  (let* ((lam (car (caddr node)))\n         (params (lambda-params lam))\n         (entries (caddr (cadddr node)))\n         (entry (emit-operands! form entries)))\n    (for-each (lambda (param value)\n                (declare! form (js-local param))\n                (emit! form (list 'assign (js (js-local param)) value)))\n              params entry)\n    (if (and (not (twin? form)) (null? (form-doubles form)) (pure-loop-body? form (lambda-body lam))\n             (any inexact-constant? (cons (lambda-body lam) entries)))\n        (let ((doubles (double-loop-variables form params entries (lambda-body lam))))\n          (if (pair? doubles) (emit-double-loop! form params doubles (lambda-body lam)))))\n    (let ((target (enter-inline-loop! form params)))\n      (for-each (lambda (param)\n                  (if (boxed-local? form param)\n                      (emit! form (list 'assign (js (js-local param)) (js \"[\" (js-local param) \"]\")))))\n                params)\n      (emit-define-boxes! form (lambda-body lam))\n      (set-form-loop-targets! form (cons target (form-loop-targets form)))\n      (emit-statement! form (lambda-body lam))\n      (set-form-loop-targets! form (cdr (form-loop-targets form)))\n      ;; The fast form's loop is a labelled `for`, closed here; every path\n      ;; through its body has returned or jumped back by then. The twin's head\n      ;; is a block, and its blocks already end in jumps.\n      (if (not (twin? form)) (emit! form (list 'text \"}\"))))))\n\n;; /**\n;;  * Opens an inline loop and returns its target. In the fast form it is a\n;;  * labelled `for`; in the twin its head is a block of its own, since block\n;;  * zero is the procedure's entry, which a loop inside it must not re-run.\n;;  * @param {form} form - The emission.\n;;  * @param {list} params - The loop's parameters.\n;;  * @returns {loop-target} The target.\n;;  */\n(define (enter-inline-loop! form params)\n  (let ((plain (lambda (param value) (list 'assign (js (js-local param)) value))))\n    (if (twin? form)\n        (let ((head (new-block! form)))\n          (emit! form (list 'goto head))\n          (switch-to! form head)\n          (make-loop-target params #t #f plain (list 'goto head)))\n        (let ((label (begin (set-form-labels! form (+ (form-labels form) 1))\n                            (string-append \"$loop\" (number->string (form-labels form))))))\n          (emit! form (list 'text (string-append label \": for (;;) {\")))\n          (make-loop-target params #t #f plain (list 'text (string-append \"continue \" label \";\")))))))\n\n;; ---------------------------------------------------------------------------\n;; Loops on raw doubles\n;; ---------------------------------------------------------------------------\n;;\n;; An inexact real whose value is an integer is boxed\n;; (src/core/interpreter/number_representation.js), so a loop whose variables\n;; are inexact reals -- summing doubles, iterating a fractal -- allocates a box\n;; whenever one lands on an integer, and V8, finding a variable sometimes a\n;; double and sometimes a box, stops keeping its doubles in registers: a loop\n;; over integral doubles ran ten times slower boxed than raw. So the fast form\n;; runs such a loop on raw doubles first: those of its variables that provably\n;; stay inexact, and the `let`s in its body that hold such values, are held\n;; unboxed, and a value is boxed only where it leaves the loop. Only a loop\n;; whose body calls nothing but inlined primitives and itself, and makes no\n;; procedure, is run so: it has no point where a continuation could be\n;; captured, which would save the raw doubles into a frame as though they were\n;; Scheme values, and nothing outside it can see them. It is entered when its\n;; variables arrive inexact and the operators it uses are still the\n;; primitives; were one rebound while it runs, it boxes its variables and goes\n;; on as the ordinary loop, which follows it.\n\n;; /**\n;;  * The operators a raw double takes, by the Scheme name, and their\n;;  * JavaScript operators: arithmetic, then comparisons.\n;;  */\n(define double-operators\n  '((+ . \"+\") (- . \"-\") (* . \"*\") (< . \"<\") (> . \">\") (<= . \"<=\") (>= . \">=\") (= . \"===\")))\n\n;; /**\n;;  * Whether an operator is arithmetic a raw double takes, with an inexact\n;;  * result.\n;;  * @param {symbol} name - The Scheme name.\n;;  * @returns {boolean}\n;;  */\n(define (double-arithmetic? name)\n  (and (memq name '(+ - *)) #t))\n\n;; /**\n;;  * The JavaScript operator of one of `double-operators`.\n;;  * @param {symbol} name - The Scheme name.\n;;  * @returns {string}\n;;  */\n(define (operator-text name)\n  (cdr (assq name double-operators)))\n\n;; /**\n;;  * The primitive a call applies, by its name, where the call is inlined: to a\n;;  * global whose binding is guarded, with an expansion for these operands; or\n;;  * #f.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `call` IR node.\n;;  * @returns {symbol|boolean}\n;;  */\n(define (inlined-operator form node)\n  (let ((fn (cadr node))\n        (u (form-unit form)))\n    (and (eq? (car fn) 'global)\n         (memq (cadr fn) (unit-guarded u))\n         (let ((name (global-written-name (unit-library-globals u) (cadr fn))))\n           (and (inline-expansion name (caddr node)) name)))))\n\n;; /**\n;;  * Whether a node is an inexact real held as a raw double where `doubles`\n;;  * are held so: an inexact constant; such a local; or `+`, `-` or `*` of two\n;;  * operands, one such a node and the other one too or an exact integer\n;;  * constant, which R7RS makes an inexact result.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node.\n;;  * @param {list} doubles - The locals held as raw doubles.\n;;  * @returns {boolean}\n;;  */\n(define (double-node? form node doubles)\n  (case (car node)\n    ((const) (let ((v (cadr node))) (and (real? v) (inexact? v))))\n    ((local) (and (memq (cadr node) doubles) #t))\n    ((call)\n     (let ((op (and (not (call-loop node)) (inlined-operator form node)))\n           (args (caddr node)))\n       (and op (double-arithmetic? op) (= (length args) 2)\n            (or (and (double-node? form (car args) doubles) (real-operand? form (cadr args) doubles))\n                (and (real-operand? form (car args) doubles) (double-node? form (cadr args) doubles))))))\n    (else #f)))\n\n;; /**\n;;  * Whether a node can be an operand of arithmetic on raw doubles: one\n;;  * `double-node?` accepts, or an exact integer constant, which R7RS converts\n;;  * to inexact there.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node.\n;;  * @param {list} doubles - The locals held as raw doubles.\n;;  * @returns {boolean}\n;;  */\n(define (real-operand? form node doubles)\n  (or (double-node? form node doubles)\n      (and (eq? (car node) 'const) (exact-integer? (cadr node)))))\n\n;; /**\n;;  * The JavaScript expression of a node's raw double, for a node\n;;  * `real-operand?` accepts. Nothing in it has an effect, so it needs no\n;;  * temporaries.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node.\n;;  * @returns {list} The expression.\n;;  */\n(define (emit-double form node)\n  (case (car node)\n    ((const) (js \"(\" (js-number (inexact (cadr node))) \")\"))\n    ((local) (js (js-local (cadr node))))\n    (else\n     (let ((args (caddr node)))\n       (js \"(\" (emit-double form (car args)) \" \" (operator-text (inlined-operator form node)) \" \"\n           (emit-double form (cadr args)) \")\")))))\n\n;; /**\n;;  * Whether a `let` holds a raw double: inside a loop on raw doubles, where\n;;  * its initializer is one.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `let` IR node.\n;;  * @returns {boolean}\n;;  */\n(define (double-let? form node)\n  (and (pair? (form-doubles form))\n       (double-node? form (caddr node) (form-doubles form))))\n\n;; /**\n;;  * Binds a `let`'s local to its initializer's raw double, and emits what is\n;;  * in its scope with the local held raw.\n;;  * @param {form} form - The emission.\n;;  * @param {symbol} name - The local.\n;;  * @param {list} init - The initializer's IR node.\n;;  * @param {procedure} thunk - Emits the scope, and returns what it returns.\n;;  * @returns {*} What `thunk` returns.\n;;  */\n(define (with-double form name init thunk)\n  (emit! form (list 'assign (js (js-local name)) (emit-double form init)))\n  (let ((outer (form-doubles form)))\n    (set-form-doubles! form (cons name outer))\n    (let ((result (thunk)))\n      (set-form-doubles! form outer)\n      result)))\n\n;; /**\n;;  * Inside a loop on raw doubles, a call the raw doubles serve: arithmetic of\n;;  * them, its raw result boxed for the value wanted; or a comparison of them,\n;;  * made on the raw doubles; else #f, for the ordinary expansion.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - A `call` IR node.\n;;  * @returns {list|boolean} The expression, or #f.\n;;  */\n(define (emit-double-inline form node)\n  (let ((doubles (form-doubles form))\n        (args (caddr node)))\n    (cond ((double-node? form node doubles)\n           (js \"R.inexactReal(\" (emit-double form node) \")\"))\n          ((let ((op (and (not (call-loop node)) (inlined-operator form node))))\n             (and op (assq op double-operators) (not (double-arithmetic? op)) (= (length args) 2)\n                  (real-operand? form (car args) doubles) (real-operand? form (cadr args) doubles)\n                  (or (double-node? form (car args) doubles) (double-node? form (cadr args) doubles))\n                  op))\n           => (lambda (op)\n                (js \"(\" (emit-double form (car args)) \" \" (operator-text op) \" \"\n                    (emit-double form (cadr args)) \")\")))\n          (else #f))))\n\n;; /**\n;;  * Whether an IR node holds an inexact constant: a loop that does is one\n;;  * whose variables may be doubles. Any other -- counting over integers, say,\n;;  * whose variables could be inexact only if they arrived so -- is not run on\n;;  * raw doubles at all, rather than carry a second copy whose test fails.\n;;  * @param {list} node - An IR node.\n;;  * @returns {boolean}\n;;  */\n(define (inexact-constant? node)\n  (case (car node)\n    ((const) (let ((v (cadr node))) (and (real? v) (inexact? v))))\n    ((if) (any inexact-constant? (list (cadr node) (caddr node) (cadddr node))))\n    ((seq) (any inexact-constant? (cadr node)))\n    ((let) (or (inexact-constant? (caddr node)) (inexact-constant? (cadddr node))))\n    ((call) (any inexact-constant? (caddr node)))\n    (else #f)))\n\n;; /**\n;;  * Whether a loop's body calls nothing but inlined primitives and the loop\n;;  * itself, and makes no procedure: one that can run on raw doubles.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node of the body.\n;;  * @returns {boolean}\n;;  */\n(define (pure-loop-body? form node)\n  (case (car node)\n    ((const local global) #t)\n    ((if) (every (lambda (n) (pure-loop-body? form n)) (list (cadr node) (caddr node) (cadddr node))))\n    ((seq) (every (lambda (n) (pure-loop-body? form n)) (cadr node)))\n    ((let) (and (pure-loop-body? form (caddr node)) (pure-loop-body? form (cadddr node))))\n    ((call) (and (every (lambda (n) (pure-loop-body? form n)) (caddr node))\n                 (if (call-loop node)\n                     (eq? (call-loop node) 'local)\n                     (and (inlined-operator form node) #t))))\n    (else #f)))\n\n;; /**\n;;  * The locals a loop on raw doubles holds raw: the loop's variables that\n;;  * provably stay inexact -- each arrives as an inexact constant or as a value\n;;  * tested when the loop is entered, and each looping call passes it a raw\n;;  * double where the locals under consideration are raw -- and those locals\n;;  * bound outside the loop, tested on entry too, that some of the loop's\n;;  * variables need raw to be held raw themselves. None, unless some loop\n;;  * variable is held raw.\n;;  * @param {form} form - The emission.\n;;  * @param {list} params - The loop's variables.\n;;  * @param {list} entries - The IR nodes of their first values.\n;;  * @param {list} body - The loop's body.\n;;  * @returns {list} The locals.\n;;  */\n(define (double-loop-variables form params entries body)\n  (let* ((outer (filter (lambda (name) (not (boxed-local? form name)))\n                        (operand-locals form body params)))\n         (raw (double-fixed-point form params body\n                                  (append (filter-map (lambda (param entry)\n                                                        (and (or (not (eq? (car entry) 'const))\n                                                                 (let ((v (cadr entry)))\n                                                                   (and (real? v) (inexact? v))))\n                                                             param))\n                                                      params entries)\n                                          outer)))\n         (raw-params (lambda (locals) (filter (lambda (param) (memq param locals)) params))))\n    (if (null? (raw-params raw))\n        '()\n        ;; An outer local the loop's variables do not need raw would only be\n        ;; tested, and fail the test when it is exact: an exact bound the\n        ;; loop counts to, say.\n        (fold (lambda (local kept)\n                (if (memq local kept)\n                    (let ((without (double-fixed-point form params body (delete local kept))))\n                      (if (equal? (raw-params without) (raw-params kept)) without kept))\n                    kept))\n              raw outer))))\n\n;; /**\n;;  * The greatest fixed point of the locals a loop holds raw, from the\n;;  * candidates down: those the loop's variables no looping call passes a raw\n;;  * double are dropped until none is.\n;;  * @param {form} form - The emission.\n;;  * @param {list} params - The loop's variables.\n;;  * @param {list} body - The loop's body.\n;;  * @param {list} candidates - The locals taken to be raw at first.\n;;  * @returns {list} Those that are.\n;;  */\n(define (double-fixed-point form params body candidates)\n  (let ((failing (loop-back-failures form params candidates body)))\n    (if (null? failing)\n        candidates\n        (double-fixed-point form params body\n                            (filter (lambda (name) (not (memq name failing))) candidates)))))\n\n;; /**\n;;  * The locals bound outside a loop that its body passes to arithmetic or a\n;;  * comparison: the outer locals a loop on raw doubles could hold raw.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node of the body.\n;;  * @param {list} bound - The locals bound in the loop where it is.\n;;  * @returns {list} The locals, each once.\n;;  */\n(define (operand-locals form node bound)\n  (delete-duplicates\n    (let walk ((node node) (bound bound))\n      (case (car node)\n        ((if) (append-map (lambda (n) (walk n bound)) (list (cadr node) (caddr node) (cadddr node))))\n        ((seq) (append-map (lambda (n) (walk n bound)) (cadr node)))\n        ((let) (append (walk (caddr node) bound) (walk (cadddr node) (cons (cadr node) bound))))\n        ((call)\n         (let* ((args (caddr node))\n                (op (and (not (call-loop node)) (inlined-operator form node))))\n           (append (if (and op (assq op double-operators))\n                       (filter-map (lambda (arg)\n                                     (and (eq? (car arg) 'local) (not (memq (cadr arg) bound)) (cadr arg)))\n                                   args)\n                       '())\n                   (append-map (lambda (n) (walk n bound)) args))))\n        (else '())))))\n\n;; /**\n;;  * The variables of `candidates` some looping call in a body does not pass a\n;;  * raw double, where the candidates, and the `let`s holding raw doubles, are\n;;  * raw; all of the loop's variables for a looping call of another arity.\n;;  * @param {form} form - The emission.\n;;  * @param {list} params - The loop's variables.\n;;  * @param {list} candidates - Those taken to be raw.\n;;  * @param {list} node - An IR node of the body.\n;;  * @returns {list} The variables, perhaps repeated.\n;;  */\n(define (loop-back-failures form params candidates node)\n  (let walk ((node node) (doubles candidates))\n    (case (car node)\n      ((if) (append-map (lambda (n) (walk n doubles)) (list (cadr node) (caddr node) (cadddr node))))\n      ((seq) (append-map (lambda (n) (walk n doubles)) (cadr node)))\n      ((let) (append (walk (caddr node) doubles)\n                     (walk (cadddr node) (if (double-node? form (caddr node) doubles)\n                                             (cons (cadr node) doubles)\n                                             doubles))))\n      ((call)\n       (let ((args (caddr node)))\n         (append (append-map (lambda (n) (walk n doubles)) args)\n                 (cond ((not (call-loop node)) '())\n                       ((not (= (length args) (length params))) params)\n                       (else (filter-map (lambda (param arg)\n                                           (and (memq param candidates)\n                                                (not (double-node? form arg doubles))\n                                                param))\n                                         params args))))))\n      (else '()))))\n\n;; /**\n;;  * The indices of the globals a loop's body applies as operators of raw\n;;  * doubles, whose bindings the loop on raw doubles needs intact.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An IR node of the body.\n;;  * @returns {list} The indices, perhaps repeated.\n;;  */\n(define (operator-indices form node)\n  (case (car node)\n    ((if) (append-map (lambda (n) (operator-indices form n)) (list (cadr node) (caddr node) (cadddr node))))\n    ((seq) (append-map (lambda (n) (operator-indices form n)) (cadr node)))\n    ((let) (append (operator-indices form (caddr node)) (operator-indices form (cadddr node))))\n    ((call)\n     (append (append-map (lambda (n) (operator-indices form n)) (caddr node))\n             (let ((op (and (not (call-loop node)) (inlined-operator form node))))\n               (if (and op (assq op double-operators))\n                   (list (global-index (form-unit form) (cadr (cadr node))))\n                   '()))))\n    (else '())))\n\n;; /**\n;;  * Emits a loop on raw doubles before the ordinary one: entered when the\n;;  * loop's variables in `doubles` arrive inexact and the operators it uses\n;;  * are intact, its variables unboxed; it returns from the procedure as the\n;;  * loop would, and at the head of each iteration, were an operator rebound,\n;;  * leaves, boxes its variables and goes on in the ordinary loop.\n;;  *\n;;  * Nothing in the loop boxes a value or calls anything: a way out of it\n;;  * breaks out, and what it returns is made after the loop\n;;  * (`deferred-exits`), as the boxing for the ordinary loop is; and the test\n;;  * that an operator is intact is JavaScript's rather than a Scheme value's.\n;;  * Either, in a branch of the loop, kept V8 from holding the variables raw\n;;  * -- once the boxing had been inlined, as it is in a program that has made\n;;  * boxes before -- and made `sumfp` in benchmarks/r7rs/src seven times\n;;  * slower.\n;;  * @param {form} form - The emission.\n;;  * @param {list} params - The loop's variables.\n;;  * @param {list} doubles - Those held as raw doubles.\n;;  * @param {list} body - The loop's body.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-double-loop! form params doubles body)\n  (let* ((intact (map (lambda (index) (js \"W\" index \".intact\"))\n                      (delete-duplicates (operator-indices form body))))\n         (inexact-test (lambda (param)\n                         (let ((v (js-local param)))\n                           (js \"((typeof \" v \" === 'number' && !Number.isInteger(\" v \")) || \" v\n                               \" instanceof R.Flonum)\"))))\n         (number (begin (set-form-labels! form (+ (form-labels form) 1))\n                        (number->string (form-labels form))))\n         (label (string-append \"$doubles\" number))\n         (rebound (string-append \"$rebound\" number))\n         (body-statements\n          (collect-statements form\n            (lambda ()\n              (set-form-doubles! form doubles)\n              (set-form-loop-targets!\n                form\n                (cons (make-loop-target params #t #f\n                                        (lambda (param value) (list 'assign (js (js-local param)) value))\n                                        (list 'text (string-append \"continue \" label \";\")))\n                      (form-loop-targets form)))\n              (emit-statement! form body)\n              (set-form-loop-targets! form (cdr (form-loop-targets form)))\n              (set-form-doubles! form '()))))\n         (note (and (> (return-count body-statements) 1) (symbol->string (temp! form))))\n         (deferred (deferred-exits body-statements label note))\n         (statements\n          (append\n           (map (lambda (param)\n                  (let ((v (js-local param)))\n                    (list 'assign (js v) (js \"typeof \" v \" === 'number' ? \" v \" : \" v \".value\"))))\n                doubles)\n           (if (pair? intact) (list (list 'text (string-append rebound \": {\"))) '())\n           (list (list 'text (string-append label \": for (;;) {\")))\n           (if (pair? intact)\n               (list (list 'guarded (js \"!(\" (all-of intact) \")\")\n                           (list (list 'text (string-append \"break \" rebound \";\")))))\n               '())\n           (car deferred)\n           (list (list 'text \"}\"))\n           (exit-statements note (cdr deferred))\n           ;; Reached only by the break out of the block: every way out of the\n           ;; loop returns, and every other path through it goes round again.\n           (if (pair? intact)\n               (cons (list 'text \"}\")\n                     (map (lambda (param)\n                            (list 'assign (js (js-local param)) (js \"R.inexactReal(\" (js-local param) \")\")))\n                          doubles))\n               '()))))\n    (emit! form (list 'if (all-of (append (map inexact-test doubles) intact)) statements '()))))\n\n;; /**\n;;  * How many `return` statements there are among statements, in their\n;;  * branches too.\n;;  * @param {list} statements - The statements.\n;;  * @returns {integer}\n;;  */\n(define (return-count statements)\n  (fold (lambda (st n)\n          (+ n (case (car st)\n                 ((return) 1)\n                 ((if) (+ (return-count (caddr st)) (return-count (cadddr st))))\n                 ((guarded) (return-count (caddr st)))\n                 (else 0))))\n        0\n        statements))\n\n;; /**\n;;  * A loop's statements with each `return` among them replaced by a break out\n;;  * of the loop, which first notes which way out it is, in `note`, if there\n;;  * is more than one; and the returns, in the order the notes number them,\n;;  * for `exit-statements` to make after the loop. What a return reads -- the\n;;  * loop's variables and temporaries -- holds the same after the break.\n;;  * @param {list} statements - The loop's statements.\n;;  * @param {string} label - The loop's label.\n;;  * @param {string|boolean} note - The variable that notes the way out, or\n;;  *   #f if there is only one.\n;;  * @returns {pair} (statements . returns).\n;;  */\n(define (deferred-exits statements label note)\n  (let ((found (deferred-exits-in statements label note '())))\n    (cons (car found) (reverse (cdr found)))))\n\n;; /**\n;;  * `deferred-exits` from the returns found so far, which come back in\n;;  * reverse, the latest first.\n;;  * @param {list} statements - The statements.\n;;  * @param {string} label - The loop's label.\n;;  * @param {string|boolean} note - The variable that notes the way out.\n;;  * @param {list} found - The returns found so far, the latest first.\n;;  * @returns {pair} (statements . found).\n;;  */\n(define (deferred-exits-in statements label note found)\n  (let walk ((sts statements) (out '()) (found found))\n    (if (null? sts)\n        (cons (reverse out) found)\n        (let ((st (car sts)))\n          (case (car st)\n            ((return)\n             (walk (cdr sts)\n                   (cons (list 'text (string-append\n                                      (if note (string-append note \" = \" (number->string (length found)) \"; \") \"\")\n                                      \"break \" label \";\"))\n                         out)\n                   (cons st found)))\n            ((if)\n             (let* ((then-part (deferred-exits-in (caddr st) label note found))\n                    (else-part (deferred-exits-in (cadddr st) label note (cdr then-part))))\n               (walk (cdr sts)\n                     (cons (with-span-of st (cons* 'if (cadr st) (car then-part) (car else-part) (cddddr st)))\n                           out)\n                     (cdr else-part))))\n            ((guarded)\n             (let ((inner (deferred-exits-in (caddr st) label note found)))\n               (walk (cdr sts)\n                     (cons (with-span-of st (cons* 'guarded (cadr st) (car inner) (cdddr st))) out)\n                     (cdr inner))))\n            (else (walk (cdr sts) (cons st out) found)))))))\n\n;; /**\n;;  * The returns a loop's ways out make after it, each but the last on the\n;;  * note of which way out was taken.\n;;  * @param {string|boolean} note - The variable that holds the note, or #f\n;;  *   if there is only one way out.\n;;  * @param {list} returns - The returns, in the order the notes number them.\n;;  * @returns {list} The statements.\n;;  */\n(define (exit-statements note returns)\n  (let loop ((k 0) (returns returns))\n    (cond ((null? returns) '())\n          ((null? (cdr returns)) returns)\n          (else (cons (list 'guarded (js note \" === \" (number->string k)) (list (car returns)))\n                      (loop (+ k 1) (cdr returns)))))))\n\n;; /**\n;;  * A statement made from another, given the other's span.\n;;  * @param {list} old - The statement it is made from.\n;;  * @param {list} new - The statement.\n;;  * @returns {list} `new`.\n;;  */\n(define (with-span-of old new)\n  (let ((span (statement-span old)))\n    (if span (weak-table-set! statement-spans new span) #f)\n    new))\n\n;; ---------------------------------------------------------------------------\n;; The twin's blocks\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Allocates a block of the twin, returning its number, which is its `$pc`.\n;;  * @param {form} form - The emission.\n;;  * @returns {integer} The block number.\n;;  */\n(define (new-block! form)\n  (let ((n (form-block-count form)))\n    (set-form-block-count! form (+ n 1))\n    n))\n\n;; /**\n;;  * Finishes the current block and directs further statements into another.\n;;  * A block is never returned to once left, so finishing it is final.\n;;  * @param {form} form - The emission.\n;;  * @param {integer} n - The block to continue in.\n;;  * @returns {unspecified}\n;;  */\n(define (switch-to! form n)\n  (set-form-blocks! form (cons (cons (form-current form) (reverse (form-out form)))\n                               (form-blocks form)))\n  (set-form-current! form n)\n  (set-form-out! form '()))\n\n;; /**\n;;  * Records a suspension point and the block it resumes at, where the fast\n;;  * form of this procedure will find it.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - The call or capture IR node.\n;;  * @param {integer} block - The resume block.\n;;  * @returns {unspecified}\n;;  */\n(define (note-resume-site! form node block)\n  (set-form-sites! form (cons (cons node block) (form-sites form))))\n\n;; /**\n;;  * Ends a call in the twin: if the callee reported a capture, spill and\n;;  * return; otherwise pass the value to the block after the call, which is\n;;  * also where a resumed frame receives it.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - The call IR node.\n;;  * @param {symbol} result - The temporary holding the call's value.\n;;  * @returns {unspecified}\n;;  */\n(define (resume-after! form node result)\n  (let ((resume (new-block! form)))\n    (note-resume-site! form node resume)\n    (emit! form (list 'spill (js result) resume))\n    (emit! form (list 'assign (js \"$r\") (js result)))\n    (emit! form (list 'goto resume))\n    (switch-to! form resume)\n    (emit! form (list 'assign (js result) (js \"$r\")))))\n\n;; /**\n;;  * A tail `if` in the twin: a branch to one block per arm.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An `if` IR node.\n;;  * @returns {unspecified}\n;;  */\n(define (emit-twin-tail-if! form node)\n  (let* ((test (emit-value! form (cadr node)))\n         (then (new-block! form))\n         (other (new-block! form)))\n    (emit! form (list 'branch test then other))\n    (switch-to! form then)\n    (emit-statement! form (caddr node))\n    (switch-to! form other)\n    (emit-statement! form (cadddr node))))\n\n;; /**\n;;  * An `if` whose value is wanted, in the twin: each arm assigns a temporary\n;;  * and jumps to a join block. The assignment is emitted after the arm's\n;;  * value, into whatever block is current then -- a call in the arm resumes in\n;;  * a block of its own, and the value is only available there.\n;;  * @param {form} form - The emission.\n;;  * @param {list} node - An `if` IR node.\n;;  * @returns {list} The expression holding its value.\n;;  */\n(define (emit-twin-value-if! form node)\n  (let* ((test (emit-value! form (cadr node)))\n         (result (temp! form))\n         (then (new-block! form))\n         (other (new-block! form))\n         (join (new-block! form))\n         (arm (lambda (block branch)\n                (switch-to! form block)\n                (let ((value (emit-value! form branch)))\n                  (emit! form (list 'assign (js result) value))\n                  (emit! form (list 'goto join))))))\n    (emit! form (list 'branch test then other))\n    (arm then (caddr node))\n    (arm other (cadddr node))\n    (switch-to! form join)\n    (js result)))\n\n;; ---------------------------------------------------------------------------\n;; Whole procedures\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * The line that begins a procedure's fast form by testing how many\n;;  * arguments it was called with, and reports a wrong count as the\n;;  * interpreter reports one for a closure (`R.wrongArity`). Every call from\n;;  * Scheme arrives here, from compiled code directly and from the\n;;  * interpreter through the raw entry; a call from JavaScript arrives fitted\n;;  * to the parameters (`createCompiledProcedure` in\n;;  * `src/core/interpreter/values.js`). A procedure taking any number of\n;;  * arguments has no test.\n;;  *\n;;  * @param {list} ir - The lambda IR node.\n;;  * @returns {list} Lines of JavaScript: one, or none.\n;;  */\n(define (arity-guard ir)\n  (let ((required (length (lambda-params ir)))\n        (rest (lambda-rest ir)))\n    (if (and rest (= required 0))\n        '()\n        (list (string-append \"if (arguments.length \" (if rest \"< \" \"!== \") (number->string required)\n                             \") R.wrongArity(\" (js-string (or (lambda-name ir) \"anonymous\")) \", \"\n                             (number->string required) \", \" (if rest \"true\" \"false\")\n                             \", arguments.length);\")))))\n\n;; /**\n;;  * Binds a function to a JavaScript name, made under the Scheme name it is\n;;  * to show.\n;;  *\n;;  * A JavaScript engine names a stack frame, in a trace or a profile, by its\n;;  * function's `name`, which for a function made as a property's value is the\n;;  * property's key. So a function made under the Scheme procedure's name shows\n;;  * as that procedure, where a declaration would show as its JavaScript name,\n;;  * `$proc`, the same for every procedure. Setting `name` after the fact would\n;;  * show the same, but reconfigures the function's own property, which leaves\n;;  * every property of it slow to read -- and compiled code reads a callee's\n;;  * properties on every call.\n;;  *\n;;  * @param {string} binding - The JavaScript name it is bound to.\n;;  * @param {string} key - The name it shows as, as a JavaScript string\n;;  *   literal (`js-string`), made once for both of a procedure's forms.\n;;  * @param {string} header - The function's head, `function (...)`.\n;;  * @param {list} body - Its body's items.\n;;  * @returns {list} The items of a `const` declaration.\n;;  */\n(define (named-function binding key header body)\n  (list (string-append \"const \" binding \" = { \" key \": \" header \" {\")\n        (vector \"  \" body)\n        (string-append \"} }[\" key \"];\")))\n\n;; /**\n;;  * The fast form of a procedure, as a JavaScript function bound to a name.\n;;  *\n;;  * A boxed parameter arrives as a plain value and is boxed on entry, so the\n;;  * body, its closures and any frame it spills all reach one binding. A\n;;  * rest parameter arrives as JavaScript arguments and is made a Scheme list.\n;;  * A procedure with a tail call to itself runs its body in a loop that takes\n;;  * in everything a fresh call would redo; only the declarations stay outside.\n;;  *\n;;  * @param {string} name - The JavaScript name it is bound to.\n;;  * @param {string} shown - The name it shows as, as a JavaScript string\n;;  *   literal (`named-function`).\n;;  * @param {list} ir - The lambda IR node.\n;;  * @param {unit} u - The unit.\n;;  * @param {string} path - Its position in the tree of procedures.\n;;  * @returns {list} Its items.\n;;  */\n(define (fast-form name shown ir u path)\n  (let ((form (new-form name ir u 'fast path)))\n    (emit-define-boxes! form (lambda-body ir))\n    (emit-statement! form (lambda-body ir))\n    (let* ((rest (lambda-rest ir))\n           (params (map js-name (lambda-params ir)))\n           (signature (string-join (append params\n                                           (if rest (list (string-append \"...\" (js-name rest) \"$raw\")) '()))\n                                   \", \"))\n           (prologue\n             (append\n               (if rest\n                   (let ((list-expr (string-append \"R.listFrom(\" (js-name rest) \"$raw)\")))\n                     (list (string-append \"let \" (js-name rest) \" = \"\n                                          (if (boxed-local? form rest)\n                                              (string-append \"[\" list-expr \"]\")\n                                              list-expr)\n                                          \";\")))\n                   '())\n               (map (lambda (p) (string-append (js-name p) \" = [\" (js-name p) \"];\"))\n                    (filter (lambda (p) (boxed-local? form p)) (lambda-params ir)))))\n           (declared (reverse (form-declared form)))\n           (declaration (if (null? declared)\n                            '()\n                            (list (string-append \"let \" (string-join (map symbol->string declared) \", \") \";\"))))\n           (body (append-map (lambda (st) (statement-lines form st)) (reverse (form-out form))))\n           (entry (append (arity-guard ir)\n                          (depth-entry form (append params (if rest (list (string-append \"...\" (js-name rest) \"$raw\")) '())))))\n           (items (if (form-loops form)\n                      (append declaration entry\n                              (list \"$loop: for (;;) {\" (vector \"  \" (append prologue body)) \"}\"))\n                      (append declaration entry prologue body))))\n      (named-function name shown (string-append \"function (\" signature \")\") items))))\n\n;; /**\n;;  * The resumable form of a procedure, as a JavaScript function bound to a\n;;  * name.\n;;  *\n;;  * It takes no argument list: everything, a rest parameter included, arrives\n;;  * in the frame `$f`. Generating it records, in the unit, where each call site\n;;  * resumes and which locals a frame suspended there must save -- those live\n;;  * at the resume block, and no others -- and the fast form reads both.\n;;  * Restoring names every local; one that was not saved comes back undefined,\n;;  * which is safe because it is dead there.\n;;  *\n;;  * @param {string} name - The JavaScript name it is bound to.\n;;  * @param {string} shown - The name it shows as, as a JavaScript string\n;;  *   literal (`named-function`): the procedure's, as the fast form's, since\n;;  *   a frame resumed is the same procedure's frame.\n;;  * @param {list} ir - The lambda IR node.\n;;  * @param {unit} u - The unit.\n;;  * @param {string} path - Its position in the tree of procedures.\n;;  * @returns {list} Its items.\n;;  */\n(define (twin-form name shown ir u path)\n  (let ((form (new-form name ir u 'twin path)))\n    ;; In block zero, so a fresh entry makes the boxes and a resume, which\n    ;; always enters later, takes them from the frame.\n    (emit-define-boxes! form (lambda-body ir))\n    (emit-statement! form (lambda-body ir))\n    (switch-to! form -1)\n    (let* ((blocks (map cdr (sort-blocks (filter (lambda (b) (>= (car b) 0)) (form-blocks form)))))\n           (rest (lambda-rest ir))\n           (slots (delete-duplicates (append (reverse (form-declared form))\n                                             (map js-local (lambda-params ir))\n                                             (if rest (list (js-local rest)) '()))\n                                     eq?))\n           (live (live-in blocks))\n           (sites (reverse (form-sites form))))\n      (set-form-frames! form\n        (map (lambda (site)\n               (cons (cdr site) (live-among live (cdr site) slots)))\n             sites))\n      ;; The fast form spills into the frame this one restores, so each of its\n      ;; suspension points saves exactly what this one expects there.\n      (for-each (lambda (site)\n                  (set-unit-resume-points! u\n                    (cons (cons (car site) (cons (cdr site) (form-frame form (cdr site))))\n                          (unit-resume-points u))))\n                sites)\n      (let ((names (string-join (map symbol->string (append slots '($r))) \", \"))\n            (cases (let number ((blocks blocks) (i 0))\n                     (if (null? blocks)\n                         '()\n                         (cons (string-append \"    case \" (number->string i) \":\")\n                               (cons (vector \"      \" (append-map (lambda (st) (statement-lines form st))\n                                                                  (car blocks)))\n                                     (number (cdr blocks) (+ i 1))))))))\n        (named-function name shown \"function ($pc, $f)\"\n          (append (list (string-append \"let \" names \";\")\n                        (string-append \"({ \" names \" } = $f);\"))\n                  (depth-entry form '())\n                  (list \"for (;;) switch ($pc) {\")\n                  cases\n                  (list (string-append \"    default: throw new Error('\" name \": bad resume point ' + $pc);\")\n                        \"}\")))))))\n\n;; /**\n;;  * The locals a frame suspended at a resume block saves.\n;;  * @param {form} form - A twin emission, after liveness.\n;;  * @param {integer} block - The resume block.\n;;  * @returns {list} The locals, in declaration order.\n;;  */\n(define (form-frame form block)\n  (cond ((assv block (form-frames form)) => cdr) (else '())))\n\n;; /**\n;;  * Blocks sorted by number.\n;;  * @param {list} blocks - (number . statements) pairs.\n;;  * @returns {list} The same pairs, in order.\n;;  */\n(define (sort-blocks blocks)\n  (let ((table (make-vector (length blocks) #f)))\n    (for-each (lambda (b) (vector-set! table (car b) b)) blocks)\n    (vector->list table)))\n\n;; ---------------------------------------------------------------------------\n;; Nested procedures and the unit\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * The factory for a nested procedure, emitting it the first time it is asked\n;;  * for. Both forms of a parent ask for the same node and get the same one.\n;;  * Recorded before emitting, so anything reached while emitting it finds the\n;;  * name instead of starting again.\n;;  * @param {unit} u - The unit.\n;;  * @param {string} proc - The nested procedure's name.\n;;  * @param {string} path - Its position in the tree of procedures.\n;;  * @param {list} lam - Its lambda IR node.\n;;  * @returns {string} The factory's name.\n;;  */\n(define (factory-for! u proc path lam)\n  (or (cond ((assq lam (unit-emitted u)) => cdr) (else #f))\n      (let ((factory (string-append \"$mk\" proc)))\n        (set-unit-emitted! u (cons (cons lam factory) (unit-emitted u)))\n        (let ((items (render-factory u factory proc path lam)))\n          (set-unit-factories! u (cons items (unit-factories u))))\n        factory)))\n\n;; /**\n;;  * A nested procedure as a factory over its free variables. Both forms go\n;;  * inside, and what the factory returns is the procedure made over the fast\n;;  * form, which faces JavaScript with the fast form as its raw entry\n;;  * (`markProcedure` in `src/compiler/runtime.js`). A `letrec`\n;;  * name the procedure refers to only itself by is declared here and assigned\n;;  * before returning, so the recursive call resolves lexically -- a named\n;;  * `let` is this shape, and usually a hot loop.\n;;  * @param {unit} u - The unit.\n;;  * @param {string} factory - The factory's name.\n;;  * @param {string} proc - The procedure's name.\n;;  * @param {string} path - Its position in the tree of procedures.\n;;  * @param {list} lam - Its lambda IR node.\n;;  * @returns {list} Its items.\n;;  */\n(define (render-factory u factory proc path lam)\n  (let* ((plan (unit-plan u))\n         (params (map js-name (plan-free-of plan lam)))\n         (own (map js-name (plan-self-of plan lam)))\n         ;; A procedure made by a named `let` or an internal definition shows\n         ;; as its name; any other, as `anonymous`, as the expander names it.\n         (shown (js-string (or (lambda-name lam) \"anonymous\")))\n         (twin (twin-form (string-append proc \"$r\") shown lam u path))\n         (fast (fast-form proc shown lam u path))\n         (value (string-append proc \"$js\"))\n         (items (append\n                  (if (null? own) '() (list (string-append \"let \" (string-join own \", \") \";\")))\n                  (list (vector \"\" fast)\n                        (string-append \"const \" value \" = R.markProcedure(\" proc \", \"\n                                       (js-string (or (lambda-name lam) \"anonymous\")) \", E\"\n                                       (if (lambda-rest lam) \", true\" \"\") \");\")\n                        (vector \"\" twin)\n                        (string-append value \".$resume = \" proc \"$r;\"))\n                  (map (lambda (self) (string-append self \" = \" value \";\")) own)\n                  (list (string-append \"return \" value \";\")))))\n    (list (string-append \"function \" factory \"(\" (string-join params \", \") \") {\")\n          (vector \"  \" items)\n          \"}\")))\n\n;; /**\n;;  * The runtime values call sites and inline expansions use, each with the\n;;  * local generated code names it by.\n;;  *\n;;  * Read from `R` once per procedure rather than at every call site: loading a\n;;  * property of the runtime module on every call was worth up to 1.08x on\n;;  * call-heavy code.\n;;  */\n(define runtime-constants\n  '(($TailCall . \"R.TailCall\") ($step . \"R.step\")\n    ($UNWIND . \"R.UNWIND\") ($RAW . \"R.SCHEME_RAW_CALL\")\n    ($vectorRef . \"R.vectorRef\") ($vectorSet . \"R.vectorSet\")\n    ($add . \"R.add\") ($sub . \"R.sub\") ($mul . \"R.mul\")\n    ($lt . \"R.lt\") ($gt . \"R.gt\") ($le . \"R.le\") ($ge . \"R.ge\") ($numEq . \"R.numEq\")\n    ($stack . \"R.stack\") ($flush . \"R.flush\") ($tailCall . \"R.tailCall\") ($PRIM . \"R.SCHEME_PRIMITIVE\")\n    ($notProc . \"R.notAProcedure\") ($foreign . \"R.callForeign\")))\n\n;; /**\n;;  * The declaration of the runtime values a unit's code uses, in the order\n;;  * `runtime-constants` lists them.\n;;  *\n;;  * The emitter notes each one as it writes it (`runtime`), rather than\n;;  * searching the finished code for them: the code of a large procedure runs\n;;  * to hundreds of kilobytes, and reading it back a character at a time was\n;;  * about a quarter of what compiling cost the canonical `scheme` program\n;;  * under the tier.\n;;  *\n;;  * @param {list} used - The local names of the runtime values used, as\n;;  *   symbols.\n;;  * @returns {string} A `const` declaration, or \"\" if it uses none.\n;;  */\n(define (runtime-prelude used)\n  (let ((declared (filter (lambda (c) (memq (car c) used)) runtime-constants)))\n    (if (null? declared)\n        \"\"\n        (string-append \"const \"\n                       (string-join (map (lambda (c) (string-append (symbol->string (car c)) \" = \" (cdr c)))\n                                         declared)\n                                    \", \")\n                       \";\"))))\n\n;; /**\n;;  * Generates the JavaScript for one lowered top-level procedure.\n;;  *\n;;  * The result is the body of a function taking the runtime `R`, the\n;;  * environment `E` globals resolve in, and the constant pool `K`, and\n;;  * returning the procedure. Each global is read through a cell, which its\n;;  * resolver `G` finds on the first read, so a forward reference compiles and\n;;  * a later redefinition or assignment is seen. A global with an inline\n;;  * expansion also gets its primitive's cell and the primitive, for the\n;;  * expansion's guard.\n;;  *\n;;  * @param {list} ir - The procedure's lambda IR node.\n;;  * @param {list} globals - The globals it references, as symbols.\n;;  * @param {list} library-globals - (key name . env) for each that is a\n;;  *   library's own binding, read from the library's environment.\n;;  * @param {string} name - Its display name.\n;;  * @param {list} guarded - The globals with an expansion that are bound to\n;;  *   their primitive here, which the caller finds out from the environment.\n;;  * @returns {list} (source constants spans): the source, its constants, and\n;;  *   the span of each of its lines, or #f, which its source map is written\n;;  *   from.\n;;  */\n(define (generate-unit ir globals library-globals name guarded)\n  (let* ((u (make-unit (plan-lifting ir) globals library-globals (global-indices globals) guarded\n                       '() '() '() '() '()))\n         ;; The twin first: generating it decides where each call site resumes\n         ;; and what a frame saves there, which the fast form needs in order to\n         ;; suspend itself.\n         (key (js-string name))\n         (twin (twin-form \"$proc$r\" key ir u \"\"))\n         (fast (fast-form \"$proc\" key ir u \"\"))\n         (accessors\n           (append-map\n             (lambda (g)\n               (let* ((i (global-index u g))\n                      (library (assq g library-globals))\n                      (literal (js-string (symbol->string (if library (cadr library) g))))\n                      (holder (if library (constant u (cddr library)) \"E\")))\n                 (cons (string-append \"let C\" i \" = R.UNRESOLVED; const G\" i\n                                      \" = () => (C\" i \" = R.globalCell(\" holder \", \" literal \")).v;\")\n                       (if (memq g guarded)\n                           (list (string-append \"const W\" i \" = R.primitiveCell(\" literal \"), P\" i\n                                                \" = W\" i \".primitive;\"))\n                           '()))))\n             globals))\n         (prelude (runtime-prelude (unit-runtime u)))\n         (rendered\n           (render-items\n             (append (if (string=? prelude \"\") '() (list prelude))\n                     accessors\n                     (map (lambda (factory) (vector \"\" factory)) (reverse (unit-factories u)))\n                     (list (vector \"\" fast)\n                           (vector \"\" twin)\n                           (string-append \"const $proc$js = R.markProcedure($proc, \" key \", E\"\n                                          (if (lambda-rest ir) \", true\" \"\") \");\")\n                           \"$proc$js.$resume = $proc$r;\"\n                           \"return $proc$js;\")))))\n    (list (car rendered) (reverse (unit-constants u)) (cdr rendered))))\n",
  "inline.scm": ";;; inline.scm -- inline expansions for primitives, used by the emitter.\n;;;\n;;; Profiling the first compiler tier put 25% of its runtime in primitive calls\n;;; and only 17% in the generated code itself. A call such as `(+ a b)` was\n;;; going through a variadic primitive that allocates a rest array, type-checks\n;;; each argument and dispatches across the numeric tower -- all to add two\n;;; integers.\n;;;\n;;; Each entry here gives a fast path for the overwhelmingly common operand\n;;; shape and falls back to the real primitive for everything else, so the\n;;; numeric tower's semantics are preserved rather than approximated: a\n;;; rational, a flonum, a complex or a wrong type all take the fallback and\n;;; behave exactly as they do in the interpreter.\n;;;\n;;; Every expansion is also guarded on the binding, by the emitter. Scheme\n;;; allows `+` to be redefined, so an expansion is used only while `+` still\n;;; denotes the primitive, and otherwise calls through whatever `+` is bound to\n;;; now. The guard is normally one property load, on a cell the interpreter\n;;; clears the first time anything rebinds the name\n;;; (`src/core/interpreter/primitive_bindings.js`).\n;;;\n;;; An entry is (name arity test value), or (name arity test value applies?).\n;;; `test` and `value` take the operands, as expressions in the emitter's\n;;; representation (see `emit.scm`), and return an expression: `test` the\n;;; run-time condition under which the fast path is valid, or #f when it always\n;;; is; `value` the fast path itself. A `value` that is a symbol instead names\n;;; the runtime helper the fast path calls with the operands, by the local name\n;;; generated code knows it by (`runtime-constants` in `emit.scm`), so that the\n;;; emitter declares the helper where it is used; and one that is a pair, of\n;;; such a name and a procedure, is an expression the procedure makes of the\n;;; operands, the helper's name and the operands' IR nodes, for a fast path\n;;; that calls the helper only for some of its operands. `applies?`, where there is\n;;; one, takes the operands' IR nodes and decides at compile time whether to\n;;; expand the call at all, for an expansion that is only worth having for some\n;;; operands.\n\n;; /**\n;;  * The JavaScript literal of an operand that is an inexact real constant,\n;;  * which is a double in arithmetic, though an integral one is boxed where it\n;;  * is a value (`constant` in emit.scm); #f for any other operand.\n;;  * @param {list} node - The operand's IR node.\n;;  * @returns {list|boolean} An expression, or #f.\n;;  */\n(define (inexact-literal node)\n  (and (eq? (car node) 'const)\n       (let ((v (cadr node)))\n         (and (real? v) (inexact? v) (js \"(\" (js-number v) \")\")))))\n\n;; /**\n;;  * Expressions joined by `&&`, or `true` for none.\n;;  * @param {list} exprs - The expressions.\n;;  * @returns {list} An expression.\n;;  */\n(define (all-of exprs)\n  (if (null? exprs)\n      (js \"true\")\n      (fold (lambda (e acc) (js acc \" && \" e)) (car exprs) (cdr exprs))))\n\n;; /**\n;;  * A binary operation one of whose operands is an inexact constant: inline\n;;  * on the other's double, whether that operand is a number or a box, since\n;;  * the result is inexact whatever it is -- `fibfp` in benchmarks/r7rs/src\n;;  * passes boxes to `(- n 1.)` and `(< n 2.)` on every call -- and otherwise,\n;;  * for a BigInt, a rational, a complex number or a wrong type, the runtime's.\n;;  * Two constants are computed on their doubles alone.\n;;  * @param {list} ops - The operand expressions.\n;;  * @param {list} nodes - Their IR nodes, at least one an inexact constant.\n;;  * @param {string} op - The JavaScript operator.\n;;  * @param {symbol} helper - The runtime operation's local name.\n;;  * @param {procedure} finish - The result made of the operator's expression\n;;  *   on the two doubles.\n;;  * @returns {list} An expression.\n;;  */\n(define (against-inexact-constant ops nodes op helper finish)\n  (let* ((ka (inexact-literal (car nodes)))\n         (kb (inexact-literal (cadr nodes)))\n         (on (lambda (a b) (finish (js (or ka a) \" \" op \" \" (or kb b))))))\n    (if (and ka kb)\n        (on ka kb)\n        (let ((x (if ka (cadr ops) (car ops)))\n              (on-x (lambda (v) (if ka (on ka v) (on v kb)))))\n          (js \"(typeof \" x \" === 'number' ? \" (on-x x)\n              \" : \" x \" instanceof R.Flonum ? \" (on-x (js x \".value\"))\n              \" : \" helper \"(\" (car ops) \", \" (cadr ops) \"))\")))))\n\n;; /**\n;;  * Whether either of two operands is an inexact constant.\n;;  * @param {list} nodes - The operands' IR nodes.\n;;  * @returns {boolean}\n;;  */\n(define (inexact-constant-operand? nodes)\n  (or (inexact-literal (car nodes)) (inexact-literal (cadr nodes))))\n\n;; /**\n;;  * A binary arithmetic operation: inline, the JavaScript operator on two\n;;  * numbers whose result needs no deciding -- one that is not an integer, an\n;;  * inexact real, or an integer in the safe range of two integers, an exact\n;;  * integer -- which V8 keeps in a register; otherwise the runtime's, which\n;;  * decides exactness, boxes an inexact integer, takes BigInts and boxes, and\n;;  * hands anything else to the primitive (`add` and the rest in\n;;  * src/compiler/runtime.js). A product of zero is decided by the runtime,\n;;  * which gives exact zero rather than JavaScript's -0. Against an inexact\n;;  * constant the result is inexact, and is boxed where it is an integer\n;;  * (`against-inexact-constant`).\n;;  * @param {string} name - The Scheme name.\n;;  * @param {string} op - The JavaScript operator.\n;;  * @param {symbol} local - The runtime operation's local name.\n;;  * @returns {list} A table entry.\n;;  */\n(define (numeric-arithmetic name op local)\n  (list name 2 (lambda (ops) #f)\n        (cons local\n              (lambda (ops helper nodes)\n                (if (inexact-constant-operand? nodes)\n                    (against-inexact-constant ops nodes op helper\n                                              (lambda (e) (js \"R.inexactReal(\" e \")\")))\n                    (let* ((a (car ops)) (b (cadr ops))\n                           (r (js \"(\" a \" \" op \" \" b \")\")))\n                      (js \"(typeof \" a \" === 'number' && typeof \" b \" === 'number'\"\n                          \" && (!Number.isInteger(\" r \")\"\n                          \" || (Number.isSafeInteger(\" r \")\"\n                          (if (string=? op \"*\") (js \" && \" r \" !== 0\") (js \"\"))\n                          \" && Number.isInteger(\" a \") && Number.isInteger(\" b \"))\"\n                          \")) ? \" r \" : \" helper \"(\" a \", \" b \")\")))))))\n\n;; /**\n;;  * A numeric comparison: inline, the JavaScript operator on two numbers,\n;;  * which compares across exactness as the tower does -- `=` as `===` agrees\n;;  * on NaN, and every ordering with a NaN is false -- and against an inexact\n;;  * constant on a box's double too (`against-inexact-constant`); otherwise\n;;  * the runtime's (`lt` and the rest in src/compiler/runtime.js).\n;;  * @param {string} name - The Scheme name.\n;;  * @param {string} op - The JavaScript operator.\n;;  * @param {symbol} local - The runtime operation's local name.\n;;  * @returns {list} A table entry.\n;;  */\n(define (numeric-comparison name op local)\n  (list name 2 (lambda (ops) #f)\n        (cons local\n              (lambda (ops helper nodes)\n                (if (inexact-constant-operand? nodes)\n                    (against-inexact-constant ops nodes op helper (lambda (e) e))\n                    (let ((a (car ops)) (b (cadr ops)))\n                      (js \"(typeof \" a \" === 'number' && typeof \" b \" === 'number') ? \"\n                          a \" \" op \" \" b \" : \" helper \"(\" a \", \" b \")\")))))))\n\n;; /**\n;;  * An expansion whose fast path is exactly what the primitive computes for\n;;  * every input, so only the binding guard applies.\n;;  * @param {string} name - The Scheme name.\n;;  * @param {integer} arity - Its argument count.\n;;  * @param {procedure} value - Operands to the fast-path expression.\n;;  * @returns {list} A table entry.\n;;  */\n(define (total name arity value)\n  (list name arity (lambda (ops) #f) value))\n\n;; /**\n;;  * An expansion whose fast path calls a runtime helper with the operands, the\n;;  * helper doing the primitive's work for every input or handing it to the\n;;  * primitive, so only the binding guard applies.\n;;  * @param {string} name - The Scheme name.\n;;  * @param {integer} arity - Its argument count.\n;;  * @param {symbol} local - The helper's local name in generated code.\n;;  * @returns {list} A table entry.\n;;  */\n(define (helper name arity local)\n  (total name arity local))\n\n;; /**\n;;  * When an exact division's fast path holds: two integers held as numbers --\n;;  * not an integral inexact, which is a box, nor a BigInt -- and a divisor\n;;  * that is not zero, for which `%` is exact.\n;;  * @param {list} ops - The operands.\n;;  * @returns {list} An expression.\n;;  */\n(define (exact-division-test ops)\n  (let ((a (car ops)) (b (cadr ops)))\n    (js \"typeof \" a \" === 'number' && typeof \" b \" === 'number'\"\n        \" && Number.isInteger(\" a \") && Number.isInteger(\" b \") && \" b \" !== 0\")))\n\n;; /**\n;;  * Whether an operand is a constant whose identity is its value: a symbol, a\n;;  * boolean or the empty list. `eqv?` against one is JavaScript `===`, since\n;;  * symbols are interned and the other two are immediates; against a number\n;;  * or a character it is not, since those compare by value.\n;;  * @param {list} node - An operand's IR node.\n;;  * @returns {boolean}\n;;  */\n(define (identity-constant? node)\n  (and (eq? (car node) 'const)\n       (let ((value (cadr node)))\n         (or (symbol? value) (boolean? value) (null? value)))))\n\n;; /**\n;;  * An operand as what a property is read of: in parentheses if it is a\n;;  * number written out, since JavaScript reads `1.car` as a malformed number\n;;  * and `-2.cdr` as the negation of a property of 2.\n;;  * @param {list} op - The operand's expression.\n;;  * @returns {list} An expression.\n;;  */\n(define (property-object op)\n  (let ((first (and (pair? op) (car op))))\n    (if (and (string? first)\n             (> (string-length first) 0)\n             (let ((c (string-ref first 0)))\n               (or (char-numeric? c) (char=? c #\\-))))\n        (js \"(\" op \")\")\n        op)))\n\n;; /**\n;;  * Every primitive with an inline expansion.\n;;  */\n(define inline-expansions\n  (list\n    ;; Arithmetic and comparison: inline on two numbers, the runtime's\n    ;; otherwise, tower fallback.\n    (numeric-arithmetic '+ \"+\" '$add)\n    (numeric-arithmetic '- \"-\" '$sub)\n    (numeric-arithmetic '* \"*\" '$mul)\n    (numeric-comparison '< \"<\" '$lt)\n    (numeric-comparison '> \">\" '$gt)\n    (numeric-comparison '<= \"<=\" '$le)\n    (numeric-comparison '>= \">=\" '$ge)\n    (numeric-comparison '= \"===\" '$numEq)\n    ;; Pairs: the representation is a plain class, so these are direct.\n    (list 'car 1\n          (lambda (ops) (js (car ops) \" instanceof R.Cons\"))\n          (lambda (ops) (js (property-object (car ops)) \".car\")))\n    (list 'cdr 1\n          (lambda (ops) (js (car ops) \" instanceof R.Cons\"))\n          (lambda (ops) (js (property-object (car ops)) \".cdr\")))\n    (total 'cons 2 (lambda (ops) (js \"new R.Cons(\" (car ops) \", \" (cadr ops) \")\")))\n    (total 'pair? 1 (lambda (ops) (js (car ops) \" instanceof R.Cons\")))\n    (total 'null? 1 (lambda (ops) (js (car ops) \" === null\")))\n    (total 'not 1 (lambda (ops) (js (car ops) \" === false\")))\n    (total 'eq? 2 (lambda (ops) (js (car ops) \" === \" (cadr ops))))\n    ;; Vectors are JavaScript arrays. An access calls a runtime helper rather\n    ;; than the primitive through the generic call path, which cost\n    ;; vector-heavy programs up to half their time; the helper checks the\n    ;; common case and passes everything else to the primitive, so every error\n    ;; is its own.\n    (helper 'vector-ref 2 '$vectorRef)\n    (helper 'vector-set! 3 '$vectorSet)\n    (list 'vector-length 1\n          (lambda (ops) (js \"Array.isArray(\" (car ops) \")\"))\n          (lambda (ops) (js (property-object (car ops)) \".length\")))\n    ;; Exact division, inline on two integers and a divisor that is not zero,\n    ;; as the primitives' own fast paths are (`dividingIntegers` in\n    ;; src/core/primitives/math.js), the primitive otherwise: V8 in Node inlines\n    ;; the primitive into compiled code, and V8 in Chrome does not, where\n    ;; `benchmarks/r7rs/src/bv2string.scm` spent nearly half its time calling\n    ;; it. `+ 0` makes JavaScript's -0 exact zero; `modulo` takes the sign of\n    ;; the divisor, adding it to a remainder of the other sign.\n    (list 'quotient 2 exact-division-test\n          (lambda (ops) (let ((a (car ops)) (b (cadr ops)))\n                          (js \"((\" a \" - \" a \" % \" b \") / \" b \" + 0)\"))))\n    (list 'remainder 2 exact-division-test\n          (lambda (ops) (js \"(\" (car ops) \" % \" (cadr ops) \" + 0)\")))\n    (list 'modulo 2 exact-division-test\n          (lambda (ops) (let ((a (car ops)) (b (cadr ops)))\n                          (js \"((\" a \" % \" b \") * \" b \" < 0 ? \" a \" % \" b \" + \" b \" : \" a \" % \" b \" + 0)\"))))\n    ;; Only against a constant `===` is exact for. That is what `case` tests\n    ;; its key with, one datum at a time; anything else calls the primitive.\n    (list 'eqv? 2\n          (lambda (ops) #f)\n          (lambda (ops) (js (car ops) \" === \" (cadr ops)))\n          (lambda (args) (any identity-constant? args)))))\n\n;; /**\n;;  * The expansion for a call, if this primitive has one for these operands.\n;;  * @param {symbol} name - The global called.\n;;  * @param {list} args - The operands' IR nodes.\n;;  * @returns {list|boolean} The table entry, or #f.\n;;  */\n(define (inline-expansion name args)\n  (let ((entry (assq name inline-expansions)))\n    (and entry\n         (= (cadr entry) (length args))\n         (let ((applies? (cddddr entry)))\n           (or (null? applies?) ((car applies?) args)))\n         entry)))\n\n;; /**\n;;  * The names that have an expansion at any arity, for the JavaScript side\n;;  * to find out which of them are bound to their primitive.\n;;  */\n(define (inline-expansion-names) (map car inline-expansions))\n",
  "ir.scm": ";;; ir.scm -- lowering core forms to compiler IR.\n;;;\n;;; This is the compiler's lowering pass, and it is Scheme because the compiler\n;;; is meant to end up in Scheme. It lowers the core forms the expander,\n;;; `(scheme-js expander)`, makes of a program, and the IR it returns goes,\n;;; still as Scheme data, to code generation in `emit.scm`.\n;;;\n;;; ## Running this at a useful speed\n;;;\n;;; A self-hosted pass has to be compiled by the tier it is part of, and the\n;;; tier has to reach the standard library too. Lowering calls `memq` and `assq`\n;;; on every scope lookup and every global it records, and those are themselves\n;;; Scheme; with them interpreted, this module crosses into the interpreter on\n;;; its hottest path and the tier is worth 1.5x. With them compiled it is worth\n;;; 20x. Both this file and the library are therefore compiled at build time\n;;; into `src/packaging/`, and `lowering.js` installs that code rather than\n;;; generating any.\n;;;\n;;; The bootstrap underneath is the interpreter, which can always run this file\n;;; from source. That is what makes the chain terminate without a compiler\n;;; written in another language: a checkout with no prebuilt code at all still\n;;; compiles, slowly, and the first thing it produces is the code that makes it\n;;; fast.\n;;;\n;;; ## Two constraints the language imposes\n;;;\n;;;   - Sets and maps here are lists, although SRFI 125 hash tables exist,\n;;;     because the lists are short. Measured over the 993 lambdas in\n;;;     `npm run benchmark:self-host`, a scope lookup's `assq` scans 1.85\n;;;     entries on average and a `memq` on the lowering state 6.8; even\n;;;     `earley:make-parser`, the deepest nesting in the corpus, averages 2.5.\n;;;     A compiled hash-table lookup costs about 100 ns, which a scan that\n;;;     short should never need. What the lists do cost is the compiled `assq`\n;;;     and `memq` themselves: about 300 ns a call, almost none of it spent\n;;;     scanning, because each call and each step of its loop goes through the\n;;;     tier's trampoline. That is 39% of lowering time, and a matter for the\n;;;     code the tier generates for loops, not for this file.\n;;;   - Nothing here calls `apply`, `values`, or anything else that transfers\n;;;     control, because a procedure that does is declined by the compiler\n;;;     tier. Self-hosting means writing in the subset the tier accepts, and\n;;;     this file is the first evidence of what that subset costs to work in.\n;;;\n;;; ## Representation\n;;;\n;;; A core form is a list whose head is a tag (`src/core/scheme/expander.sld`\n;;; lists them); this pass reads\n;;;\n;;;     (lit value) (var name) (if test then else) (seq exprs)\n;;;     (lambda params rest name body ...) (let var init body)\n;;;     (letrec names inits body ...) (set name value) (define name value)\n;;;     (app fn args)\n;;;\n;;; and declines the rest, and `(other description)`, a form the host could\n;;; not give as a core form. An application's span is where it was read\n;;; from, the reader's, kept as its form's `source` (`app-span`); data written\n;;; by hand has none.\n;;;\n;;; An IR node is the same idea, with the fields the JavaScript version stores\n;;; in an object, in the same order:\n;;;\n;;;     (const value tail) (local name tail callable) (global name tail callable)\n;;;     (if test then else tail callable) (seq exprs tail callable)\n;;;     (lambda params rest name body tail callable)\n;;;     (let name init body tail callable)\n;;;     (letrec names inits body tail callable inline)\n;;;     (set name local value tail) (define name value tail)\n;;;     (call fn args tail loop span)\n;;;\n;;; A call's `span` is its application's, which the source map of the code\n;;; generated for it reads (`sourcemap.scm`); the calls this pass synthesizes\n;;; carry none, and may stop before `loop`.\n;;;\n;;; A call's `loop` is `local` or `global` when the call is a tail call to the\n;;; procedure that contains it, which the emitter compiles as a jump back to\n;;; the procedure's top rather than a trip through the trampoline; see\n;;; \"Loops\" below. Otherwise it is `#f`. A `letrec`'s `inline` is `#t` when\n;;; the group is a loop the emitter can place inside the enclosing procedure;\n;;; see `inline-loop?`.\n;;;\n;;; Names are symbols, so membership tests are pointer comparisons. The\n;;; JavaScript version compares strings, which V8 also makes a pointer\n;;; comparison for interned strings, so neither side is favoured.\n;;;\n;;; Lowering failure is `#f`. No IR node is `#f` -- every one is a pair -- so\n;;; the sentinel cannot be confused with a result.\n\n;; /**\n;;  * Globals whose primitives transfer control, or whose semantics involve the\n;;  * continuation. A procedure that references one is left to the interpreter.\n;;  */\n(define control-globals\n  '(call/cc call-with-current-continuation dynamic-wind\n    call-with-values eval\n    with-exception-handler raise raise-continuable guard\n    call-with-escape-continuation exit emergency-exit\n    parameterize))\n\n;; `values` is not here. It builds a multiple-values object and returns it,\n;; which is an ordinary value; it never transfers control. `apply` is not here\n;; either, although it returns a tail call rather than a value: it transfers to\n;; an ordinary procedure with ordinary arguments, and a compiled trampoline can\n;; continue that itself. What used to keep `apply` on the list was the shape of\n;; the tail call it built -- one carrying an expression for the interpreter to\n;; evaluate, which compiled code has no evaluator for. It names the procedure\n;; and the arguments now.\n;;\n;; `call-with-values` stays, because its primitive hands the interpreter an\n;; expression to evaluate. A direct two-argument call to it is rewritten during\n;; lowering into calls the compiler can already make, and that rewrite records\n;; no name, so reaching it by any other route still declines.\n;;\n;; `make-parameter` is not here: it is a procedure of (scheme core)'s that makes\n;; a closure over a cell (parameter.scm), and calling it transfers no control.\n;; What binds a parameter for a dynamic extent, `parameterize`, does, through\n;; `dynamic-wind`.\n\n;; ---------------------------------------------------------------------------\n;; Lexical scope\n;; ---------------------------------------------------------------------------\n;;\n;; A scope is a list of frames, innermost first. A frame is a one-element\n;; vector holding an association list from name to \"is this bound to a lambda\n;; we lowered?\". The vector exists because a frame is extended in place: an\n;; internal `define` adds to the scope it is already being lowered in.\n;;\n;; Holding both facts in one alist entry is what makes shadowing fall out for\n;; free. A name bound plainly in an inner scope hides a callable binding\n;; outside it, because the inner entry is found first.\n\n;; /**\n;;  * Creates a scope nested inside another.\n;;  * @param {list} parent - The enclosing scope, or '() at the outermost level.\n;;  * @returns {list} The new scope.\n;;  */\n(define (make-scope parent)\n  (cons (vector '()) parent))\n\n;; /**\n;;  * Records a name as bound in the innermost frame of a scope.\n;;  * @param {list} scope - The scope to extend.\n;;  * @param {symbol} name - The renamed variable.\n;;  * @param {boolean|list} callable - Whether it is bound to a lambda we\n;;  *   lowered; or, for a name bound to a constant and never assigned, the\n;;  *   constant's IR node, which a reference to the name becomes\n;;  *   (`constant-binding`).\n;;  * @returns {unspecified}\n;;  */\n(define (scope-declare! scope name callable)\n  (let ((frame (car scope)))\n    (vector-set! frame 0 (cons (cons name callable) (vector-ref frame 0)))))\n\n;; /**\n;;  * Finds a name's binding entry, innermost frame first.\n;;  * @param {list} scope - The scope to search.\n;;  * @param {symbol} name - The renamed variable.\n;;  * @returns {pair|boolean} The (name . callable) entry, or #f if unbound.\n;;  */\n(define (scope-lookup scope name)\n  (if (null? scope)\n      #f\n      (let ((hit (assq name (vector-ref (car scope) 0))))\n        (if hit hit (scope-lookup (cdr scope) name)))))\n\n;; /**\n;;  * @param {list} scope - The scope to search.\n;;  * @param {symbol} name - The renamed variable.\n;;  * @returns {boolean} Whether the name is lexically bound.\n;;  */\n(define (scope-has? scope name)\n  (if (scope-lookup scope name) #t #f))\n\n;; /**\n;;  * @param {list} scope - The scope to search.\n;;  * @param {symbol} name - The renamed variable.\n;;  * @returns {boolean} Whether the name is bound to a lambda we lowered.\n;;  */\n(define (scope-callable? scope name)\n  (let ((hit (scope-lookup scope name)))\n    (and hit (eq? (cdr hit) #t))))\n\n;; /**\n;;  * The names a core form assigns anywhere in it, with `set`, added to those\n;;  * found already. A local's name is unique to its binding, so a name found\n;;  * is a binding assigned somewhere.\n;;  *\n;;  * Each form is searched by its shape (src/core/scheme/expander.sld), and\n;;  * only in the parts that are forms. The others are data, whatever they look\n;;  * like: a quoted datum, and the names a lambda or a letrec binds, which it\n;;  * keeps as written beside their renamed forms -- `(lambda (set) set)` has\n;;  * the list `(set)` in it, which is not an assignment. A form the lowering\n;;  * does not lower is not searched, since its procedure is declined.\n;;  * @param {list} form - A core form.\n;;  * @param {list} found - The names found so far.\n;;  * @returns {list}\n;;  */\n(define (assigned-names form found)\n  (case (car form)\n    ((set) (assigned-names (caddr form) (cons (cadr form) found)))\n    ((library-set) (assigned-names (cadddr form) found))\n    ((define) (assigned-names (caddr form) found))\n    ((if) (assigned-names-in (cdr form) found))\n    ((seq) (assigned-names-in (cadr form) found))\n    ((app) (assigned-names-in (caddr form) (assigned-names (cadr form) found)))\n    ((lambda) (assigned-names (list-ref form 4) found))\n    ((letrec) (assigned-names (cadddr form) (assigned-names-in (caddr form) found)))\n    (else found)))\n\n;; /**\n;;  * The names a list of core forms assigns (`assigned-names`).\n;;  * @param {list} forms - The forms.\n;;  * @param {list} found - The names found so far.\n;;  * @returns {list}\n;;  */\n(define (assigned-names-in forms found)\n  (fold assigned-names found forms))\n\n;; /**\n;;  * What a binding's name is declared as: the constant its initializer is, if\n;;  * it is one and the name is never assigned -- so that a reference to the\n;;  * name is the constant, as a literal would be: an inexact integer is then a\n;;  * double in arithmetic rather than a box read from a variable\n;;  * (`fast-operands` in inline.scm) -- or else whether it is a lambda.\n;;  * @param {symbol} name - The renamed variable.\n;;  * @param {list} init - The initializer's IR node.\n;;  * @param {vector} st - The lowering state, which holds the names the\n;;  *   procedure assigns.\n;;  * @returns {boolean|list}\n;;  */\n(define (constant-binding name init st)\n  (cond ((eq? (car init) 'lambda) #t)\n        ((and (eq? (car init) 'const) (not (memq name (vector-ref st 13))))\n         (list 'const (cadr init)))\n        (else #f)))\n\n;; ---------------------------------------------------------------------------\n;; Lowering state\n;; ---------------------------------------------------------------------------\n;;\n;; One mutable record threaded through the whole traversal, as a vector:\n;;\n;;   0  globals           symbols referenced free anywhere in the form\n;;   1  calls-unknown?    whether any call has a callee this pass cannot name\n;;   2  called-locals     locals that were called, having been bound to a lambda\n;;   3  assigned-locals   locals that are the target of a set!\n;;   4  reason            why lowering failed, or #f\n;;   5  synthesized       counter for names this pass invents rather than reads\n;;   6  captures?         whether the form captures a continuation itself\n;;   7  suspends?         whether it has a point it can be suspended at\n;;   8  self              the procedure being lowered, if a call can loop to it\n;;   9  pending-self      the binding the next lambda lowered is bound to\n;;  10  local-loops       calls tagged as local loops, checked once all is seen\n;;  11  defined           names bound by internal definitions, in order\n;;  12  library-globals   each library's binding referred to, as\n;;                        (key name . env): see `library-global-key`\n;;  13  assigned          the names the procedure assigns anywhere, found\n;;                        before it is lowered, so that a binding is known\n;;                        constant where it is declared (`constant-binding`)\n;;  14  receiver          the local holding `this` for the innermost lambda\n;;                        being lowered that reads it, or #f (`receiver-local`)\n\n;; /**\n;;  * Creates an empty lowering state.\n;;  * @returns {vector} The state.\n;;  */\n(define (make-state) (vector '() #f '() '() #f 0 #f #f #f #f '() '() '() '() #f))\n\n(define (state-globals st) (vector-ref st 0))\n(define (state-calls-unknown? st) (vector-ref st 1))\n(define (state-reason st) (vector-ref st 4))\n(define (state-captures? st) (vector-ref st 6))\n\n;; /**\n;;  * Records a free reference to a global, without duplicating it.\n;;  * @param {vector} st - The lowering state.\n;;  * @param {symbol} name - The global's renamed name.\n;;  * @returns {unspecified}\n;;  */\n(define (state-add-global! st name)\n  (if (memq name (vector-ref st 0))\n      #f\n      (vector-set! st 0 (cons name (vector-ref st 0)))))\n\n;; /**\n;;  * The global a library's own binding is known by: a name of its own, the\n;;  * binding's and the library's, `eqv?@scheme.control`, which no other global\n;;  * has, so that everything after this pass treats it as a global of the\n;;  * procedure's; what reads its value, or writes it, finds the library's\n;;  * environment by it (`lowered-library-globals`). A library's macro refers\n;;  * so to the library's binding, where the macro is used outside it\n;;  * (`library-binding-env` in src/core/scheme/expander.scm).\n;;  * @param {vector} st - The lowering state.\n;;  * @param {symbol} name - The binding's name.\n;;  * @param {object} env - The library's environment.\n;;  * @returns {symbol}\n;;  */\n(define (library-global-key st name env)\n  (let ((known (find (lambda (entry) (and (eq? (cadr entry) name) (eq? (cddr entry) env)))\n                     (vector-ref st 12))))\n    (if known\n        (car known)\n        (let ((key (string->symbol\n                    (string-append (symbol->string name) \"@\" (library-key-of env)))))\n          (vector-set! st 12 (cons (cons key (cons name env)) (vector-ref st 12)))\n          key))))\n\n;; /**\n;;  * A library's environment's name, its parts joined with dots, as the\n;;  * library system keys it: `scheme.control`.\n;;  * @param {object} env - The environment.\n;;  * @returns {string}\n;;  */\n(define (library-key-of env)\n  (let ((name (js-ref env \"libraryName\")))\n    (if (and (vector? name) (> (vector-length name) 0))\n        (let join ((parts (cdr (vector->list name))) (key (vector-ref name 0)))\n          (if (null? parts) key (join (cdr parts) (string-append key \".\" (car parts)))))\n        \"library\")))\n\n;; /**\n;;  * Records that some call in this form has a callee the pass cannot name.\n;;  * @param {vector} st - The lowering state.\n;;  * @returns {unspecified}\n;;  */\n(define (state-calls-unknown! st) (vector-set! st 1 #t))\n\n;; /**\n;;  * Records that the form captures a continuation itself.\n;;  * @param {vector} st - The lowering state.\n;;  * @returns {unspecified}\n;;  */\n(define (state-captures! st) (vector-set! st 6 #t))\n\n;; /**\n;;  * Records that the form has a point it can be suspended at -- a non-tail\n;;  * call or a capture. A form with neither is never reified into a frame.\n;;  * @param {vector} st - The lowering state.\n;;  * @returns {unspecified}\n;;  */\n(define (state-suspends! st) (vector-set! st 7 #t))\n\n;; /**\n;;  * Records that a local bound to a lambda was called.\n;;  * @param {vector} st - The lowering state.\n;;  * @param {symbol} name - The local's name.\n;;  * @returns {unspecified}\n;;  */\n(define (state-called-local! st name)\n  (if (memq name (vector-ref st 2))\n      #f\n      (vector-set! st 2 (cons name (vector-ref st 2)))))\n\n;; /**\n;;  * Records that a local is assigned by set!.\n;;  * @param {vector} st - The lowering state.\n;;  * @param {symbol} name - The local's name.\n;;  * @returns {unspecified}\n;;  */\n(define (state-assigned-local! st name)\n  (if (memq name (vector-ref st 3))\n      #f\n      (vector-set! st 3 (cons name (vector-ref st 3)))))\n\n;; /**\n;;  * Records why lowering failed and yields the failure sentinel. The first\n;;  * reason is kept, since it is the innermost and most specific one.\n;;  * @param {vector} st - The lowering state.\n;;  * @param {string} reason - Human-readable cause.\n;;  * @returns {boolean} #f, the failure sentinel.\n;;  */\n(define (fail! st reason)\n  (if (vector-ref st 4) #f (vector-set! st 4 reason))\n  #f)\n\n;; ---------------------------------------------------------------------------\n;; Loops\n;; ---------------------------------------------------------------------------\n;;\n;; A tail call returns a pending call to the trampoline, which allocates and\n;; round-trips on every iteration: measured, about 95 ns an iteration of an\n;; empty compiled loop, and most of what a compiled `assq` costs on a\n;; two-entry list. When the callee is certainly the procedure making the call,\n;; the emitter can instead reassign the parameters and jump back to the top.\n;; This pass decides when that is, because it is the one that knows which\n;; lambda each name is bound to.\n;;\n;; Two bindings qualify. A procedure bound by `letrec` -- a named `let`, a\n;; `do` -- or by an internal definition is certainly itself when its body\n;; calls that name, provided the name is never assigned and defined only once;\n;; both are known only at the end, so such calls are tagged as they are seen\n;; and untagged afterwards if either fails. A top-level procedure calling its\n;; own global name is itself only while the global is not redefined, which can\n;; happen after this code was compiled, so that call is tagged `global` and the\n;; emitter guards it on the binding.\n;;\n;; \"The procedure making the call\" is the innermost lambda. A lambda nested\n;; inside a loop is a different procedure, and a call from it to the loop's\n;; name is an ordinary call; `self` is reset on entering every lambda for that\n;; reason. The argument count must match and there must be no rest parameter,\n;; so that reassigning the parameters is the whole of the call.\n\n;; /**\n;;  * Names the binding the next lambda lowered is bound to.\n;;  * @param {vector} st - The lowering state.\n;;  * @param {symbol} kind - 'local or 'global.\n;;  * @param {symbol} name - The binding's name.\n;;  * @returns {unspecified}\n;;  */\n(define (state-pending-self! st kind name)\n  (vector-set! st 9 (cons kind name)))\n\n;; /**\n;;  * The binding a lambda about to be lowered is bound to, as a `self` record,\n;;  * consuming it so that no lambda nested inside can claim it.\n;;  * @param {vector} st - The lowering state.\n;;  * @param {list} node - The lambda's AST node.\n;;  * @returns {list|boolean} (kind name arity), or #f if calls cannot loop.\n;;  */\n(define (take-self! st node)\n  (let ((pending (vector-ref st 9)))\n    (vector-set! st 9 #f)\n    (if (and pending (not (ast-2 node)))\n        (list (car pending) (cdr pending) (length (ast-1 node)))\n        #f)))\n\n;; /**\n;;  * The loop tag for a call, and a note of it if it has to be checked later.\n;;  * @param {list} fn - The lowered callee.\n;;  * @param {list} args - The lowered arguments.\n;;  * @param {boolean} tail - Whether the call is in tail position.\n;;  * @param {vector} st - The lowering state.\n;;  * @returns {symbol|boolean} 'local, 'global or #f.\n;;  */\n(define (loop-kind fn args tail st)\n  (let ((self (vector-ref st 8)))\n    (if (and tail\n             self\n             (eq? (car fn) (car self))\n             (eq? (ast-1 fn) (cadr self))\n             (= (length args) (caddr self)))\n        (car self)\n        #f)))\n\n;; /**\n;;  * Whether a `letrec` group can be emitted as a loop in the procedure that\n;;  * enters it, rather than as a procedure of its own.\n;;  *\n;;  * Iterating already jumps; entering still makes a closure and returns a\n;;  * pending call, once per call of the enclosing procedure -- for `assq` on a\n;;  * two-entry list, nearly the whole cost. A group qualifies when it is one\n;;  * lambda without a rest parameter; its body is a single tail call to that\n;;  * name with the right number of arguments; and every other mention of the\n;;  * name is one of the lambda's own looping calls. Then the name is never\n;;  * needed as a value, and the lambda is only ever running as a loop entered\n;;  * from here. It can be decided now rather than at the end, because every\n;;  * mention of the name lies inside the group, which is fully lowered.\n;;  *\n;;  * @param {list} names - The group's names.\n;;  * @param {list} inits - Their lowered initializers.\n;;  * @param {list} body - The lowered body.\n;;  * @param {boolean} tail - Whether the group is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {boolean}\n;;  */\n(define (inline-loop? names inits body tail st)\n  (and tail\n       (null? (cdr names))\n       (let ((name (car names))\n             (lam (car inits)))\n         (and (not (caddr lam))\n              (eq? (car body) 'call)\n              (eq? (car (cadr body)) 'local)\n              (eq? (cadr (cadr body)) name)\n              (= (length (caddr body)) (length (cadr lam)))\n              (not (memq name (vector-ref st 3)))\n              (equal? (mentions-all name (caddr body) (cons 0 0)) (cons 0 0))\n              (let ((uses (mentions name lam (cons 0 0))))\n                ;; No mention except as a callee, and every call a looping one.\n                (and (= (car uses) 0)\n                     (= (cdr uses) (looping-calls name lam))))))))\n\n;; /**\n;;  * Counts a name's mentions in an IR subtree: as the callee of a call, and\n;;  * anywhere else. Nested lambdas are searched too, since a mention there is\n;;  * still a mention.\n;;  * @param {symbol} name - The name.\n;;  * @param {list} node - An IR node.\n;;  * @param {pair} counts - (other . calls) so far.\n;;  * @returns {pair} (other . calls).\n;;  */\n(define (mentions name node counts)\n  (let ((tag (car node)))\n    (cond ((eq? tag 'const) counts)\n          ((eq? tag 'global) counts)\n          ((eq? tag 'local)\n           (if (eq? (cadr node) name) (cons (+ (car counts) 1) (cdr counts)) counts))\n          ((eq? tag 'call)\n           (let ((fn (cadr node)))\n             (mentions-all name (caddr node)\n                           (if (and (eq? (car fn) 'local) (eq? (cadr fn) name))\n                               (cons (car counts) (+ (cdr counts) 1))\n                               (mentions name fn counts)))))\n          ((eq? tag 'if)\n           (mentions name (cadddr node)\n                     (mentions name (caddr node) (mentions name (cadr node) counts))))\n          ((eq? tag 'seq) (mentions-all name (cadr node) counts))\n          ((eq? tag 'lambda) (mentions name (car (cddddr node)) counts))\n          ((eq? tag 'let) (mentions name (cadddr node) (mentions name (caddr node) counts)))\n          ((eq? tag 'letrec)\n           (mentions name (cadddr node) (mentions-all name (caddr node) counts)))\n          ((eq? tag 'set)\n           (mentions name (cadddr node)\n                     (if (eq? (cadr node) name) (cons (+ (car counts) 1) (cdr counts)) counts)))\n          ((eq? tag 'define) (mentions name (caddr node) counts))\n          ((eq? tag 'capture) (mentions name (cadr node) counts))\n          (else (cons (+ (car counts) 1) (cdr counts))))))\n\n;; /**\n;;  * `mentions` over a list of IR nodes.\n;;  * @param {symbol} name - The name.\n;;  * @param {list} nodes - IR nodes.\n;;  * @param {pair} counts - (other . calls) so far.\n;;  * @returns {pair} (other . calls).\n;;  */\n(define (mentions-all name nodes counts)\n  (if (null? nodes)\n      counts\n      (mentions-all name (cdr nodes) (mentions name (car nodes) counts))))\n\n;; /**\n;;  * How many calls to a name inside a lambda are tagged as that lambda's own\n;;  * looping calls. Those are only ever in the lambda's own body, since a\n;;  * nested lambda is a different procedure, so only that body is searched.\n;;  * @param {symbol} name - The lambda's name.\n;;  * @param {list} lam - The lambda's IR node.\n;;  * @returns {integer}\n;;  */\n(define (looping-calls name lam)\n  (let count ((node (car (cddddr lam))))\n    (let ((tag (car node)))\n      (cond ((eq? tag 'call)\n             (let ((fn (cadr node)))\n               (if (and (eq? (car fn) 'local) (eq? (cadr fn) name)\n                        (car (cddddr node)))\n                   1\n                   0)))\n            ((eq? tag 'if) (+ (count (caddr node)) (count (cadddr node))))\n            ((eq? tag 'seq) (if (null? (cadr node)) 0 (count (last-of (cadr node)))))\n            ((eq? tag 'let) (count (cadddr node)))\n            ((eq? tag 'letrec) (count (cadddr node)))\n            (else 0)))))\n\n;; /**\n;;  * Records an internal definition's name, so that one defined twice is\n;;  * known not to be a single binding.\n;;  * @param {vector} st - The lowering state.\n;;  * @param {symbol} name - The defined name.\n;;  * @returns {unspecified}\n;;  */\n(define (state-defined! st name)\n  (vector-set! st 11 (cons name (vector-ref st 11))))\n\n;; /**\n;;  * Untags every local loop whose name turned out to be assigned or defined\n;;  * more than once, now that the whole procedure has been seen.\n;;  * @param {vector} st - The lowering state.\n;;  * @returns {unspecified}\n;;  */\n(define (confirm-local-loops! st)\n  (let ((assigned (vector-ref st 3))\n        (defined (vector-ref st 11)))\n    (for-each\n      (lambda (call)\n        (let ((name (ast-1 (cadr call))))\n          (if (or (memq name assigned)\n                  (let ((first (memq name defined)))\n                    (and first (memq name (cdr first)))))\n              (set-car! (cddddr call) #f)\n              #f)))\n      (vector-ref st 10))))\n\n;; ---------------------------------------------------------------------------\n;; Reading the analyzed AST\n;; ---------------------------------------------------------------------------\n\n(define (ast-tag node) (car node))\n(define (ast-1 node) (cadr node))\n(define (ast-2 node) (caddr node))\n(define (ast-3 node) (cadddr node))\n(define (ast-4 node) (car (cddddr node)))\n\n;; /**\n;;  * An application's source span, or #f: its form's `source`, where the\n;;  * expander keeps the span of the text it was made from.\n;;  * @param {list} node - An `app` core form.\n;;  * @returns {object|boolean}\n;;  */\n(define (app-span node)\n  (let ((span (js-ref node \"source\")))\n    (if (or (js-undefined? span) (js-null? span)) #f span)))\n\n;; /**\n;;  * Whether an IR node denotes something this pass can name as a callee.\n;;  *\n;;  * A global can be looked up and followed; a lambda, and a local bound to\n;;  * one, were lowered here so their references are already recorded. Anything\n;;  * else -- a bare parameter, most often -- is whatever the caller handed\n;;  * over, and may capture a continuation without this procedure's text saying\n;;  * so.\n;;  *\n;;  * @param {list} node - An IR node.\n;;  * @returns {boolean} Whether the callee is nameable.\n;;  */\n(define (ir-callable? node)\n  (let ((tag (car node)))\n    (cond ((eq? tag 'local) (ast-3 node))\n          ((eq? tag 'global) (ast-3 node))\n          ((eq? tag 'lambda) (car (cdr (cddddr (cdr node)))))\n          ((eq? tag 'if) (car (cddddr (cdr node))))\n          ((eq? tag 'seq) (ast-3 node))\n          ((eq? tag 'let) (car (cddddr (cdr node))))\n          ((eq? tag 'letrec) (car (cddddr (cdr node))))\n          (else #f))))\n\n;; ---------------------------------------------------------------------------\n;; Lowering\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Lowers an analyzed AST node to IR.\n;;  * @param {list} node - An analyzed AST node.\n;;  * @param {list} scope - The enclosing lexical scope.\n;;  * @param {boolean} tail - Whether the node is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean} An IR node, or #f if the form is unsupported.\n;;  */\n(define (lower-node node scope tail st)\n  (let ((tag (ast-tag node)))\n    (cond\n      ((eq? tag 'lit)\n       (list 'const (ast-1 node) tail))\n\n      ((eq? tag 'var)\n       (let ((name (ast-1 node)))\n         ;; One lookup decides all three: a local bound to a constant, a\n         ;; local, or a global.\n         (let ((hit (scope-lookup scope name)))\n           (cond\n             ;; `this` is no global: it is a method's receiver, which the\n             ;; innermost lambda reading it took as it was entered\n             ;; (`receiver-local`).\n             ((and (not hit) (eq? name 'this) (vector-ref st 14))\n              (receiver-read (vector-ref st 14) tail st))\n             ((not hit)\n              (state-add-global! st name)\n              ;; A global callee is nameable in the sense this flag means: the\n              ;; safety analysis can look it up and follow it. Not that it is\n              ;; safe.\n              (list 'global name tail #t))\n             ((pair? (cdr hit)) (list 'const (cadr (cdr hit)) tail))\n             (else (list 'local name tail (eq? (cdr hit) #t)))))))\n\n      ((eq? tag 'if)\n       (let ((test (lower-node (ast-1 node) scope #f st)))\n         (if (not test)\n             #f\n             (let ((then (lower-node (ast-2 node) scope tail st)))\n               (if (not then)\n                   #f\n                   (let ((other (lower-node (ast-3 node) scope tail st)))\n                     (if (not other)\n                         #f\n                         (list 'if test then other tail\n                               (if (ir-callable? then) (if (ir-callable? other) #t #f) #f)))))))))\n\n      ((eq? tag 'seq)\n       (let ((body (lower-sequence (ast-1 node) scope tail st)))\n         (if (not body)\n             #f\n             (list 'seq body tail\n                   (if (null? body) #f (if (ir-callable? (last-of body)) #t #f))))))\n\n      ((eq? tag 'lambda)\n       (let ((inner (make-scope scope))\n             (outer-self (vector-ref st 8))\n             (outer-receiver (vector-ref st 14))\n             (receiver (and (mentions-this? (ast-4 node)) (receiver-name! st))))\n         (declare-all! inner (ast-1 node))\n         (if (ast-2 node) (scope-declare! inner (ast-2 node) #f) #f)\n         (if receiver (scope-declare! inner receiver #f) #f)\n         ;; This lambda is now the procedure a tail call could loop to, and\n         ;; stops being it once its body is lowered; and, if it reads `this`,\n         ;; the one whose receiver the reads find.\n         (vector-set! st 8 (take-self! st node))\n         (if receiver (vector-set! st 14 receiver) #f)\n         (let ((body (lower-body (ast-4 node) inner st)))\n           (vector-set! st 8 outer-self)\n           (vector-set! st 14 outer-receiver)\n           (if (not body)\n               #f\n               (list 'lambda (ast-1 node) (ast-2 node) (ast-3 node)\n                     (if receiver (receiver-binding receiver outer-receiver body) body)\n                     tail #t)))))\n\n      ((eq? tag 'let)\n       (let ((init (lower-node (ast-2 node) scope #f st)))\n         (if (not init)\n             #f\n             (let ((inner (make-scope scope)))\n               (scope-declare! inner (ast-1 node) (constant-binding (ast-1 node) init st))\n               (let ((body (lower-node (ast-3 node) inner tail st)))\n                 (if (not body)\n                     #f\n                     (list 'let (ast-1 node) init body tail\n                           (if (ir-callable? body) #t #f))))))))\n\n      ((eq? tag 'letrec)\n       ;; Every name is in scope in every initializer, which is what makes the\n       ;; group mutually recursive, and every initializer is a lambda -- the\n       ;; expander only builds this shape. Declaring them all callable before\n       ;; lowering any of them is what lets a recursive or mutually recursive\n       ;; call be recognised as a callee this pass can name.\n       (let ((inner (make-scope scope)))\n         (declare-all-callable! inner (ast-1 node))\n         (let ((inits (lower-letrec-inits (ast-1 node) (ast-2 node) inner st)))\n           (if (not inits)\n               #f\n               (let ((body (lower-node (ast-3 node) inner tail st)))\n                 (if (not body)\n                     #f\n                     (list 'letrec (ast-1 node) inits body tail\n                           (if (ir-callable? body) #t #f)\n                           (inline-loop? (ast-1 node) inits body tail st))))))))\n\n      ((eq? tag 'library-var)\n       (let ((key (library-global-key st (ast-1 node) (ast-2 node))))\n         (state-add-global! st key)\n         (list 'global key tail #t)))\n\n      ((eq? tag 'library-set)\n       (let ((value (lower-node (ast-3 node) scope #f st)))\n         (if (not value)\n             #f\n             (let ((key (library-global-key st (ast-1 node) (ast-2 node))))\n               (state-add-global! st key)\n               (list 'set key #f value tail)))))\n\n      ((eq? tag 'set)\n       (let ((value (lower-node (ast-2 node) scope #f st)))\n         (if (not value)\n             #f\n             (let* ((name (ast-1 node))\n                    (local (scope-has? scope name)))\n               (if local\n                   (state-assigned-local! st name)\n                   (state-add-global! st name))\n               (list 'set name local value tail)))))\n\n      ((eq? tag 'define)\n       ;; Only reachable for an internal definition; the top-level case is\n       ;; handled by the caller. The expander has already hoisted the name.\n       (begin\n         (state-defined! st (ast-1 node))\n         (if (eq? (ast-tag (ast-2 node)) 'lambda)\n             (state-pending-self! st 'local (ast-1 node))\n             #f)\n         (let ((value (lower-node (ast-2 node) scope #f st)))\n           (if (not value)\n               #f\n               (begin\n                 (scope-declare! scope (ast-1 node) (eq? (car value) 'lambda))\n                 (list 'define (ast-1 node) value tail))))))\n\n      ((eq? tag 'app)\n       (let ((direct (lower-direct-application node scope tail st)))\n         (if (not (eq? direct 'not-this-shape))\n             direct\n             (let ((values-call (lower-call-with-values node scope tail st)))\n               (if (not (eq? values-call 'not-this-shape))\n                   values-call\n                   (let ((captured (lower-call-cc node scope tail st)))\n                     (if (not (eq? captured 'not-this-shape))\n                         captured\n                         (lower-ordinary-application node scope tail st))))))))\n\n      (else (fail! st (unsupported-form-reason node))))))\n\n;; /**\n;;  * Why a core form this pass does not lower is declined.\n;;  * @param {list} node - The form.\n;;  * @returns {string}\n;;  */\n(define (unsupported-form-reason node)\n  (case (ast-tag node)\n    ((other) (ast-1 node))\n    ((scoped-var) \"refers to a binding found by scopes as it runs\")\n    (else (string-append \"unsupported form: \" (symbol->string (ast-tag node))))))\n\n;; /**\n;;  * Lowers `(call/cc receiver)` as a capture made by compiled code.\n;;  *\n;;  * A continuation is the interpreter's frame stack, which the compiled frames\n;;  * between the call and the interpreter do not appear in, so the primitive\n;;  * cannot be called. The capture is emitted as a call site that suspends\n;;  * instead: the procedure records what the capture needs, spills its locals\n;;  * and reports the unwind outward, and the captured value arrives at the\n;;  * resume point rather than from the call.\n;;  *\n;;  * @param {list} node - An `app` AST node.\n;;  * @param {list} scope - The enclosing lexical scope.\n;;  * @param {boolean} tail - Whether the application is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean|symbol} IR, #f if unsupported, or 'not-this-shape.\n;;  */\n(define (lower-call-cc node scope tail st)\n  (let ((fn (ast-1 node)))\n    (if (not (memq (ast-tag fn) '(var library-var)))\n        'not-this-shape\n        (if (not (if (eq? (ast-1 fn) 'call/cc)\n                     #t\n                     (eq? (ast-1 fn) 'call-with-current-continuation)))\n            'not-this-shape\n            ;; A local of the same name is not the primitive at all. A\n            ;; library's binding, which a library's macro refers to -- `guard`\n            ;; in (scheme control) -- is never a local.\n            (if (and (eq? (ast-tag fn) 'var) (scope-has? scope (ast-1 fn)))\n                'not-this-shape\n                (if (not (= (length (ast-2 node)) 1))\n                    'not-this-shape\n                    (let ((receiver (lower-node (car (ast-2 node)) scope #f st)))\n                      (if (not receiver)\n                          #f\n                          (begin\n                            ;; The receiver is handed the continuation and\n                            ;; called, so it is a callee this pass cannot name.\n                            (state-calls-unknown! st)\n                            (state-captures! st)\n                            (state-suspends! st)\n                            (list 'capture receiver tail))))))))))\n\n;; /**\n;;  * Lowers `(call-with-values producer consumer)` without the primitive.\n;;  *\n;;  * The primitive returns something only the interpreter can continue, and it\n;;  * cannot be a plain procedure either, because the pending consumer\n;;  * application would then sit in a frame a captured continuation could not\n;;  * restore. Rewriting it as `(apply consumer (%values->list (producer)))`\n;;  * avoids both: every part is something the compiler already emits, and the\n;;  * producer call becomes an ordinary call site, which is what gives a capture\n;;  * inside it somewhere to resume.\n;;  *\n;;  * The producer expression is bound first so the operands are still evaluated\n;;  * left to right, matching the interpreter.\n;;  *\n;;  * `%apply` and `%values->list` are the primitives, read from the runtime\n;;  * rather than the environment (`runtime-globals` in emit.scm): a library sees\n;;  * only what it imports, and need not import `apply` to call\n;;  * `call-with-values`, nor be stopped by defining an `apply` of its own.\n;;  *\n;;  * @param {list} node - An `app` AST node.\n;;  * @param {list} scope - The enclosing lexical scope.\n;;  * @param {boolean} tail - Whether the application is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean|symbol} IR, #f if unsupported, or 'not-this-shape.\n;;  */\n(define (lower-call-with-values node scope tail st)\n  (let ((fn (ast-1 node)))\n    (if (not (and (memq (ast-tag fn) '(var library-var))\n                  (eq? (ast-1 fn) 'call-with-values)\n                  ;; A local of the same name is not the primitive at all. A\n                  ;; library's binding, which a library's macro refers to --\n                  ;; `define-values` in (scheme control) -- is never a local.\n                  (not (and (eq? (ast-tag fn) 'var) (scope-has? scope (ast-1 fn))))\n                  (= (length (ast-2 node)) 2)))\n        'not-this-shape\n        (let ((producer (lower-node (car (ast-2 node)) scope #f st)))\n          (if (not producer)\n              #f\n              (let ((consumer (lower-node (cadr (ast-2 node)) scope #f st)))\n                (if (not consumer)\n                    #f\n                    (begin\n                      ;; Neither `call-with-values`, which would decline the\n                      ;; procedure for mentioning what it no longer mentions,\n                      ;; nor the two primitives is recorded as a global: the\n                      ;; primitives are read from the runtime. The producer is\n                      ;; whatever the caller was handed, so calling it is\n                      ;; calling something this pass cannot name.\n                      (state-calls-unknown! st)\n                      (let ((nm (synthesized-name! st)))\n                        (list 'let nm producer\n                              (list 'call (list 'global '%apply #f #t)\n                                    (list consumer\n                                          (list 'call\n                                                (list 'global '%values->list #f #t)\n                                                (list (list 'call (list 'local nm #f #f) '() #f))\n                                                #f))\n                                    tail)\n                              tail #f))))))))))\n\n;; /**\n;;  * A name this pass invents, distinct from anything the expander produces.\n;;  * @param {vector} st - The lowering state.\n;;  * @returns {symbol} A fresh name.\n;;  */\n(define (synthesized-name! st)\n  (let ((n (vector-ref st 5)))\n    (vector-set! st 5 (+ n 1))\n    (string->symbol (string-append \"%cwv\" (number->string n)))))\n\n;; ---------------------------------------------------------------------------\n;; `this`\n;; ---------------------------------------------------------------------------\n;;\n;; `this` is the receiver JavaScript calls a procedure as a method of. The\n;; interpreter binds it at each application while a method's call runs, and a\n;; procedure made then sees, called after, the receiver it was made under\n;; (frames.js). The runtime keeps the receiver of the call running (`thisAt`\n;; in src/compiler/runtime.js), so compiled code does the same: a lambda that\n;; reads `this`, itself or in a lambda inside it, takes the receiver as it is\n;; entered into a local, or, where there is none, the one the lambda around it\n;; took; a read of `this` is of that local, and of no receiver at all an\n;; unbound variable, as in the interpreter.\n\n;; /**\n;;  * Whether a core form reads `this` free anywhere inside it, a lambda inside\n;;  * it included, followed by its shape (`subforms` in `driver.scm`), never into\n;;  * a lambda's parameters as written. A local is never `this`, which the\n;;  * expander renames, so a variable of that name is the receiver.\n;;  * @param {list} form - The core form.\n;;  * @returns {boolean}\n;;  */\n(define (mentions-this? form)\n  (case (ast-tag form)\n    ((var) (eq? (ast-1 form) 'this))\n    ((library-set) (mentions-this? (ast-3 form)))\n    (else (any mentions-this? (subforms form)))))\n\n;; /**\n;;  * A name for the local a lambda holds its receiver in.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {symbol}\n;;  */\n(define (receiver-name! st)\n  (let ((n (vector-ref st 5)))\n    (vector-set! st 5 (+ n 1))\n    (string->symbol (string-append \"%this\" (number->string n)))))\n\n;; /**\n;;  * A lambda's body, with its receiver bound first: the receiver of the\n;;  * method call running as it is entered, or else the one the lambda around\n;;  * it took (`%this-at`, `R.thisAt`).\n;;  * @param {symbol} receiver - The local.\n;;  * @param {symbol|boolean} outer - The local of the lambda around it that\n;;  *   reads `this`, or #f.\n;;  * @param {list} body - The lowered body.\n;;  * @returns {list}\n;;  */\n(define (receiver-binding receiver outer body)\n  (list 'let receiver\n        (list 'call (list 'global '%this-at #f #t) (if outer (list (list 'local outer #f #f)) '()) #f)\n        body #t (if (ir-callable? body) #t #f)))\n\n;; /**\n;;  * A read of `this`: the receiver the local holds, or, where there was none,\n;;  * an unbound variable's error (`%this-of`, `R.thisOf`).\n;;  * @param {symbol} receiver - The local.\n;;  * @param {boolean} tail - Whether the read is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list}\n;;  */\n(define (receiver-read receiver tail st)\n  (let ((nm (synthesized-name! st)))\n    (list 'let nm (list 'call (list 'global '%this-of #f #t) (list (list 'local receiver #f #f)) #f)\n          (list 'local nm tail #f) tail #f)))\n\n;; /**\n;;  * Lowers `((lambda (a b) body) x y)` as bindings rather than as a call.\n;;  *\n;;  * Every `let` reaches the compiler in this shape, because that is what the\n;;  * expander expands it to, so a chain of bindings would otherwise be a chain\n;;  * of nested procedures -- one per clause of a `let*`. Reducing it is sound\n;;  * because the operator is a literal lambda applied exactly here: nothing\n;;  * else can call it and nothing can capture it.\n;;  *\n;;  * The body takes on the *call's* tail position rather than being a procedure\n;;  * body of its own, which is the part that has to be right: inlined into a\n;;  * caller that wants a value, a call in the body must produce one.\n;;  *\n;;  * @param {list} node - An `app` AST node.\n;;  * @param {list} scope - The enclosing lexical scope.\n;;  * @param {boolean} tail - Whether the application is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean|symbol} IR, #f if unsupported, or the symbol\n;;  *   'not-this-shape if the caller should emit an ordinary call.\n;;  */\n(define (lower-direct-application node scope tail st)\n  (let ((fn (ast-1 node)))\n    (if (not (eq? (ast-tag fn) 'lambda))\n        'not-this-shape\n        ;; A rest parameter would have to be built from the arguments, and a\n        ;; mismatched count is an arity error the ordinary path reports.\n        (if (ast-2 fn)\n            'not-this-shape\n            (let ((params (ast-1 fn))\n                  (args (ast-2 node)))\n              (if (not (= (length params) (length args)))\n                  'not-this-shape\n                  (let ((inits (lower-each args scope st)))\n                    (if (not inits)\n                        #f\n                        (let ((inner (make-scope scope)))\n                          (declare-bindings! inner params inits st)\n                          (let ((body (lower-body-in (ast-4 fn) inner st tail)))\n                            (if (not body)\n                                #f\n                                (wrap-bindings params inits body tail))))))))))))\n\n;; /**\n;;  * Declares each parameter, noting the ones bound to a lambda, and those\n;;  * bound to a constant the body never assigns (`constant-binding`).\n;;  * @param {list} scope - The scope to extend.\n;;  * @param {list} params - Renamed parameter names.\n;;  * @param {list} inits - Their lowered initializers, in the same order.\n;;  * @param {vector} st - The lowering state.\n;;  * @returns {unspecified}\n;;  */\n(define (declare-bindings! scope params inits st)\n  (if (null? params)\n      #f\n      (begin\n        (scope-declare! scope (car params) (constant-binding (car params) (car inits) st))\n        (declare-bindings! scope (cdr params) (cdr inits) st))))\n\n;; /**\n;;  * Wraps a body in one binding per parameter, the first outermost.\n;;  * @param {list} params - Renamed parameter names.\n;;  * @param {list} inits - Their lowered initializers.\n;;  * @param {list} body - The lowered body.\n;;  * @param {boolean} tail - Whether the whole form is in tail position.\n;;  * @returns {list} An IR node.\n;;  */\n(define (wrap-bindings params inits body tail)\n  (if (null? params)\n      body\n      (let ((inner (wrap-bindings (cdr params) (cdr inits) body tail)))\n        (list 'let (car params) (car inits) inner tail\n              (if (ir-callable? inner) #t #f)))))\n\n;; /**\n;;  * Lowers an ordinary application, whose callee is evaluated like any other\n;;  * expression.\n;;  * @param {list} node - An `app` AST node.\n;;  * @param {list} scope - The enclosing lexical scope.\n;;  * @param {boolean} tail - Whether the application is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean} An IR node, or #f if unsupported.\n;;  */\n(define (lower-ordinary-application node scope tail st)\n  (let ((fn (lower-node (ast-1 node) scope #f st)))\n    (if (not fn)\n        #f\n        (let ((args (lower-each (ast-2 node) scope st)))\n          (cond\n            ((not args) #f)\n            ((named-let-operator? fn) (lower-named-let-call fn args tail (app-span node) st))\n            (else\n                (if (ir-callable? fn)\n                    (if (eq? (car fn) 'local) (state-called-local! st (ast-1 fn)) #f)\n                    (state-calls-unknown! st))\n                (if tail #f (state-suspends! st))\n                (let* ((loop (loop-kind fn args tail st))\n                       (call (list 'call fn args tail loop (app-span node))))\n                  (if (eq? loop 'local)\n                      (vector-set! st 10 (cons call (vector-ref st 10)))\n                      #f)\n                  call)))))))\n\n;; /**\n;;  * Whether a lowered callee is a named `let`'s operator: a one-lambda\n;;  * `letrec` whose body is just its own name.\n;;  * @param {list} fn - A lowered callee.\n;;  * @returns {boolean}\n;;  */\n(define (named-let-operator? fn)\n  (and (eq? (car fn) 'letrec)\n       (null? (cdr (cadr fn)))\n       (eq? (car (cadddr fn)) 'local)\n       (eq? (cadr (cadddr fn)) (car (cadr fn)))))\n\n;; /**\n;;  * Lowers a named `let`'s application with the call moved inside the group:\n;;  * `((letrec ((loop L)) loop) a b)` becomes `(letrec ((loop L)) (loop a b))`.\n;;  *\n;;  * The expander expands a named `let` to the first shape, where the call is\n;;  * outside the group and the group can only be a procedure. In the second the\n;;  * group's body is the call that enters the loop, which is the shape\n;;  * `inline-loop?` recognises. The two mean the same thing: the arguments were\n;;  * lowered outside the group and renaming keeps its name out of them, and the\n;;  * closure is still made before they are evaluated.\n;;  *\n;;  * @param {list} fn - The lowered `letrec` operator.\n;;  * @param {list} args - The lowered arguments.\n;;  * @param {boolean} tail - Whether the application is in tail position.\n;;  * @param {object|boolean} span - The application's source span, or #f.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list} A `letrec` IR node.\n;;  */\n(define (lower-named-let-call fn args tail span st)\n  (let* ((names (cadr fn))\n         (inits (caddr fn))\n         (call (list 'call (cadddr fn) args tail #f span)))\n    (state-called-local! st (car names))\n    (if tail #f (state-suspends! st))\n    (list 'letrec names inits call tail #f\n          (inline-loop? names inits call tail st))))\n\n;; /**\n;;  * Declares each of a lambda's parameters as a plain binding.\n;;  * @param {list} scope - The scope to extend.\n;;  * @param {list} names - Renamed parameter names.\n;;  * @returns {unspecified}\n;;  */\n(define (declare-all! scope names)\n  (if (null? names)\n      #f\n      (begin (scope-declare! scope (car names) #f)\n             (declare-all! scope (cdr names)))))\n\n;; /**\n;;  * Declares each name as bound to a lambda this pass lowered.\n;;  * @param {list} scope - The scope to extend.\n;;  * @param {list} names - Renamed names.\n;;  * @returns {unspecified}\n;;  */\n(define (declare-all-callable! scope names)\n  (if (null? names)\n      #f\n      (begin (scope-declare! scope (car names) #t)\n             (declare-all-callable! scope (cdr names)))))\n\n;; /**\n;;  * @param {list} lst - A non-empty list.\n;;  * @returns {*} Its last element.\n;;  */\n(define (last-of lst)\n  (if (null? (cdr lst)) (car lst) (last-of (cdr lst))))\n\n;; /**\n;;  * Lowers every node in a list, none of them in tail position.\n;;  * @param {list} nodes - Analyzed nodes.\n;;  * @param {list} scope - Enclosing scope.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean} IR nodes, or #f if any was unsupported.\n;;  */\n(define (lower-each nodes scope st)\n  (if (null? nodes)\n      '()\n      (let ((head (lower-node (car nodes) scope #f st)))\n        (if (not head)\n            #f\n            (let ((rest (lower-each (cdr nodes) scope st)))\n              (if (not rest) #f (cons head rest)))))))\n\n;; /**\n;;  * Lowers a `letrec` group's initializers, each knowing the name it is bound\n;;  * to so that a tail call to that name inside it can loop.\n;;  * @param {list} names - The group's names.\n;;  * @param {list} inits - Their initializers, all lambdas.\n;;  * @param {list} scope - The group's scope.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean} IR nodes, or #f if any was unsupported.\n;;  */\n(define (lower-letrec-inits names inits scope st)\n  (if (null? inits)\n      '()\n      (begin\n        (state-pending-self! st 'local (car names))\n        (let ((head (lower-node (car inits) scope #f st)))\n          (if (not head)\n              #f\n              (let ((rest (lower-letrec-inits (cdr names) (cdr inits) scope st)))\n                (if (not rest) #f (cons head rest))))))))\n\n;; /**\n;;  * Lowers a sequence, marking only its last expression as tail.\n;;  * @param {list} nodes - Analyzed nodes.\n;;  * @param {list} scope - Enclosing scope.\n;;  * @param {boolean} tail - Whether the sequence is in tail position.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean} IR nodes, or #f if any was unsupported.\n;;  */\n(define (lower-sequence nodes scope tail st)\n  (if (null? nodes)\n      '()\n      (let* ((last? (null? (cdr nodes)))\n             (head (lower-node (car nodes) scope (if last? tail #f) st)))\n        (if (not head)\n            #f\n            (let ((rest (lower-sequence (cdr nodes) scope tail st)))\n              (if (not rest) #f (cons head rest)))))))\n\n;; /**\n;;  * Lowers a procedure body, which is in tail position by definition.\n;;  *\n;;  * Internal definitions are declared before the body is lowered, or a forward\n;;  * reference between two internal procedures would be mistaken for a global.\n;;  * One naming a procedure is a callee this pass can name, so calling it is not\n;;  * calling an unknown.\n;;  *\n;;  * @param {list} node - The body node.\n;;  * @param {list} scope - The procedure's scope.\n;;  * @param {vector} st - Lowering state.\n;;  * @returns {list|boolean} An IR node, or #f if the body is unsupported.\n;;  */\n(define (lower-body node scope st)\n  (lower-body-in node scope st #t))\n\n;; /**\n;;  * Lowers a body in a caller-supplied tail position.\n;;  *\n;;  * A real procedure body is in tail position by definition; a body being\n;;  * inlined into its caller is in whatever position the caller was.\n;;  *\n;;  * @param {list} node - The body node.\n;;  * @param {list} scope - The scope to lower in.\n;;  * @param {vector} st - Lowering state.\n;;  * @param {boolean} tail - Whether the body is in tail position.\n;;  * @returns {list|boolean} An IR node, or #f if the body is unsupported.\n;;  */\n(define (lower-body-in node scope st tail)\n  (let ((tag (ast-tag node)))\n    (cond ((eq? tag 'seq) (predeclare-definitions! (ast-1 node) scope))\n          ((eq? tag 'define)\n           (scope-declare! scope (ast-1 node) (eq? (car (ast-2 node)) 'lambda)))\n          (else #f))\n    (lower-node node scope tail st)))\n\n;; /**\n;;  * Declares the internal definitions among a body's expressions.\n;;  * @param {list} exprs - The body's expressions.\n;;  * @param {list} scope - The procedure's scope.\n;;  * @returns {unspecified}\n;;  */\n(define (predeclare-definitions! exprs scope)\n  (if (null? exprs)\n      #f\n      (begin\n        (if (eq? (ast-tag (car exprs)) 'define)\n            (scope-declare! scope (ast-1 (car exprs))\n                            (eq? (car (ast-2 (car exprs))) 'lambda))\n            #f)\n        (predeclare-definitions! (cdr exprs) scope))))\n\n;; /**\n;;  * A lambda lowered: its IR, and what it references.\n;;  * @property {list} ir - The IR.\n;;  * @property {list} globals - The globals it names, as symbols, in the order\n;;  *   first named.\n;;  * @property {list} library-globals - Those that are a library's own\n;;  *   bindings, as (key name . env) (`library-global-key`).\n;;  * @property {boolean} calls-unknown? - Whether it calls a callee the lowering\n;;  *   cannot name.\n;;  * @property {boolean} captures? - Whether it captures a continuation.\n;;  */\n(define-record-type lowered-lambda\n  (make-lowered-lambda ir globals library-globals calls-unknown? captures?)\n  lowered-lambda?\n  (ir lowered-ir)\n  (globals lowered-globals)\n  (library-globals lowered-library-globals)\n  (calls-unknown? lowered-calls-unknown?)\n  (captures? lowered-captures?))\n\n;; /**\n;;  * A global's name as the code it names it in has it: a library's binding\n;;  * known by a key of its own, by the binding's name.\n;;  * @param {list} library-globals - (key name . env) for each library's\n;;  *   binding.\n;;  * @param {symbol} global - The global.\n;;  * @returns {symbol}\n;;  */\n(define (global-written-name library-globals global)\n  (let ((entry (assq global library-globals)))\n    (if entry (cadr entry) global)))\n\n;; /**\n;;  * A lambda the lowering cannot express.\n;;  * @property {string} reason - Why.\n;;  */\n(define-record-type lowering-failure\n  (make-lowering-failure reason)\n  lowering-failure?\n  (reason lowering-failure-reason))\n\n;; /**\n;;  * Lowers a lambda to IR, reporting what it references.\n;;  *\n;;  * Lowering failure and safety are kept apart, because they are different\n;;  * questions. A form the compiler cannot express is a failure, reported as a\n;;  * reason. A form it can express but should not compile is a judgement the\n;;  * caller makes, and needs more than this one lambda to make.\n;;  *\n;;  * @param {list} node - An analyzed lambda node.\n;;  * @returns {lowered-lambda|lowering-failure}\n;;  */\n(define (lower-lambda node)\n  (let ((st (make-state)))\n    (vector-set! st 13 (assigned-names node '()))\n    ;; A top-level procedure is bound to the global its definition names, for\n    ;; as long as nobody redefines it -- which the emitter checks at run time.\n    (if (string? (ast-3 node))\n        (state-pending-self! st 'global (string->symbol (ast-3 node)))\n        #f)\n    (lower-top-lambda node st)))\n\n;; /**\n;;  * The body of `lower-lambda`, once the state is set up.\n;;  * @param {list} node - An analyzed lambda node.\n;;  * @param {vector} st - A fresh lowering state.\n;;  * @returns {lowered-lambda|lowering-failure} As for `lower-lambda`.\n;;  */\n(define (lower-top-lambda node st)\n  (let ((ir (lower-node node (make-scope '()) #f st)))\n    (if ir (confirm-local-loops! st) #f)\n    (if (not ir)\n        (make-lowering-failure (let ((r (state-reason st))) (if r r \"unsupported form\")))\n        ;; A local that was both called and assigned is not the lambda we\n        ;; lowered, so the call does not reach a callee this pass can name.\n        (make-lowered-lambda ir (reverse (state-globals st)) (vector-ref st 12)\n                             (if (state-calls-unknown? st)\n                                 #t\n                                 (any-assigned? (vector-ref st 2) (vector-ref st 3)))\n                             (state-captures? st)))))\n\n;; /**\n;;  * Whether any called local is also assigned.\n;;  * @param {list} called - Locals that were called.\n;;  * @param {list} assigned - Locals that are assigned.\n;;  * @returns {boolean} True if the two lists intersect.\n;;  */\n(define (any-assigned? called assigned)\n  (if (null? called)\n      #f\n      (if (memq (car called) assigned)\n          #t\n          (any-assigned? (cdr called) assigned))))\n\n",
  "lift.scm": ";;; lift.scm -- deciding which nested procedures to emit once, at top level.\n;;;\n;;; ## The problem\n;;;\n;;; A procedure is emitted twice -- a fast form and a resumable one -- and each\n;;; of those used to emit both forms of every procedure nested inside it. So a\n;;; lambda at nesting depth d appeared about 4^d times. Measured, that was 4.2x\n;;; per level: `earley.scm:make-parser` reached 3.6 MB of generated source, and\n;;; `map`, `for-each`, `vector-map` and `string-map` together were a third of the\n;;; compiled standard library's bundle.\n;;;\n;;; ## The fix\n;;;\n;;; Each nested procedure is emitted once, at the top level of the generated\n;;; unit, as a factory taking its free variables:\n;;;\n;;;     function $mk$fn0(s_a, s_b) {\n;;;       function $fn0(s_x) { ... uses s_a, s_b, and $fn0 for recursion ... }\n;;;       function $fn0$r($pc, $f) { ... }\n;;;       $fn0.$resume = $fn0$r;\n;;;       return $fn0;\n;;;     }\n;;;\n;;; and created with `$t5 = $mk$fn0(s_a, s_b)`. Every form of every parent\n;;; shares that one emission, so code size is linear in the program rather than\n;;; exponential in its nesting. Variable *references* do not change, which is\n;;; what makes this cheap: the inner function closes over the factory's\n;;; parameters, and those have the names the body already used.\n;;;\n;;; ## Why free variables can be passed by value\n;;;\n;;; A free variable that is never assigned cannot be observed to differ from a\n;;; copy, so passing it is safe. One that *is* assigned is held in a\n;;; one-element array, so what gets passed is the array, and every reader still\n;;; shares one binding.\n;;;\n;;; ## `letrec`, which is the whole difficulty\n;;;\n;;; A `letrec`-bound lambda refers to names its group is still defining, so\n;;; they cannot be passed by value when it is created -- they have no value yet.\n;;;\n;;; Self-reference needs nothing: the factory declares the name and assigns the\n;;; procedure to it before returning, so the recursive call resolves lexically\n;;; inside the factory. That is the common case and the hot one.\n;;;\n;;; Mutual reference does need indirection, so a name referenced by one of its\n;;; *siblings* is boxed. The boxes exist before any initializer runs and are\n;;; passed to each factory, so the group can refer to itself in any order. Only\n;;; such names pay for it: in `map`, `loop` reads `any-null?`, `all-cars` and\n;;; `all-cdrs`, so those three are boxed while `loop` itself is not.\n\n;; /**\n;;  * What lifting decided about one unit.\n;;  *\n;;  * `free` maps each nested lambda node to its free variables, in the order\n;;  * first seen -- its factory's parameter list, which both forms of its parent\n;;  * must pass in the same order. `boxed` is every local held in a box. `self`\n;;  * maps a `letrec` initializer to the name it binds inside its own factory.\n;;  * Lambda nodes are keys by identity, in association lists: a unit has few.\n;;  */\n(define-record-type lift-plan\n  (make-lift-plan free boxed self)\n  lift-plan?\n  (free plan-free)\n  (boxed plan-boxed)\n  (self plan-self))\n\n;; /**\n;;  * A nested lambda's free variables, which become its factory's parameters.\n;;  * @param {lift-plan} plan - The plan.\n;;  * @param {list} lam - A nested lambda IR node.\n;;  * @returns {list} The names.\n;;  */\n(define (plan-free-of plan lam)\n  (cond ((assq lam (plan-free plan)) => cdr) (else '())))\n\n;; /**\n;;  * The group names a `letrec` initializer binds inside its own factory.\n;;  * @param {lift-plan} plan - The plan.\n;;  * @param {list} lam - A lambda IR node.\n;;  * @returns {list} Its own name, or '().\n;;  */\n(define (plan-self-of plan lam)\n  (cond ((assq lam (plan-self plan)) => cdr) (else '())))\n\n;; /**\n;;  * Whether a local is held in a box.\n;;  * @param {lift-plan} plan - The plan.\n;;  * @param {symbol} name - A renamed local.\n;;  * @returns {boolean}\n;;  */\n(define (boxed? plan name) (memq name (plan-boxed plan)))\n\n;; ---------------------------------------------------------------------------\n;; Walking the IR\n;; ---------------------------------------------------------------------------\n;;\n;; Every walk here goes through `ir-children`, so none can disagree with\n;; another about order. Order matters: a factory lists its parameters in the\n;; order its free variables are first seen, and both forms of its parent pass\n;; them in that order.\n\n;; /**\n;;  * The IR nodes directly inside a node, in the order they are evaluated.\n;;  * @param {list} node - An IR node.\n;;  * @returns {list} Its children.\n;;  */\n(define (ir-children node)\n  (case (car node)\n    ((if) (list (cadr node) (caddr node) (cadddr node)))\n    ((seq) (cadr node))\n    ((lambda) (list (lambda-body node)))\n    ((let) (list (caddr node) (cadddr node)))\n    ((letrec) (append (caddr node) (list (cadddr node))))\n    ((set) (list (cadddr node)))\n    ((define) (list (caddr node)))\n    ((call) (cons (cadr node) (caddr node)))\n    ((capture) (list (cadr node)))\n    (else '())))\n\n(define (lambda-params lam) (cadr lam))\n(define (lambda-rest lam) (caddr lam))\n(define (lambda-name lam) (cadddr lam))\n(define (lambda-body lam) (car (cddddr lam)))\n\n;; /**\n;;  * The names a lambda binds on entry: its parameters and rest parameter.\n;;  * @param {list} lam - A lambda IR node.\n;;  * @returns {list} The names.\n;;  */\n(define (lambda-bound lam)\n  (if (lambda-rest lam)\n      (cons (lambda-rest lam) (lambda-params lam))\n      (lambda-params lam)))\n\n;; /**\n;;  * Every node in a subtree satisfying a predicate, parents before children.\n;;  * @param {procedure} keep? - The predicate.\n;;  * @param {list} node - An IR node.\n;;  * @returns {list} The nodes.\n;;  */\n(define (ir-find keep? node)\n  (let ((below (append-map (lambda (child) (ir-find keep? child)) (ir-children node))))\n    (if (keep? node) (cons node below) below)))\n\n;; /**\n;;  * The lambdas directly inside a subtree: found, but not searched inside,\n;;  * since what they contain belongs to them.\n;;  * @param {list} node - An IR node.\n;;  * @returns {list} The lambda nodes.\n;;  */\n(define (outermost-lambdas node)\n  (if (eq? (car node) 'lambda)\n      (list node)\n      (append-map outermost-lambdas (ir-children node))))\n\n(define (tagged? tag) (lambda (node) (eq? (car node) tag)))\n\n;; /**\n;;  * Whether a subtree reads or assigns a local, nested lambdas included.\n;;  * Names are unique after the expander's renaming, so any mention is a\n;;  * mention of that one binding.\n;;  * @param {list} node - An IR node.\n;;  * @param {symbol} name - A renamed local.\n;;  * @returns {boolean}\n;;  */\n(define (mentions? node name)\n  (case (car node)\n    ((local) (eq? (cadr node) name))\n    ((set) (or (and (caddr node) (eq? (cadr node) name))\n               (mentions? (cadddr node) name)))\n    (else (any (lambda (child) (mentions? child name)) (ir-children node)))))\n\n;; ---------------------------------------------------------------------------\n;; Free variables\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * The locals a lambda reads or assigns without binding, in the order first\n;;  * seen.\n;;  * @param {list} lam - A lambda IR node.\n;;  * @returns {list} Its free variables.\n;;  */\n(define (free-variables lam)\n  (reverse (free-in (lambda-body lam) (lambda-bound lam) '())))\n\n;; /**\n;;  * Adds a subtree's free variables to those found so far.\n;;  *\n;;  * Every internal definition in a body is in scope throughout it, not only\n;;  * after itself -- that is what lets two internal procedures call each other\n;;  * -- so a sequence binds all its definitions before scanning any of its\n;;  * expressions. Binding them in order instead once reported a self-recursive\n;;  * internal definition as free in its own procedure, and left the caller\n;;  * passing a variable it never declared.\n;;  *\n;;  * @param {list} node - An IR node.\n;;  * @param {list} bound - Names bound by enclosing forms.\n;;  * @param {list} found - Free variables so far, most recent first.\n;;  * @returns {list} The free variables, most recent first.\n;;  */\n(define (free-in node bound found)\n  (define (scan-all nodes bound found)\n    (fold (lambda (n acc) (free-in n bound acc)) found nodes))\n  (define (note name)\n    (if (or (memq name bound) (memq name found)) found (cons name found)))\n  (case (car node)\n    ((local) (note (cadr node)))\n    ((set) (free-in (cadddr node) bound (if (caddr node) (note (cadr node)) found)))\n    ((lambda) (free-in (lambda-body node) (append (lambda-bound node) bound) found))\n    ((let) (free-in (cadddr node) (cons (cadr node) bound)\n                    (free-in (caddr node) bound found)))\n    ((letrec) (let ((inner (append (cadr node) bound)))\n                (scan-all (ir-children node) inner found)))\n    ((seq) (let ((inner (append (map cadr (filter (tagged? 'define) (cadr node))) bound)))\n             (scan-all (cadr node) inner found)))\n    (else (scan-all (ir-children node) bound found))))\n\n;; ---------------------------------------------------------------------------\n;; The plan\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * Plans lifting for a lowered procedure.\n;;  *\n;;  * Which nested procedures to lift, what each is passed, and which locals\n;;  * must be shared rather than copied are one question asked three ways, so\n;;  * every reason a local is boxed is decided here.\n;;  *\n;;  * @param {list} ir - The unit's top-level lambda IR node.\n;;  * @returns {lift-plan} The plan.\n;;  */\n(define (plan-lifting ir)\n  (let* ((groups (ir-find (tagged? 'letrec) ir))\n         (boxed (delete-duplicates (append (assigned-locals ir)\n                                           (sibling-references groups)\n                                           (defined-and-captured ir))\n                                   eq?))\n         (self (self-bindings groups boxed)))\n    (make-lift-plan (factory-parameters ir self) boxed self)))\n\n;; /**\n;;  * The locals assigned by `set!` anywhere in a unit.\n;;  *\n;;  * A spilled frame copies each local's value, while Scheme shares the\n;;  * binding: an assignment made after a continuation is captured is seen when\n;;  * that continuation is invoked again, and by every closure over the\n;;  * variable. Copying is right for temporaries, which are always written before\n;;  * they are read, and wrong for a variable the program can name.\n;;  *\n;;  * @param {list} ir - An IR node.\n;;  * @returns {list} The names.\n;;  */\n(define (assigned-locals ir)\n  (map cadr (filter caddr (ir-find (tagged? 'set) ir))))\n\n;; /**\n;;  * The `letrec` names one of their siblings refers to. The sibling is\n;;  * created before the name has a value, so it has to be handed a box.\n;;  * @param {list} groups - Every `letrec` node in the unit.\n;;  * @returns {list} The names.\n;;  */\n(define (sibling-references groups)\n  (append-map\n    (lambda (group)\n      (let ((names (cadr group)) (inits (caddr group)))\n        (filter (lambda (name)\n                  (any (lambda (own init) (and (not (eq? own name)) (mentions? init name)))\n                       names inits))\n                names)))\n    groups))\n\n;; /**\n;;  * The internal definitions a nested procedure refers to.\n;;  *\n;;  * An internal definition has the difficulty a `letrec` group has: its name\n;;  * takes its value when the definition runs, so a procedure created earlier\n;;  * in the same body that refers to it -- the way mutually recursive internal\n;;  * definitions are written -- would capture nothing.\n;;  *\n;;  * @param {list} ir - The unit's top-level lambda.\n;;  * @returns {list} The names.\n;;  */\n(define (defined-and-captured ir)\n  (let ((nested (ir-find (tagged? 'lambda) (lambda-body ir))))\n    (filter (lambda (name) (any (lambda (lam) (mentions? lam name)) nested))\n            (map cadr (ir-find (tagged? 'define) ir)))))\n\n;; /**\n;;  * The name each `letrec` initializer may bind inside its own factory rather\n;;  * than receive: its own, when that is not boxed. A boxed name is shared\n;;  * through its box, so the factory has to be handed the box instead.\n;;  * @param {list} groups - Every `letrec` node in the unit.\n;;  * @param {list} boxed - Every boxed name.\n;;  * @returns {list} Alist from initializer to a list of names.\n;;  */\n(define (self-bindings groups boxed)\n  (append-map\n    (lambda (group)\n      (filter-pairs (lambda (name init)\n                      (and (eq? (car init) 'lambda) (not (memq name boxed))))\n                    (cadr group) (caddr group)))\n    groups))\n\n;; /**\n;;  * `(init . (name))` for each name and initializer that satisfy a predicate.\n;;  * @param {procedure} keep? - Takes a name and its initializer.\n;;  * @param {list} names - Names.\n;;  * @param {list} inits - Their initializers.\n;;  * @returns {list} The alist.\n;;  */\n(define (filter-pairs keep? names inits)\n  (cond ((null? names) '())\n        ((keep? (car names) (car inits))\n         (cons (cons (car inits) (list (car names)))\n               (filter-pairs keep? (cdr names) (cdr inits))))\n        (else (filter-pairs keep? (cdr names) (cdr inits)))))\n\n;; /**\n;;  * Every nested lambda's factory parameters: its free variables, less the\n;;  * name it binds itself.\n;;  * @param {list} lam - A lambda IR node.\n;;  * @param {list} self - The self-binding alist.\n;;  * @returns {list} Alist from lambda node to parameter names.\n;;  */\n(define (factory-parameters lam self)\n  (append-map\n    (lambda (nested)\n      (let ((own (cond ((assq nested self) => cdr) (else '()))))\n        (cons (cons nested (remove (lambda (v) (memq v own)) (free-variables nested)))\n              (factory-parameters nested self))))\n    (outermost-lambdas (lambda-body lam))))\n",
  "liveness.scm": ";;; liveness.scm -- which locals are live where a suspended frame will resume.\n;;;\n;;; When a continuation is captured beneath a compiled procedure, the procedure\n;;; saves its locals into a frame and its resumable form restores them later.\n;;; Saving every local at every suspension point is quadratic -- a procedure\n;;; with n locals and n call sites writes n^2 names -- and measured, frame\n;;; literals were once 57% of all generated code in the benchmark corpus. A\n;;; frame only needs what can still be read after it resumes, and this works\n;;; that out per block of the resumable form, with ordinary backward liveness.\n;;;\n;;; It runs over the twin's statements rather than over the IR because what a\n;;; frame must save includes values the IR has no name for: in\n;;; `(list (one) (capturer))` the result of `(one)` sits in a temporary while\n;;; `(capturer)` runs, and is live across it. The statements are data\n;;; (`emit.scm`), with every local an expression reads marked as a symbol, so\n;;; reads and writes are read off them directly.\n;;;\n;;; Getting it wrong one way loses a value on resume; the other way saves a\n;;; name unnecessarily. So where a statement is only conditionally a write --\n;;; an assignment inside a guarded jump -- it counts as a read and not a write.\n\n;; ---------------------------------------------------------------------------\n;; Sets of locals, as bits\n;; ---------------------------------------------------------------------------\n\n;; Each set is an exact integer with a bit for each local in it (SRFI 151), so\n;; that a union, or what is left once a local is written, is one operation\n;; whatever the sets' sizes. As lists, those were most of the analysis: a large\n;; procedure has hundreds of locals live across its call sites, and a list's\n;; union tests each member of one set against the whole of the other.\n\n;; /**\n;;  * The bit each local of one analysis has, numbered as they are met.\n;;  * @property {weak-table} bits - Each local's bit.\n;;  * @property {integer} count - How many locals are numbered.\n;;  * @property {list} locals - The locals, the last numbered first.\n;;  */\n(define-record-type numbering\n  (make-numbering bits count locals)\n  numbering?\n  (bits numbering-bits)\n  (count numbering-count set-numbering-count!)\n  (locals numbering-locals set-numbering-locals!))\n\n;; /**\n;;  * A local's bit, numbering it if it has none yet.\n;;  * @param {numbering} numbering - The analysis's numbering.\n;;  * @param {symbol} local - The local.\n;;  * @returns {integer} Its bit's index.\n;;  */\n(define (local-bit numbering local)\n  (or (weak-table-ref (numbering-bits numbering) local)\n      (let ((k (numbering-count numbering)))\n        (weak-table-set! (numbering-bits numbering) local k)\n        (set-numbering-count! numbering (+ k 1))\n        (set-numbering-locals! numbering (cons local (numbering-locals numbering)))\n        k)))\n\n;; /**\n;;  * The set of some locals.\n;;  * @param {numbering} numbering - The analysis's numbering.\n;;  * @param {list} locals - The locals, possibly with repeats.\n;;  * @returns {integer} The set.\n;;  */\n(define (set-of numbering locals)\n  (fold (lambda (local set) (bitwise-ior set (arithmetic-shift 1 (local-bit numbering local))))\n        0 locals))\n\n;; /**\n;;  * What a statement does to the set of live locals, going backwards -- its\n;;  * transfer function: the\n;;  * locals still live above it are those live below it that it does not\n;;  * write, with those it reads, and with those live where it spills a frame.\n;;  * @property {integer} keeps - Every local but the one it writes.\n;;  * @property {integer} reads - The locals it reads.\n;;  * @property {integer|boolean} spill - The block it spills a frame for, or #f.\n;;  */\n(define-record-type transfer\n  (make-transfer keeps reads spill)\n  transfer?\n  (keeps transfer-keeps)\n  (reads transfer-reads)\n  (spill transfer-spill))\n\n;; /**\n;;  * A statement's transfer.\n;;  * @param {list} st - The statement.\n;;  * @param {numbering} numbering - The analysis's numbering.\n;;  * @returns {transfer}\n;;  */\n(define (statement-transfer st numbering)\n  (let ((def (statement-def st)))\n    (make-transfer (if def (bitwise-not (arithmetic-shift 1 (local-bit numbering def))) -1)\n                   (set-of numbering (statement-reads st))\n                   (statement-spill st))))\n\n;; ---------------------------------------------------------------------------\n;; The analysis\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * What the analysis found: the locals live on entry to each block.\n;;  * @property {numbering} numbering - Each local's bit.\n;;  * @property {vector} live - For each block, the set live on entry.\n;;  */\n(define-record-type liveness\n  (make-liveness numbering live)\n  liveness?\n  (numbering liveness-numbering)\n  (live liveness-live))\n\n;; /**\n;;  * The locals live on entry to each block of a resumable form.\n;;  *\n;;  * Every symbol a statement names is followed, not only the frame's slots: a\n;;  * nested procedure's statements also name its factory's parameters, which\n;;  * are never written here, so they are live everywhere and harmless, and the\n;;  * caller asks only about the slots when it builds each frame (`live-among`).\n;;  *\n;;  * @param {list} blocks - Each block's statements, in block order; a block's\n;;  *   position is the `$pc` that selects it.\n;;  * @returns {liveness} What is live on entry to each block.\n;;  */\n(define (live-in blocks)\n  (let* ((numbering (make-numbering (make-weak-table) 0 '()))\n         ;; Each block's transfers, last statement first, for going backwards.\n         (code (list->vector\n                 (map (lambda (stmts)\n                        (reverse (map (lambda (st) (statement-transfer st numbering)) stmts)))\n                      blocks)))\n         (n (vector-length code))\n         (successors (list->vector\n                       (map (lambda (stmts i)\n                              (filter (lambda (s) (< s n)) (block-successors stmts i)))\n                            blocks (iota n))))\n         (live (make-vector n 0)))\n    ;; Standard backward dataflow. Each set only grows, so one that has not\n    ;; changed is at its fixed point, and visiting the blocks last-first makes\n    ;; one pass nearly always enough, because the twin mostly jumps forward.\n    (let sweep ()\n      (let ((changed\n             (fold (lambda (i changed)\n                     (let ((entry (block-entry (vector-ref code i)\n                                               (fold (lambda (s set) (bitwise-ior (vector-ref live s) set))\n                                                     0 (vector-ref successors i))\n                                               live)))\n                       (if (= entry (vector-ref live i))\n                           changed\n                           (begin (vector-set! live i entry) #t))))\n                   #f\n                   (reverse (iota n)))))\n        (if changed (sweep) (make-liveness numbering live))))))\n\n;; /**\n;;  * The locals live on entry to a block, given those live on its exit.\n;;  * @param {list} transfers - The block's transfers, last statement first.\n;;  * @param {integer} exit - Locals live on exit.\n;;  * @param {vector} live - Live-in sets so far, for what a spill reads.\n;;  * @returns {integer} Locals live on entry.\n;;  */\n(define (block-entry transfers exit live)\n  (fold (lambda (transfer current)\n          (bitwise-ior (bitwise-and current (transfer-keeps transfer))\n                       (transfer-reads transfer)\n                       (let ((n (transfer-spill transfer))) (if n (vector-ref live n) 0))))\n        exit\n        transfers))\n\n;; /**\n;;  * Those of some locals that are live on entry to a block, in their order.\n;;  * @param {liveness} liveness - The analysis.\n;;  * @param {integer} block - The block.\n;;  * @param {list} locals - The locals asked about.\n;;  * @returns {list} The live ones.\n;;  */\n(define (live-among liveness block locals)\n  (let ((set (vector-ref (liveness-live liveness) block))\n        (bits (numbering-bits (liveness-numbering liveness))))\n    (filter (lambda (local)\n              (let ((bit (weak-table-ref bits local)))\n                (and bit (bit-set? bit set))))\n            locals)))\n\n;; /**\n;;  * Every local live on entry to a block, in the order they were numbered.\n;;  * @param {liveness} liveness - The analysis.\n;;  * @param {integer} block - The block.\n;;  * @returns {list} The live locals.\n;;  */\n(define (live-locals liveness block)\n  (live-among liveness block (reverse (numbering-locals (liveness-numbering liveness)))))\n\n;; /**\n;;  * The local a statement certainly writes: the target of an assignment that\n;;  * is a local on its own. A write through a box reads the box.\n;;  * @param {list} st - A statement.\n;;  * @returns {symbol|boolean} The local, or #f.\n;;  */\n(define (statement-def st)\n  (and (eq? (car st) 'assign)\n       (let ((target (cadr st)))\n         (and (null? (cdr target)) (symbol? (car target)) (car target)))))\n\n;; /**\n;;  * The locals a statement reads.\n;;  * @param {list} st - A statement.\n;;  * @returns {list} The locals, possibly with repeats.\n;;  */\n(define (statement-reads st)\n  (case (car st)\n    ((assign) (append (if (statement-def st) '() (expr-locals (cadr st)))\n                      (expr-locals (caddr st))))\n    ((eval return raw) (expr-locals (cadr st)))\n    ((branch) (expr-locals (cadr st)))\n    ((spill) (if (cadr st) (expr-locals (cadr st)) '()))\n    ;; Conditional, so a write inside it is not certain: everything it names\n    ;; counts as read.\n    ((guarded) (append (expr-locals (cadr st))\n                       (append-map statement-mentions (caddr st))))\n    ((tail) (append (expr-locals (cadr st)) (append-map expr-locals (caddr st))))\n    (else '())))\n\n;; /**\n;;  * Every local a statement names, written or read.\n;;  * @param {list} st - A statement.\n;;  * @returns {list} The locals.\n;;  */\n(define (statement-mentions st)\n  (case (car st)\n    ((assign) (append (expr-locals (cadr st)) (expr-locals (caddr st))))\n    (else (statement-reads st))))\n\n;; /**\n;;  * The block a statement spills a frame for, whose live-in set it reads:\n;;  * the frame is the only way those values reach the code after a capture.\n;;  * @param {list} st - A statement.\n;;  * @returns {integer|boolean} The resume block, or #f.\n;;  */\n(define (statement-spill st)\n  (and (eq? (car st) 'spill) (caddr st)))\n\n;; /**\n;;  * The blocks control can reach after a block: its jumps, and the next block\n;;  * if it may fall through -- which it may unless it ends in a return, a tail\n;;  * call, which returns whichever way it is made, or an unconditional jump.\n;;  * @param {list} stmts - The block's statements.\n;;  * @param {integer} index - The block's own number.\n;;  * @returns {list} Successor block numbers.\n;;  */\n(define (block-successors stmts index)\n  (let ((jumps (append-map statement-jumps stmts))\n        (ends (and (pair? stmts)\n                   (memq (car (list-ref stmts (- (length stmts) 1))) '(return goto branch tail)))))\n    (delete-duplicates (if ends jumps (append jumps (list (+ index 1)))) eqv?)))\n\n;; /**\n;;  * The blocks a statement can jump to.\n;;  * @param {list} st - A statement.\n;;  * @returns {list} Block numbers.\n;;  */\n(define (statement-jumps st)\n  (case (car st)\n    ((goto) (list (cadr st)))\n    ((branch) (list (caddr st) (cadddr st)))\n    ((guarded) (append-map statement-jumps (caddr st)))\n    (else '())))\n",
  "safety.scm": ";; A rule for declining procedures a capture could unwind through, applied\n;; only on request (`decline-captures?`).\n;;\n;; By default every procedure is compiled, those that capture included, and\n;; one whose saved frames continuations keep re-entering is switched back to\n;; its interpreted closure as the program runs (`note-resume` in `tier.scm`).\n;; This rule is what the tier did before that, kept because it measures the\n;; trade-off: it wins where captures are frequent or re-entered -- `btsearch`\n;; 4.5x, `fibc` 1.8x, `ctak` 1.1-1.2x -- and loses where a capture is an escape\n;; taken now and then -- `quicksort` 21x, `puzzle` 4x, `maze` 3.8x, `contfib`\n;; 2.9x, `threads` 1.35x -- which is nearly every capture in real libraries\n;; (docs/corpus_decline_results.md).\n;;\n;; It was once a correctness rule. A compiled procedure's frame could not be\n;; put into a continuation, so a capture beneath one dropped what it had left\n;; to do, and the program got a wrong answer: `btsearch`'s `enumerate`, which\n;; backtracking re-enters, and `maze`'s `make-maze`, which an escape from\n;; `dig-maze` unwinds past. Neither names `call/cc`, which is why the rule\n;; follows the call graph rather than what a procedure names. Compiled frames\n;; save themselves now (src/core/interpreter/unwind.js), so what is left is\n;; the cost of saving and resuming them.\n;;\n;; A procedure is declined if it can reach a control-transferring global or a\n;; capture: itself, through another procedure being decided with it, or\n;; through an interpreted closure already in the environment, which is how a\n;; standard library procedure that captures is found. With `strict?`, one that\n;; calls a procedure it was handed is declined too, since it cannot know what\n;; that does; that was once the only way to catch `btsearch`, where the capture\n;; arrives as an argument, and it declines most higher-order code for it.\n;;\n;; A global rebound after compilation to something that captures is not\n;; caught, and need not be: compiled code calls the new binding, and its\n;; capture is handled like any other.\n\n;; /**\n;;  * What a procedure references, as its lowering reports it.\n;;  * @property {list} globals - The globals it references, as symbols.\n;;  * @property {boolean} calls-unknown? - Whether it calls a callee it cannot\n;;  *   name.\n;;  * @property {list} library-globals - (key name . env) for each global that\n;;  *   is a library's own binding (`library-global-key` in ir.scm).\n;;  * @property {symbol|boolean} control - A control global it names, or #f.\n;;  * @property {boolean} captures? - Whether it captures a continuation.\n;;  */\n(define-record-type facts\n  (make-facts globals library-globals calls-unknown? control captures?)\n  facts?\n  (globals facts-globals)\n  (library-globals facts-library-globals)\n  (calls-unknown? facts-calls-unknown?)\n  (control facts-control)\n  (captures? facts-captures?))\n\n;; /**\n;;  * The facts of a lambda, or #f if it cannot be lowered: a procedure that\n;;  * cannot be vetted is taken to be safe, as every primitive is.\n;;  * @param {list} node - The lambda, as `ir.scm` reads it.\n;;  * @returns {facts|boolean}\n;;  */\n(define (lambda-facts node)\n  (let ((lowered (lower-lambda node)))\n    (and (lowered-lambda? lowered)\n         (let ((globals (lowered-globals lowered))\n               (library-globals (lowered-library-globals lowered)))\n           (make-facts globals library-globals (lowered-calls-unknown? lowered)\n                       (control-global-in globals library-globals) (lowered-captures? lowered))))))\n\n;; /**\n;;  * The facts of an interpreted closure, or #f.\n;;  * @param {procedure} closure - The closure.\n;;  * @param {symbol} name - Its name.\n;;  * @returns {facts|boolean}\n;;  */\n(define (closure-facts closure name)\n  (lambda-facts (closure-lambda closure (symbol->string name))))\n\n;; /**\n;;  * Looks up the facts of whatever an environment binds a name to: an\n;;  * interpreted closure's, and #f for anything else -- a primitive not on the\n;;  * control list, a procedure already compiled, a name not yet bound.\n;;  * @param {object} env - The environment.\n;;  * @returns {procedure} From a name, as a symbol, to facts or #f.\n;;  */\n(define (environment-facts env)\n  (lambda (name)\n    (let ((value (environment-value env (symbol->string name))))\n      (and (interpreted-closure? value) (closure-facts value name)))))\n\n;; /**\n;;  * Decides which of some procedures a capture could unwind through.\n;;  *\n;;  * Outside the procedures being decided, each name is looked into once and\n;;  * the verdict kept, so the standard library is walked once rather than once\n;;  * per reference; a cycle there is not itself evidence.\n;;  *\n;;  * @param {list} local - The procedures being decided, as (name . facts).\n;;  * @param {procedure} external - From a name outside them to its facts, or #f.\n;;  * @param {boolean} strict? - Also decline calling a procedure handed in.\n;;  * @returns {list} Those declined, as (name . reason), in `local`'s order;\n;;  *   each reason a path the reader can follow to a control global.\n;;  */\n(define (unsafe-from-facts local external strict?)\n  (define verdicts '())\n\n  ;; Each library's binding met so far, as (key name . env): one is looked into\n  ;; in the library's environment, not the program's.\n  (define library-globals '())\n\n  (define (note-library-globals! facts)\n    (set! library-globals (append (facts-library-globals facts) library-globals))\n    facts)\n\n  (define (facts-of name)\n    (let ((library (assq name library-globals)))\n      (if library ((environment-facts (cddr library)) (cadr library)) (external name))))\n\n  (define (outside-reason name visiting)\n    (cond\n      ((assq name verdicts) => cdr)\n      ((memq name visiting) #f)\n      (else\n       (let* ((facts (facts-of name))\n              (reason (and facts\n                           (outside-facts-reason name (note-library-globals! facts) (cons name visiting)))))\n         (set! verdicts (cons (cons name reason) verdicts))\n         reason))))\n\n  (define (outside-facts-reason name facts visiting)\n    (let ((label (symbol->string name)))\n      (cond\n        ((facts-control facts)\n         => (lambda (control) (string-append label \" references '\" (symbol->string control) \"'\")))\n        ((facts-captures? facts) (string-append label \" captures a continuation\"))\n        ((and strict? (facts-calls-unknown? facts)) (string-append label \" calls a procedure it is given\"))\n        (else (any (lambda (g)\n                     (let ((inner (outside-reason g visiting)))\n                       (and inner (string-append label \" -> \" inner))))\n                   (facts-globals facts))))))\n\n  (define (own-reason facts)\n    (cond\n      ((facts-control facts)\n       => (lambda (control) (string-append \"references control global '\" (symbol->string control) \"'\")))\n      ((facts-captures? facts) \"captures a continuation, which costs more compiled than interpreted\")\n      ((and strict? (facts-calls-unknown? facts))\n       \"calls a procedure it is given, which may capture a continuation\")\n      (else (any (lambda (g)\n                   (and (not (assq g local))\n                        (let ((reason (outside-reason g '())))\n                          (and reason (string-append \"reaches \" reason)))))\n                 (facts-globals facts)))))\n\n  ;; A caller of a declined procedure is declined, until none is left to add.\n  (define (spread unsafe)\n    (let ((more (filter-map\n                  (lambda (entry)\n                    (and (not (assq (car entry) unsafe))\n                         (let ((callee (find (lambda (g) (assq g unsafe)) (facts-globals (cdr entry)))))\n                           (and callee\n                                (cons (car entry)\n                                      (string-append \"reaches \" (symbol->string callee) \", which \"\n                                                     (cdr (assq callee unsafe))))))))\n                  local)))\n      (if (null? more) unsafe (spread (append unsafe more)))))\n\n  (for-each (lambda (entry) (note-library-globals! (cdr entry))) local)\n  (let ((unsafe (spread (filter-map (lambda (entry)\n                                      (let ((reason (own-reason (cdr entry))))\n                                        (and reason (cons (car entry) reason))))\n                                    local))))\n    (filter-map (lambda (entry) (assq (car entry) unsafe)) local)))\n\n;; /**\n;;  * Decides which of a program's procedure definitions a capture could unwind\n;;  * through.\n;;  * @param {list} forms - The program's analyzed forms, as `ir.scm` reads them.\n;;  * @param {object} env - The environment they are defined into.\n;;  * @param {boolean} strict? - As for `unsafe-from-facts`.\n;;  * @returns {list} Those declined, as (name . reason) with the name a symbol.\n;;  */\n(define (unsafe-definitions forms env strict?)\n  (unsafe-from-facts\n    (filter-map (lambda (form)\n                  (and (procedure-definition? form)\n                       (let ((facts (lambda-facts (ast-2 form))))\n                         (and facts (cons (ast-1 form) facts)))))\n                forms)\n    (environment-facts env)\n    strict?))\n\n;; /**\n;;  * `unsafe-definitions`, for a program's analyzed forms as the interpreter\n;;  * made them.\n;;  * @param {vector} nodes - The forms.\n;;  * @returns {list}\n;;  */\n(define (program-unsafe-definitions nodes env strict?)\n  (unsafe-definitions (map ast->scheme (vector->list nodes)) env strict?))\n\n;; /**\n;;  * Decides which of some interpreted closures a capture could unwind through:\n;;  * the question `unsafe-definitions` asks, for procedures that exist as\n;;  * values, as a library's do once it has loaded.\n;;  * @param {list} closures - The closures, as (name . closure) with the name a\n;;  *   symbol.\n;;  * @param {object} env - The environment they live in.\n;;  * @param {boolean} strict? - As for `unsafe-from-facts`.\n;;  * @returns {list} Those declined, as (name . reason).\n;;  */\n(define (unsafe-closures closures env strict?)\n  (unsafe-from-facts\n    (filter-map (lambda (entry)\n                  (let ((facts (closure-facts (cdr entry) (car entry))))\n                    (and facts (cons (car entry) facts))))\n                closures)\n    (environment-facts env)\n    strict?))\n",
  "sourcemap.scm": ";;; sourcemap.scm -- where generated code came from, for a debugger.\n;;;\n;;; A source map tells a debugger, for each position in a script, the position\n;;; in a source it was generated from (Source Map Revision 3). With one, a\n;;; debugger shows a compiled procedure's frames at their places in its Scheme\n;;; source, and takes a breakpoint set in the source at the code generated\n;;; from it.\n;;;\n;;; The emitter renders a procedure as lines, each carrying the source span of\n;;; the statement it came from, or #f (`emit.scm`); a line maps, from its\n;;; start, to the start of its span. So a frame, which a debugger places at the\n;;; call it is in, shows at the start of the Scheme expression whose code holds\n;;; that call -- a statement's, not the call's own column within it -- and a\n;;; breakpoint set there stops at the line's first statement. A line with no\n;;; span maps nothing.\n;;;\n;;; The map is written into the script itself, as a `data:` URL: a script made\n;;; with `new Function` has no file a map could sit beside. Its JSON goes into\n;;; the URL as it is, not in base 64: a URL's parser percent-encodes what it\n;;; must and a `data:` URL's body is percent-decoded, so only what would end\n;;; the URL or change its meaning is escaped (`url-path-escape`) -- and only a\n;;; file's name can hold any of it.\n\n;; ---------------------------------------------------------------------------\n;; The encoding\n;; ---------------------------------------------------------------------------\n\n(define base64-digits\n  \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\")\n\n;; /**\n;;  * An integer as a base-64 variable-length quantity, as a source map's\n;;  * fields are written: its sign in the lowest bit, then five bits to a digit,\n;;  * least significant first, each digit but the last with its continuation\n;;  * bit, 32, set.\n;;  * @param {integer} n - The integer.\n;;  * @returns {string}\n;;  */\n(define (encode-vlq n)\n  (let loop ((v (if (negative? n) (+ (* -2 n) 1) (* 2 n))) (digits '()))\n    (let ((low (remainder v 32)) (high (quotient v 32)))\n      (if (zero? high)\n          (list->string (reverse (cons (string-ref base64-digits low) digits)))\n          (loop high (cons (string-ref base64-digits (+ low 32)) digits))))))\n\n;; /**\n;;  * The quantities of the integers from -1024 to 1023, each made when first\n;;  * asked for: nearly every field of a map is a small difference, and making\n;;  * them each time was a third of what writing a map cost.\n;;  */\n(define vlq-table (make-vector 2048 #f))\n\n;; /**\n;;  * `encode-vlq`, remembered for the integers `vlq-table` holds.\n;;  * @param {integer} n - The integer.\n;;  * @returns {string}\n;;  */\n(define (vlq n)\n  (if (and (>= n -1024) (< n 1024))\n      (let ((i (+ n 1024)))\n        (or (vector-ref vlq-table i)\n            (let ((text (encode-vlq n)))\n              (vector-set! vlq-table i text)\n              text)))\n      (encode-vlq n)))\n\n;; /**\n;;  * Whether a character would end a URL's path or begin an escape in it, or\n;;  * is a space.\n;;  * @param {char} c - The character.\n;;  * @returns {boolean}\n;;  */\n(define (url-path-special? c)\n  (case c ((#\\% #\\? #\\# #\\space) #t) (else #f)))\n\n;; /**\n;;  * Text escaped for a URL: only the characters `url-path-special?` names, so\n;;  * that a Scheme name stays readable where it can. Most text has none, and is\n;;  * returned as it is.\n;;  * @param {string} text - The text.\n;;  * @returns {string}\n;;  */\n(define (url-path-escape text)\n  (if (string-index text url-path-special?)\n      (string-concatenate\n        (map (lambda (c)\n               (case c\n                 ((#\\%) \"%25\") ((#\\?) \"%3F\") ((#\\#) \"%23\") ((#\\space) \"%20\")\n                 (else (string c))))\n             (string->list text)))\n      text))\n\n;; ---------------------------------------------------------------------------\n;; A map of rendered lines\n;; ---------------------------------------------------------------------------\n\n;; /**\n;;  * The file a span is from, or #f: the reader records `<unknown>` for\n;;  * source it was given no file for.\n;;  * @param {object} span - A source span.\n;;  * @returns {string|boolean}\n;;  */\n(define (span-file span)\n  (let ((file (js-ref span \"filename\")))\n    (and (string? file) (not (string=? file \"<unknown>\")) file)))\n\n;; /**\n;;  * The source map of a script, as JSON, or #f if no line maps anything.\n;;  *\n;;  * Its `mappings` hold, for each line, a segment if the line has a span:\n;;  * the column it maps from, always 0; the index of the span's file in the\n;;  * map's `sources`; and the span's line and column, counted from zero. Lines\n;;  * are separated by `;`, and each field is written as its difference from\n;;  * the same field of the segment before -- the generated column only within\n;;  * its line, so always 0.\n;;  *\n;;  * A file a debugger can fetch by its name it fetches. One it cannot, whose\n;;  * text the caller knows -- a page's inline script -- has the text in the\n;;  * map's `sourcesContent`, and any other file a null beside it. The names and\n;;  * the text are escaped for the URL the map goes into (`source-map-url`),\n;;  * whose reader undoes it.\n;;  *\n;;  * @param {list} spans - Each line's span, or #f, as the emitter renders\n;;  *   them (`render-items` in `emit.scm`).\n;;  * @param {integer} offset - How many lines the script has before the first.\n;;  * @param {procedure} text-of - A file's text, where the map should hold it,\n;;  *   or #f.\n;;  * @returns {string|boolean}\n;;  */\n(define (source-map spans offset text-of)\n  ;; `sources` is newest first, so a file's index in the order first named is\n  ;; the length of what follows it. The mappings are appended to as they go,\n  ;; as `render-items` in `emit.scm` builds its text.\n  (let loop ((spans spans) (first? #t) (mappings (make-string offset #\\;))\n             (sources '()) (source 0) (line 0) (column 0) (previous #f))\n    (if (null? spans)\n        (and (pair? sources)\n             (let* ((files (reverse sources))\n                    (texts (map text-of files))\n                    (json-list (lambda (strings)\n                                 (string-join (map (lambda (s) (if s (url-path-escape (js-string s)) \"null\"))\n                                                   strings)\n                                              \",\"))))\n               ;; The mappings need no quoting: base-64 digits and `;`.\n               (string-append \"{\\\"version\\\":3,\\\"sources\\\":[\" (json-list files) \"]\"\n                              (if (any (lambda (text) text) texts)\n                                  (string-append \",\\\"sourcesContent\\\":[\" (json-list texts) \"]\")\n                                  \"\")\n                              \",\\\"names\\\":[],\\\"mappings\\\":\\\"\" mappings \"\\\"}\")))\n        (let* ((span (car spans))\n               (mappings (if first? mappings (string-append mappings \";\"))))\n          (cond\n            ;; The span of the line before -- the lines of a statement, or\n            ;; the statements of one call -- maps where it did: every field\n            ;; the same.\n            ((and span (eq? span previous))\n             (loop (cdr spans) #f (string-append mappings \"AAAA\") sources source line column span))\n            ((not (and span (span-file span)))\n             (loop (cdr spans) #f mappings sources source line column previous))\n            (else\n             (let* ((file (span-file span))\n                    (sources (if (member file sources) sources (cons file sources)))\n                    (index (- (length (member file sources)) 1))\n                    (span-line (- (js-ref span \"line\") 1))\n                    (span-column (- (js-ref span \"column\") 1)))\n               (loop (cdr spans) #f\n                     (string-append mappings \"A\" (vlq (- index source))\n                                    (vlq (- span-line line)) (vlq (- span-column column)))\n                     sources index span-line span-column span))))))))\n\n;; /**\n;;  * A source map as a URL a script can name its map by, in a\n;;  * `//# sourceMappingURL=` comment.\n;;  * @param {string} json - The map, from `source-map`.\n;;  * @returns {string}\n;;  */\n(define (source-map-url json)\n  (string-append \"data:application/json;charset=utf-8,\" json))\n",
  "tier.scm": ";; Compiling a program's own code as it runs.\n;;\n;; The standard library is compiled at build time; a program's own procedures\n;; are compiled by a tier attached to its interpreter (src/compiler/tiering.js\n;; attaches it). The interpreter tells the tier two things -- a closure has\n;; been bound to a top-level name, by `define` or `set!`, and a waiting\n;; closure's calls have run out -- and asks it one: whether to run a top-level\n;; form compiled. This file answers. The interpreter holds the tier's record\n;; and calls the procedure in it for each, directly, with compiled frames kept\n;; from moving (`callSchemeProcedure` in src/core/interpreter/values.js): so\n;; the tier's Scheme runs compiled, or in the compiler's own interpreter, and\n;; never where the program's debugger could pause it.\n;;\n;; ## When\n;;\n;; Generating a procedure's code costs about a millisecond, so compiling every\n;; definition as it is made would cost a page with five hundred of them half a\n;; second before anything ran, much of it for code run once. So:\n;;\n;;  - A top-level procedure whose body loops or makes procedures is compiled\n;;    when it is bound. A loop inside a procedure called once is where a\n;;    program spends its time, and a count of calls could never catch it.\n;;  - Any other is compiled on its second call, so a procedure called once is\n;;    never compiled.\n;;  - A top-level expression is compiled only if it loops.\n;;\n;; Switching needs no on-stack replacement. Both tiers look a top-level name up\n;; at every call, so once the compiled procedure is bound, the next call -- a\n;; recursive call below frames already made, or the next iteration of a loop\n;; written as a tail call -- runs compiled, and the frames already made finish\n;; interpreted. A procedure nested in a top-level one is compiled with it.\n;;\n;; ## Over the closure, for the debugger\n;;\n;; Each procedure is compiled from the interpreted closure the program made,\n;; and the pair is recorded, so that while the program is being debugged it\n;; runs as that closure again and its breakpoints fire, as the standard\n;; library's do. Nothing is compiled while the program is being debugged; a\n;; procedure that would have been is compiled on its first call after.\n;;\n;; Nor while a library is being loaded: the compiler's own definitions would\n;; be registered with the scopes that library's macros resolve their free\n;; identifiers through. So a library's procedures wait for calls once it has\n;; loaded, however they loop -- ten, since most of what a library defines is\n;; not hot in any one program (`library-calls-before-compiling`). An expression compiled\n;; as a thunk has no closure to go back to, which is why only loops are: a\n;; procedure such a loop makes and keeps stays compiled while debugging.\n\n;; /**\n;;  * How many calls a procedure that neither loops nor makes procedures waits\n;;  * before it is compiled. A variable, so that `benchmarks/run_tier.js` can\n;;  * measure another count.\n;;  * @type {integer}\n;;  */\n(define calls-before-compiling 2)\n\n;; /**\n;;  * Whether a top-level procedure is compiled as soon as it is bound rather\n;;  * than after `calls-before-compiling` calls: when its body loops or makes\n;;  * procedures. A procedure of its own, like the count a variable, so that\n;;  * `benchmarks/run_tier.js` can measure another rule in its place.\n;;  * @param {list} body - The procedure's analyzed body.\n;;  * @returns {boolean}\n;;  */\n(define (compiled-when-bound? body) (makes-procedures-or-loops? body))\n\n;; /**\n;;  * How many calls a procedure a library defines waits, once the library has\n;;  * loaded, before it is compiled, however it loops: compiling waits while a\n;;  * library loads (see the notes at the head of this file), and the call that\n;;  * finds it due runs interpreted either way.\n;;  *\n;;  * Ten, measured over the test programs of 22 libraries that are not\n;;  * shipped (`benchmarks/run_tier.js --set corpus`): compiled at their first\n;;  * call, as they were, 21 of the programs ran slower with the tier than\n;;  * without, compiling half the time; at their tenth, 28% faster, none more\n;;  * than 15% slower. At their hundredth they ran faster still, but a program\n;;  * whose library's loops were hot ran 31% slower. Keeping the program's own\n;;  * rule, compiling at the first call what loops or makes procedures, kept\n;;  * only 5-7%: most procedures a library defines do one or the other. A\n;;  * variable, so that `benchmarks/run_tier.js` can measure another count.\n;;  * @type {integer}\n;;  */\n(define library-calls-before-compiling 10)\n\n;; /**\n;;  * The compiler tier of one program.\n;;  * @property {object} interpreter - The program's interpreter.\n;;  * @property {object} env - The program's global environment.\n;;  * @property {procedure} prebuilt? - From a library's name to whether its\n;;  *   procedures are compiled at build time, and so are not the tier's.\n;;  * @property {boolean} decline-captures? - Decline what a capture could unwind\n;;  *   through (`safety.scm`), as the tier once did.\n;;  * @property {object} waiting - Each closure waiting to be compiled, weakly,\n;;  *   mapped to (name . environment) for the binding it waits under.\n;;  * @property {object} outcomes - A JavaScript `Map` from each name the tier\n;;  *   tried to \"compiled\" or why not, for whoever attached it to read.\n;;  * @property {integer} expressions - How many top-level forms it compiled.\n;;  * @property {procedure} bound - What the interpreter calls when a closure is\n;;  *   bound to a top-level name: `tier-bound!` on this tier.\n;;  * @property {procedure} due - What it calls when a waiting closure's calls\n;;  *   have run out: `tier-due!` on this tier.\n;;  * @property {procedure} form - What it asks for each top-level form, and its\n;;  *   environment: `tier-top-level-procedure` on this tier.\n;;  */\n(define-record-type tier\n  (make-tier-record interpreter env prebuilt? decline-captures? waiting outcomes expressions\n                    bound due form)\n  tier?\n  (interpreter tier-interpreter)\n  (env tier-env)\n  (prebuilt? tier-prebuilt-test)\n  (decline-captures? tier-declines-captures?)\n  (waiting tier-waiting)\n  (outcomes tier-outcomes)\n  (expressions tier-expressions set-tier-expressions!)\n  (bound tier-bound-hook)\n  (due tier-due-hook)\n  (form tier-form-hook))\n\n;; /**\n;;  * Makes a program's tier, and takes on the procedures the program has\n;;  * already bound at top level as if they were bound now.\n;;  * @param {object} interpreter - The program's interpreter.\n;;  * @param {object} env - Its global environment.\n;;  * @param {procedure} prebuilt? - As for the record.\n;;  * @param {boolean} decline-captures? - As for the record.\n;;  * @param {object} outcomes - As for the record.\n;;  * @returns {tier|boolean} The tier, or #f if code cannot be generated here --\n;;  *   a Content-Security-Policy forbids it -- and the program runs interpreted.\n;;  */\n(define (make-tier interpreter env prebuilt? decline-captures? outcomes)\n  (and (code-generation-allowed?)\n       (letrec ((tier (make-tier-record\n                       interpreter env prebuilt? decline-captures? (make-weak-table) outcomes 0\n                       (lambda (name closure env) (tier-bound! tier name closure env))\n                       (lambda (closure) (tier-due! tier closure))\n                       (lambda (node env) (tier-top-level-procedure tier node env)))))\n         (for-each (lambda (binding)\n                     (let ((value (cdr binding)))\n                       (if (and (interpreted-closure? value) (programs-own? value env))\n                           (tier-bound! tier (car binding) value env))))\n                   (environment-bindings env))\n         tier)))\n\n;; /**\n;;  * Whether a closure is a program's own: made in its global environment or a\n;;  * scope inside it, and not inside a library's, whose environment is inside\n;;  * the global one too.\n;;  * @param {procedure} closure - An interpreted closure.\n;;  * @param {object} env - The program's global environment.\n;;  * @returns {boolean}\n;;  */\n(define (programs-own? closure env)\n  (let walk ((scope (closure-environment closure)))\n    (and scope\n         (or (eq? scope env)\n             (and (not (environment-library scope)) (walk (environment-parent scope)))))))\n\n;; /**\n;;  * Whether an environment is a program's top level: the global environment\n;;  * the tier was attached to, or one of import sets alone that is not a\n;;  * library's -- a program's that began with import declarations, which sees\n;;  * only them, or one `environment` made.\n;;  * @param {tier} tier - The tier.\n;;  * @param {object} env - The environment.\n;;  * @returns {boolean}\n;;  */\n(define (program-environment? tier env)\n  (or (eq? env (tier-env tier))\n      (and (environment-strict? env) (not (environment-library env)))))\n\n;; /**\n;;  * Whether the procedures an environment binds at top level are the tier's:\n;;  * the program's own, or those of a library the program loaded that has no\n;;  * prebuilt table.\n;;  * @param {tier} tier - The tier.\n;;  * @param {object|boolean} env - The environment binding a name, or #f.\n;;  * @returns {boolean}\n;;  */\n(define (tier-manages? tier env)\n  (and env\n       (or (program-environment? tier env)\n           (let ((library (environment-library env)))\n             (and library (not ((tier-prebuilt-test tier) library)))))))\n\n;; /**\n;;  * Whether compiling must wait: while the program is being debugged, or a\n;;  * library is being loaded.\n;;  * @param {tier} tier - The tier.\n;;  * @returns {boolean}\n;;  */\n(define (tier-deferring? tier)\n  (or (debugging? (tier-interpreter tier)) (library-loading?)))\n\n;; /**\n;;  * A closure has been bound to a top-level name: compiled now if its body\n;;  * loops or makes procedures, and set to wait for its second call otherwise.\n;;  * @param {tier} tier - The tier.\n;;  * @param {string} name - The name.\n;;  * @param {procedure} closure - The closure.\n;;  * @param {object|boolean} env - The environment that binds the name, or #f.\n;;  */\n(define (tier-bound! tier name closure env)\n  (when (tier-manages? tier env)\n    (weak-table-set! (tier-waiting tier) closure (cons name env))\n    (cond ((debugging? (tier-interpreter tier)) (wait-calls! closure 1))\n          ((library-loading?) (wait-calls! closure library-calls-before-compiling))\n          ((compiled-when-bound? (closure-body closure)) (tier-compile! tier closure))\n          (else (wait-calls! closure calls-before-compiling)))))\n\n;; /**\n;;  * A waiting closure's calls have run out. While compiling must wait, it\n;;  * waits for one more call.\n;;  * @param {tier} tier - The tier.\n;;  * @param {procedure} closure - The closure.\n;;  */\n(define (tier-due! tier closure)\n  (if (tier-deferring? tier)\n      (wait-calls! closure 1)\n      (tier-compile! tier closure)))\n\n;; /**\n;;  * Compiles a waiting closure and binds the compiled procedure in its place,\n;;  * if its name still holds it and the compiler accepts it, recording the\n;;  * outcome under the name.\n;;  * @param {tier} tier - The tier.\n;;  * @param {procedure} closure - The closure.\n;;  */\n(define (tier-compile! tier closure)\n  (let ((entry (weak-table-ref (tier-waiting tier) closure)))\n    (weak-table-delete! (tier-waiting tier) closure)\n    (wait-calls! closure 0)\n    ;; A name rebound since belongs to another closure, with its own count.\n    (when (and entry (eq? (environment-value (cdr entry) (car entry)) closure))\n      (let* ((name (car entry))\n             (env (cdr entry))\n             (outcome (compile-waiting tier closure name env)))\n        (when (compiled? outcome) (install-compiled! tier closure (compiled-procedure outcome) name env))\n        (js-invoke (tier-outcomes tier) \"set\" name\n                   (if (compiled? outcome) \"compiled\" (declined-reason outcome)))))))\n\n;; /**\n;;  * Compiles a closure the tier was waiting on: over the closure, and captures\n;;  * included unless the tier declines them. One whose continuations are\n;;  * re-entered over and over is switched back as the program runs\n;;  * (`note-resume`).\n;;  * @returns {compiled|declined}\n;;  */\n(define (compile-waiting tier closure name env)\n  (let ((ruled-out (and (tier-declines-captures? tier)\n                        (unsafe-closures (list (cons (string->symbol name) closure)) env #f))))\n    (if (pair? ruled-out)\n        (make-declined name (cdar ruled-out) #f)\n        (compile-closure closure name (tier-declines-captures? tier)))))\n\n;; /**\n;;  * Makes a closure run as what it compiled to, staying the object every\n;;  * holder of it has -- the name that binds it, any other name, a library\n;;  * that imported it, the program's data -- and records it for a debugger.\n;;  * @param {tier} tier - The tier.\n;;  * @param {procedure} closure - The closure.\n;;  * @param {procedure} procedure - What it compiled to.\n;;  * @param {string} name - The name that binds it.\n;;  * @param {object} env - The environment that binds it.\n;;  */\n(define (install-compiled! tier closure procedure name env)\n  (run-compiled! closure procedure)\n  (record-compiled-over! (list (cons closure procedure)) (tier-env tier)))\n\n;; /**\n;;  * The compiled procedure to run a top-level form as, or #f to interpret it.\n;;  *\n;;  * Only a form that loops. One that only makes procedures is interpreted: the\n;;  * procedures it binds are compiled when bound, over their closures, and one\n;;  * it makes and keeps elsewhere would, compiled here, have no closure for a\n;;  * debugger to go back to. Definitions run interpreted, which is where the\n;;  * tier sees what they bind.\n;;  *\n;;  * @param {tier} tier - The tier.\n;;  * @param {object} node - The analyzed form.\n;;  * @param {object} env - The environment it is to run in.\n;;  * @returns {procedure|boolean} A thunk, or #f.\n;;  */\n(define (tier-top-level-procedure tier node env)\n  (and (program-environment? tier env)\n       (not (tier-deferring? tier))\n       (let ((form (ast->scheme node)))\n         (and (not (defines-at-top-level? form))\n              (contains-loop? form)\n              (let ((outcome (compile-expression-form form env (ast-span node) #f\n                                                      (tier-declines-captures? tier))))\n                (and (compiled? outcome)\n                     (begin\n                       (set-tier-expressions! tier (+ (tier-expressions tier) 1))\n                       (compiled-procedure outcome))))))))\n\n;; ---------------------------------------------------------------------------\n;; Procedures whose saved frames are re-entered\n;; ---------------------------------------------------------------------------\n;;\n;; A procedure is compiled whether or not a continuation may be captured\n;; through it: nearly every capture in real code is an escape, taken now and\n;; then, and each saved frame is resumed once, which compiled code pays for\n;; easily. What costs more compiled than interpreted is a continuation\n;; re-entered over and over, as a backtracking search re-enters its choice\n;; points: every re-entry resumes each compiled frame in it through its\n;; resumable form. So the runtime counts each procedure's frames as they are\n;; saved and as they are resumed (src/core/interpreter/unwind.js), and asks\n;; here whether to switch the procedure back for good to the interpreted\n;; closure it was compiled from -- and, when not, at which resume to ask\n;; again, since a frame is resumed at almost every call in some programs and\n;; the question need not be asked that often.\n;;\n;; The thresholds are set by the programs that capture: `btsearch` resumes its\n;; frames 200 times for each save, and every program for which compiling its\n;; captures pays -- `quicksort`, `puzzle`, `maze`, `contfib`, `threads` --\n;; exactly once. A frame moved to the heap to make room on the JavaScript\n;; stack is saved and resumed once too, so deep recursion is not mistaken for\n;; re-entry.\n\n;; /**\n;;  * How many resumes a procedure's frames take before it may be switched back:\n;;  * enough that a few re-entries of one continuation do not do it.\n;;  * @type {integer}\n;;  */\n(define reentry-minimum 1024)\n\n;; /**\n;;  * How many resumes per save mark a procedure's frames as re-entered.\n;;  * @type {integer}\n;;  */\n(define reentry-ratio 4)\n\n;; /**\n;;  * Whether a procedure's frames are re-entered, from how often they have been\n;;  * saved and resumed.\n;;  * @param {number} saved - Saves.\n;;  * @param {number} resumed - Resumes.\n;;  * @returns {boolean}\n;;  */\n(define (re-entered? saved resumed)\n  (and (>= resumed reentry-minimum) (>= resumed (* reentry-ratio saved))))\n\n;; /**\n;;  * The first resume at which a procedure not yet re-entered could be. Saves\n;;  * only grow, so its frames cannot count as re-entered before their resumes\n;;  * reach both the minimum and the ratio times the saves so far.\n;;  * @param {number} saved - Saves so far.\n;;  * @param {number} resumed - Resumes so far.\n;;  * @returns {number}\n;;  */\n(define (next-resume-to-ask saved resumed)\n  (max (+ resumed 1) reentry-minimum (* reentry-ratio saved)))\n\n;; /**\n;;  * The first resume at which to ask about a procedure.\n;;  * @returns {number}\n;;  */\n(define (first-resume-to-ask) (next-resume-to-ask 0 0))\n\n;; /**\n;;  * A procedure's saved frame is being resumed: switches the procedure back if\n;;  * its frames are re-entered.\n;;  * @param {procedure} twin - The procedure's resumable form, which the frame\n;;  *   carries.\n;;  * @param {number} saved - Its frames' saves so far.\n;;  * @param {number} resumed - Their resumes, this one included.\n;;  * @returns {boolean|number} #t if it was judged re-entered, whether or not\n;;  *   there was a closure to switch back to, after which the runtime does not\n;;  *   ask again; otherwise the resume at which to ask next.\n;;  */\n(define (note-resume twin saved resumed)\n  (if (re-entered? saved resumed)\n      (begin (switch-back-to-closure! twin) #t)\n      (next-resume-to-ask saved resumed)))\n"
};
